-- 0304: A quantity kind has a vocabulary.
--
-- QUDT was cited in four places and seeded in none. The five BMS example readings carried a QUDT
-- quantity kind typed by hand, Add Metric's picker could not offer one, an AAS export left every
-- IEC 61360 `unitId` empty, and i3X filed a kind's id in the local namespace. QUDT's own vocabulary
-- files are CC BY 4.0, which asks for attribution to QUDT.org and permits redistribution, so they are
-- kept in the repository and the rows are generated from them as the other vocabularies' are.
--
--   * qudt_quantity_kinds: every quantity kind QUDT 3.5.2 does not deprecate, 1126 of them
--     (`Temperature`, `VolumeFlowRate`), each with its English label and its description as plain
--     text, NULL where QUDT gives none in English. A kind names what a reading measures, not the
--     reading, so no metric group and no `standard` is registered for it: a metric stays MTConnect's,
--     OPC UA's or Custom, and takes a kind as its semantic id only where no other standard names it.
--   * qudt_units: the 83 QUDT units that MTConnect's unit names map to, each with its label, its symbol
--     and its UN/ECE Recommendation 20 code. The export reads the map itself from a TypeScript module
--     generated from scripts/vocabularies/mtconnect-units-to-qudt.json, so no query is added to it; the
--     table holds the units that map reaches, and the check keeps the two in step.
--   * The rows are generated from the two files in scripts/vocabularies/, which are QUDT's
--     VOCAB_QUDT-QUANTITY-KINDS-ALL.ttl and VOCAB_QUDT-UNITS-ALL.ttl at tag v3.5.2, pinned by SHA-256.
--     scripts/generate-qudt-vocabulary.mjs writes the two blocks below and the module the exporter reads,
--     and scripts/check-qudt-seed-sync.mjs checks them. The Turtle reader is scripts/lib/turtle.mjs,
--     which the ASHRAE 223P generator shares.
--   * The ids are QUDT's own, http://qudt.org/vocab/quantitykind/<Name> and .../unit/<Name>, so a CHECK
--     on each table admits no other prefix.
--   * concept_definitions is declared again with a QUDT arm between ASHRAE 223P and OPC UA, so an export
--     defines a quantity kind by QUDT's text instead of "Temperature, as QUDT defines it." The view's
--     columns do not change, so its grants and security_invoker stay. (A view, so not a `-- Redefines`
--     line: those mark functions.) 0302 declared it with six arms; this file declares the whole set.
--
-- ⚠ VERIFY. Read from QUDT's release v3.5.2 (2026-09-22); nothing here was typed from QUDT's website.
-- The file declares its own licence (`dcterms:rights`, CC BY 4.0, attribution to QUDT.org). The kinds
-- file holds 1225 `quantitykind:` subjects, one of them a stub with a wikidata match and no type or
-- label, so 1224 are quantity kinds, 98 of them deprecated. The units file holds 2932 units, 85
-- deprecated. The units file also carries a UCUM notice in its metadata, which applies to the UCUM
-- codes: none is taken. A description is QUDT's `qudt:plainTextDescription`, else its
-- `dcterms:description`, in English, with its LaTeX written out (`$\textit{Absolute Humidity}$` is
-- `Absolute Humidity`) and whitespace collapsed; 171 kinds have none and their description is NULL.
-- 122 of QUDT's plain-text descriptions are German: each of those kinds also has an English
-- `dcterms:description`, and that is the one taken. Each MTConnect unit name was matched to a QUDT unit
-- one by one: the crosswalk maps a name only where QUDT has exactly that unit, and 17 of the 100 names
-- map to nothing, each with its reason beside it.
--
-- Reasoning: supabase/README.md, "A quantity kind has a vocabulary (0304)". Idempotent.

-- -------------------------------------------------------------------------------------------------
-- 1. The tables
-- -------------------------------------------------------------------------------------------------
-- Reference data, as ashrae223_vocabulary and vda5050_vocabulary are: a row is a term QUDT defines,
-- not a metric a device publishes. Keyed on the IRI, which QUDT issues and which no two kinds share
-- (their English labels can repeat: `Volume` is the label of two).
CREATE TABLE IF NOT EXISTS public.qudt_quantity_kinds (
    semantic_id text NOT NULL,
    name text NOT NULL,
    description text,
    CONSTRAINT qudt_quantity_kinds_pkey PRIMARY KEY (semantic_id),
    -- Every id is QUDT's. One minted here would assert a standing QUDT never gave it.
    CONSTRAINT qudt_quantity_kinds_semantic_id_namespace
        CHECK ((semantic_id ~~ 'http://qudt.org/vocab/quantitykind/%'::text))
);

CREATE TABLE IF NOT EXISTS public.qudt_units (
    semantic_id text NOT NULL,
    name text NOT NULL,
    symbol text,
    unece_code text,
    CONSTRAINT qudt_units_pkey PRIMARY KEY (semantic_id),
    CONSTRAINT qudt_units_semantic_id_namespace
        CHECK ((semantic_id ~~ 'http://qudt.org/vocab/unit/%'::text))
);

ALTER TABLE public.qudt_quantity_kinds OWNER TO postgres;
ALTER TABLE public.qudt_quantity_kinds ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qudt_units OWNER TO postgres;
ALTER TABLE public.qudt_units ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.qudt_quantity_kinds IS
  'The quantity kinds QUDT 3.5.2 does not deprecate, generated from its vocabulary file (CC BY 4.0, '
  'attribution to QUDT.org). Reference data, not deployment state: a row is a term QUDT defines. '
  'A kind names what a reading measures, not the reading, so a metric takes one as its semantic id '
  'only where no other standard names it (0304).';
COMMENT ON COLUMN public.qudt_quantity_kinds.semantic_id IS
  'QUDT''s own IRI for the kind, http://qudt.org/vocab/quantitykind/<Name>. Issued by QUDT, not minted here (0304).';
COMMENT ON COLUMN public.qudt_quantity_kinds.name IS
  'The English label. Two kinds can share one, so the IRI is the key (0304).';
COMMENT ON COLUMN public.qudt_quantity_kinds.description IS
  'QUDT''s description as plain text, in English: its plain-text description, else its description with '
  'the LaTeX written out. NULL where QUDT gives none, so an export falls back as for an id no '
  'vocabulary defines (0304).';

COMMENT ON TABLE public.qudt_units IS
  'The QUDT 3.5.2 units that MTConnect''s unit names map to (scripts/vocabularies/mtconnect-units-to-qudt.json), '
  'generated from QUDT''s unit file (CC BY 4.0, attribution to QUDT.org). Not all of QUDT''s 2932: the '
  'export sets a metric''s IEC 61360 unitId to one of these (0304).';
COMMENT ON COLUMN public.qudt_units.semantic_id IS
  'QUDT''s own IRI for the unit, http://qudt.org/vocab/unit/<Name>. Issued by QUDT, not minted here (0304).';
COMMENT ON COLUMN public.qudt_units.name IS 'The English label (0304).';
COMMENT ON COLUMN public.qudt_units.symbol IS 'QUDT''s symbol for the unit, NULL where it gives none (0304).';
COMMENT ON COLUMN public.qudt_units.unece_code IS
  'The UN/ECE Recommendation 20 code QUDT gives the unit (MTR, CEL), the first where it gives two; NULL where it gives none (0304).';

-- Anyone signed in reads them. Nobody writes them: the generated rows below are the only writer, and
-- run as the owner. anon is revoked by name.
REVOKE ALL ON TABLE public.qudt_quantity_kinds FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.qudt_quantity_kinds TO authenticated, service_role;
REVOKE ALL ON TABLE public.qudt_units FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.qudt_units TO authenticated, service_role;

SELECT public.replay_policy('public.qudt_quantity_kinds', 'qudt_quantity_kinds_select_authenticated', $ddl$
CREATE POLICY qudt_quantity_kinds_select_authenticated ON public.qudt_quantity_kinds FOR SELECT TO authenticated USING (true);
$ddl$);
SELECT public.replay_policy('public.qudt_units', 'qudt_units_select_authenticated', $ddl$
CREATE POLICY qudt_units_select_authenticated ON public.qudt_units FOR SELECT TO authenticated USING (true);
$ddl$);

-- -------------------------------------------------------------------------------------------------
-- 2. The quantity kinds
-- -------------------------------------------------------------------------------------------------
-- >>> BEGIN GENERATED qudt_quantity_kinds -- QUDT 3.5.2, 1126 rows, sha256:861707339f529100
-- GENERATED by scripts/generate-qudt-vocabulary.mjs from scripts/vocabularies/qudt-3.5.2-quantity-kinds.ttl.
-- Do not edit these rows by hand: change the script and re-run it. CI verifies the digest above.
ON CONFLICT (semantic_id) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description
 WHERE (qudt_quantity_kinds.name, qudt_quantity_kinds.description)
       IS DISTINCT FROM (EXCLUDED.name, EXCLUDED.description);
-- <<< END GENERATED qudt_quantity_kinds

-- -------------------------------------------------------------------------------------------------
-- 3. The units MTConnect's names map to
-- -------------------------------------------------------------------------------------------------
-- >>> BEGIN GENERATED qudt_units -- QUDT 3.5.2, 83 rows, sha256:2b95573d66bcafef
-- GENERATED by scripts/generate-qudt-vocabulary.mjs from scripts/vocabularies/qudt-3.5.2-units.ttl, taking the units scripts/vocabularies/mtconnect-units-to-qudt.json reaches.
-- Do not edit these rows by hand: change the script and re-run it. CI verifies the digest above.
ON CONFLICT (semantic_id) DO UPDATE SET
  name = EXCLUDED.name,
  symbol = EXCLUDED.symbol,
  unece_code = EXCLUDED.unece_code
 WHERE (qudt_units.name, qudt_units.symbol, qudt_units.unece_code)
       IS DISTINCT FROM (EXCLUDED.name, EXCLUDED.symbol, EXCLUDED.unece_code);
-- <<< END GENERATED qudt_units

-- -------------------------------------------------------------------------------------------------
-- 4. The view
-- -------------------------------------------------------------------------------------------------
-- 0302's view with a QUDT arm. An id held by two vocabularies takes the first in this order: IDTA
-- (issued by IDTA, IEC CDD and ECLASS), ASHRAE 223P and QUDT (each issuing its own IRIs), OPC UA
-- (derived from a published namespace), then ISO 22400, MTConnect and VDA 5050 (minted under
-- aber.local). QUDT sits after 223P because 223P is the narrower, standard-specific source and no id
-- is in both. Within one vocabulary, the first by its key. A row with no text defines nothing, so it
-- is left out and the exporter falls back as it would for an id no vocabulary holds.
CREATE OR REPLACE VIEW public.concept_definitions WITH (security_invoker='true') AS
 SELECT DISTINCT ON (c.semantic_id)
    c.semantic_id,
    c.name,
    c.definition,
    c.standard
   FROM ( SELECT 1 AS precedence, t.template_id || ' ' || t.id_short AS tiebreak,
            t.semantic_id, t.id_short AS name, t.description AS definition, 'IDTA'::text AS standard
           FROM public.idta_submodel_templates t
        UNION ALL
         SELECT 2, v.name, v.semantic_id, v.name, v.description, 'ASHRAE 223P'::text
           FROM public.ashrae223_vocabulary v
        UNION ALL
         SELECT 3, v.semantic_id, v.semantic_id, v.name, v.description, 'QUDT'::text
           FROM public.qudt_quantity_kinds v
        UNION ALL
         SELECT 4, v.companion_spec || ' ' || v.name, v.semantic_id, v.name, v.description,
            'OPC UA'::text
           FROM public.opcua_vocabulary v
        UNION ALL
         SELECT 5, v.name, v.semantic_id, v.name, v.description, 'ISO 22400'::text
           FROM public.iso22400_vocabulary v
        UNION ALL
         SELECT 6, v.kind || ' ' || v.name, v.semantic_id, v.name, v.description, 'MTConnect'::text
           FROM public.mtconnect_vocabulary v
        UNION ALL
         SELECT 7, v.name, v.semantic_id, v.name, v.description, 'VDA 5050'::text
           FROM public.vda5050_vocabulary v) c
  WHERE (NULLIF(btrim(c.semantic_id), '') IS NOT NULL)
    AND (NULLIF(btrim(c.definition), '') IS NOT NULL)
  ORDER BY c.semantic_id, c.precedence, c.tiebreak;

ALTER VIEW public.concept_definitions OWNER TO postgres;

COMMENT ON VIEW public.concept_definitions IS 'One row per semantic id a vocabulary defines: the concept''s name and its vocabulary''s own definition text. IDTA, ASHRAE 223P, QUDT, OPC UA, ISO 22400, MTConnect and VDA 5050. An id held by two vocabularies takes the first in that order. The AAS exporter reads it for ConceptDescription definitions.';

-- Reference data, read as the vocabularies are: security_invoker applies their SELECT policies to
-- the caller, so aas-api's caller-bound client reads it as itself.
REVOKE ALL ON TABLE public.concept_definitions FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.concept_definitions TO authenticated, service_role;

-- -------------------------------------------------------------------------------------------------
-- What this file did, and nothing wider.
-- -------------------------------------------------------------------------------------------------
DO $check$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.oid = 'public.qudt_quantity_kinds'::regclass AND c.relrowsecurity) THEN
    RAISE EXCEPTION '0304: row security is off on qudt_quantity_kinds';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.oid = 'public.qudt_units'::regclass AND c.relrowsecurity) THEN
    RAISE EXCEPTION '0304: row security is off on qudt_units';
  END IF;
  IF has_table_privilege('anon', 'public.qudt_quantity_kinds', 'SELECT')
     OR has_table_privilege('authenticated', 'public.qudt_quantity_kinds', 'INSERT')
     OR has_table_privilege('authenticated', 'public.qudt_quantity_kinds', 'UPDATE')
     OR has_table_privilege('authenticated', 'public.qudt_quantity_kinds', 'DELETE')
     OR has_table_privilege('anon', 'public.qudt_units', 'SELECT')
     OR has_table_privilege('authenticated', 'public.qudt_units', 'INSERT')
     OR has_table_privilege('authenticated', 'public.qudt_units', 'UPDATE')
     OR has_table_privilege('authenticated', 'public.qudt_units', 'DELETE') THEN
    RAISE EXCEPTION '0304: a QUDT table is readable by anon or writable by authenticated';
  END IF;
  IF NOT has_table_privilege('authenticated', 'public.qudt_quantity_kinds', 'SELECT')
     OR NOT has_table_privilege('authenticated', 'public.qudt_units', 'SELECT') THEN
    RAISE EXCEPTION '0304: authenticated cannot read a QUDT table';
  END IF;
  -- The kind the example readings and the issue name first, defined by QUDT's own text and by no other vocabulary.
  IF NOT EXISTS (SELECT 1 FROM public.qudt_quantity_kinds k
                   JOIN public.concept_definitions c ON c.semantic_id = k.semantic_id
                  WHERE k.semantic_id = 'http://qudt.org/vocab/quantitykind/Temperature'
                    AND c.standard = 'QUDT' AND c.definition = k.description) THEN
    RAISE EXCEPTION '0304: concept_definitions does not define the Temperature quantity kind by its QUDT text';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.qudt_units WHERE semantic_id = 'http://qudt.org/vocab/unit/DEG_C' AND unece_code = 'CEL') THEN
    RAISE EXCEPTION '0304: qudt_units does not hold the Celsius unit MTConnect''s CELSIUS maps to';
  END IF;
  IF has_table_privilege('anon', 'public.concept_definitions', 'SELECT') THEN
    RAISE EXCEPTION '0304: anon may read concept_definitions';
  END IF;
  IF NOT has_table_privilege('authenticated', 'public.concept_definitions', 'SELECT') THEN
    RAISE EXCEPTION '0304: authenticated may not read concept_definitions; aas-api reads it as the caller';
  END IF;
  IF EXISTS (SELECT 1 FROM public.concept_definitions GROUP BY semantic_id HAVING count(*) > 1) THEN
    RAISE EXCEPTION '0304: concept_definitions holds a semantic id twice';
  END IF;
END
$check$;

NOTIFY pgrst, 'reload schema';
