INSERT INTO public.qudt_quantity_kinds (semantic_id, name, description) VALUES
('http://qudt.org/vocab/quantitykind/APIGravity', 'API Gravity', 'The American Petroleum Institute gravity, or API gravity, is a measure of how heavy or light a petroleum liquid is compared to water: if its API gravity is greater than 10, it is lighter and floats on water; if less than 10, it is heavier and sinks. API gravity is thus an inverse measure of a petroleum liquid''s density relative to that of water (also known as specific gravity). It is used to compare densities of petroleum liquids. For example, if one petroleum liquid is less dense than another, it has a greater API gravity. Although API gravity is mathematically a dimensionless quantity (see the formula below), it is referred to as being in ''degrees''. API gravity is graduated in degrees on a hydrometer instrument. API gravity values of most petroleum liquids fall between 10 and 70 degrees.'),
('http://qudt.org/vocab/quantitykind/AbsoluteActivity', 'Absolute Activity', 'The "Absolute Activity" is the exponential of the ratio of the chemical potential to RT where R is the gas constant and T the thermodynamic temperature.'),
('http://qudt.org/vocab/quantitykind/AbsoluteHumidity', 'Absolute Humidity', 'Absolute Humidity is an amount of water vapour, usually discussed per unit volume. Absolute humidity in air ranges from zero to roughly 30 grams per cubic meter when the air is saturated at 30° C. The absolute humidity changes as air temperature or pressure changes. This is very inconvenient for chemical engineering calculations, e.g. for clothes dryers, where temperature can vary considerably. As a result, absolute humidity is generally defined in chemical engineering as mass of water vapour per unit mass of dry air, also known as the mass mixing ratio, which is much more rigorous for heat and mass balance calculations. Mass of water per unit volume as in the equation above would then be defined as volumetric humidity, because of the potential confusion.'),
('http://qudt.org/vocab/quantitykind/AbsoluteTypographicMeasurement', 'Absolute Typographic Measurement', NULL),
('http://qudt.org/vocab/quantitykind/AbsorbedDose', 'Absorbed Dose', '"Absorbed Dose" (also known as Total Ionizing Dose, TID) is a measure of the energy deposited in a medium by ionizing radiation. It is equal to the energy deposited per unit mass of medium, and so has the unit J/kg, which is given the special name Gray (Gy).'),
('http://qudt.org/vocab/quantitykind/AbsorbedDoseRate', 'Absorbed Dose Rate', '"Absorbed Dose Rate" is the absorbed dose of ionizing radiation imparted at a given location per unit of time (second, minute, hour, or day).'),
('http://qudt.org/vocab/quantitykind/Absorptance', 'Absorptance', 'Absorptance is the ratio of the radiation absorbed by a surface to that incident upon it. Also known as absorbance.'),
('http://qudt.org/vocab/quantitykind/Acceleration', 'Acceleration', 'Acceleration is the (instantaneous) rate of change of velocity. Acceleration may be either linear acceleration, or angular acceleration. It is a vector quantity with dimension length/time^2 for linear acceleration, or in the case of angular acceleration, with dimension angle/time^2. In SI units, linear acceleration is measured in meters/second^2 (m · s^-2), and angular acceleration is measured in radians/second^2. In physics, any increase or decrease in speed is referred to as acceleration and similarly, motion in a circle at constant speed is also an acceleration, since the direction component of the velocity is changing.'),
('http://qudt.org/vocab/quantitykind/AccelerationOfGravity', 'Acceleration of Gravity', 'The acceleration of freely falling bodies under the influence of terrestrial gravity, equal to approximately 9.81 meters (32 feet) per second per second.'),
('http://qudt.org/vocab/quantitykind/AcceptorDensity', 'Acceptor Density', '"Acceptor Density" is the number per volume of acceptor levels.'),
('http://qudt.org/vocab/quantitykind/AcceptorIonizationEnergy', 'Acceptor Ionization Energy', '"Acceptor Ionization Energy" is the ionization energy of an acceptor.'),
('http://qudt.org/vocab/quantitykind/Acidity', 'Acidity', 'Chemicals or substances having a pH less than 7 are said to be acidic; lower pH means higher acidity.'),
('http://qudt.org/vocab/quantitykind/AcousticImpedance', 'Acoustic Impedance', 'Acoustic impedance at a surface is the complex quotient of the average sound pressure over that surface by the sound volume flow rate through that surface.'),
('http://qudt.org/vocab/quantitykind/Action', 'Action', 'An action is usually an integral over time. But for action pertaining to fields, it may be integrated over spatial variables as well. In some cases, the action is integrated along the path followed by the physical system. If the action is represented as an integral over time, taken over the path of the system between the initial time and the final time of the development of the system. The evolution of a physical system between two states is determined by requiring the action be minimized or, more generally, be stationary for small perturbations about the true evolution. This requirement leads to differential equations that describe the true evolution. Conversely, an action principle is a method for reformulating differential equations of motion for a physical system as an equivalent integral equation. Although several variants have been defined (see below), the most commonly used action principle is Hamilton''s principle.'),
('http://qudt.org/vocab/quantitykind/ActionTime', 'Action Time', NULL),
('http://qudt.org/vocab/quantitykind/ActiveEnergy', 'Active Energy', '"Active Energy" is the electrical energy transformable into some other form of energy.'),
('http://qudt.org/vocab/quantitykind/ActivePower', 'Active Power', 'An Active Power is, under periodic conditions, the mean value, taken over one period T, of the instantaneous power p. In complex notation, P = Re S, where S is complex power.'),
('http://qudt.org/vocab/quantitykind/Activity', 'Activity', 'Activity is the number of decays per unit time of a radioactive sample, the term used to characterise the number of nuclei which disintegrate in a radioactive substance per unit time. Activity is usually measured in Becquerels (Bq), where 1 Bq is 1 disintegration per second, in honor of the scientist Henri Becquerel.'),
('http://qudt.org/vocab/quantitykind/ActivityCoefficient', 'Activity Coefficient', 'An "Activity Coefficient" is a factor used in thermodynamics to account for deviations from ideal behaviour in a mixture of chemical substances. In an ideal mixture, the interactions between each pair of chemical species are the same (or more formally, the enthalpy change of solution is zero) and, as a result, properties of the mixtures can be expressed directly in terms of simple concentrations or partial pressures of the substances present e.g. Raoult''s law. Deviations from ideality are accommodated by modifying the concentration by an activity coefficient.'),
('http://qudt.org/vocab/quantitykind/ActivityConcentration', 'Activity Concentration', 'The "Activity Concentration", also known as volume activity, and activity density, is the ratio of the activity of a sample containing radionuclides and the sample''s volume.'),
('http://qudt.org/vocab/quantitykind/ActivityRelatedByMass', 'Activity Related by Mass', 'quantitative data of the radioactivity of the amount of a radionuclide in a particular state of energy at a defined point in time, divided by the related mass of this quantity'),
('http://qudt.org/vocab/quantitykind/ActivityThresholds', 'Activity Thresholds', '"Activity Thresholds" are threshold values of absorbed dose - the mean energy imparted by ionizing radiation to matter per unit mass - above which harmful (deterministic) effects occur. It has the dimension of specific energy and is expressed in gray.'),
('http://qudt.org/vocab/quantitykind/Adaptation', 'Adaptation', '"Adaptation" is the recovery of visual ability following exposure to light (dark adaptation).'),
('http://qudt.org/vocab/quantitykind/Admittance', 'Admittance', '"Admittance" is a measure of how easily a circuit or device will allow a current to flow. It is defined as the inverse of the impedance (Z).'),
('http://qudt.org/vocab/quantitykind/AlphaDisintegrationEnergy', 'Alpha Disintegration Energy', 'The "Alpha Disintegration Energy" is the sum of the kinetic energy of the alpha-particle produced in the disintegration process and the recoil energy of the product atom in the reference frame in which the emitting nucleus is at rest before its disintegration.'),
('http://qudt.org/vocab/quantitykind/Altitude', 'Altitude', 'Altitude or height is defined based on the context in which it is used (aviation, geometry, geographical survey, sport, and more). As a general definition, altitude is a distance measurement, usually in the vertical or "up" direction, between a reference datum and a point or object. The reference datum also often varies according to the context. [Wikipedia]'),
('http://qudt.org/vocab/quantitykind/AmbientPressure', 'Ambient Pressure', 'The ambient pressure on an object is the pressure of the surrounding medium, such as a gas or liquid, which comes into contact with the object. The SI unit of pressure is the pascal (Pa), which is a very small unit relative to atmospheric pressure on Earth, so kilopascals (kPa) are more commonly used in this context.'),
('http://qudt.org/vocab/quantitykind/AmountOfBiologicallyActiveSubstance', 'Amount of Biologically Active Substance', '"Amount of Biologically Active Substance" is the quantity of a substance expressed in International Units (IU), a measure of biological activity. It is dimensioned as mass (M) and organized under Mass Equivalent rather than as amount of substance (N): for any given substance one IU corresponds to a defined mass of an international reference preparation, so the quantity is a substance-dependent mass equivalent whose conversion factor is fixed per substance and resolved at the quantity level. It is deliberately not dimensioned as amount of substance, since one IU is not a fixed number of moles.'),
('http://qudt.org/vocab/quantitykind/AmountOfCloudCover', 'Amount of Cloud Cover', 'The amount of the celestial dome covered by all clouds visible.'),
('http://qudt.org/vocab/quantitykind/AmountOfData', 'Amount of Data', 'The total quantity of digital information or storage, counted as a number of bits or bytes (and their SI and binary multiples). This is an abstract umbrella kind; its concrete specialisations are counted in bits (quantitykind:BitDataVolume) or bytes (quantitykind:ByteDataVolume). It is a counting quantity, distinct from the information-theoretic entropy carried by that data (see unit:SHANNON).'),
('http://qudt.org/vocab/quantitykind/AmountOfSubstance', 'Amount of Substance', 'Amount of Substance is a standards-defined quantity that measures the size of an ensemble of elementary entities, such as atoms, molecules, electrons, and other particles. It is sometimes referred to as chemical amount. The International System of Units (SI) defines the amount of substance to be proportional to the number of elementary entities present. The SI unit for amount of substance is mole. It has the unit symbol mol. The mole is defined as the amount of substance that contains an equal number of elementary entities as there are atoms in 0.012kg of the isotope carbon-12. This number is called Avogadro''s number and has the value 6.02214179(30) × 10^23. The only other unit of amount of substance in current use is the pound-mole with the symbol lb-mol, which is sometimes used in chemical engineering in the United States. One pound-mole is exactly 453.59237 mol.'),
('http://qudt.org/vocab/quantitykind/AmountOfSubstanceConcentration', 'Amount of Substance of Concentration', '"Amount of Substance of Concentration of B" is defined as the amount of a constituent divided by the volume of the mixture.'),
('http://qudt.org/vocab/quantitykind/AmountOfSubstanceFraction', 'Fractional Amount of Substance', '"Fractional Amount of Substance" is defined as tthe amount of a constituent divided by the total amount of all constituents in a mixture.'),
('http://qudt.org/vocab/quantitykind/AmountOfSubstanceIonConcentration', 'Amount of Substance Ion Concentration', '"Amount of Substance Ion Concentration" is the moles of ions per volume of solution.'),
('http://qudt.org/vocab/quantitykind/AmountOfSubstancePerMass', 'Amount of Substance per Mass', NULL),
('http://qudt.org/vocab/quantitykind/AmountOfSubstancePerMassPressure', 'Molar Mass Variation Due to Pressure', 'The "Variation of Molar Mass" of a gas as a function of pressure.'),
('http://qudt.org/vocab/quantitykind/AmountOfSubstancePerVolume', 'Amount of Substance per Volume', 'The amount of substance per unit volume is called the molar density. Molar density is an intensive property of a substance and depends on the temperature and pressure.'),
('http://qudt.org/vocab/quantitykind/Angle', 'Angle', 'The abstract notion of angle. Narrow concepts include plane angle and solid angle. While both plane angle and solid angle are dimensionless, they are actually length/length and area/area respectively.'),
('http://qudt.org/vocab/quantitykind/AngleOfAttack', 'Angle of Attack', 'Angle of attack is the angle between the oncoming air or relative wind and a reference line on the airplane or wing.'),
('http://qudt.org/vocab/quantitykind/AngleOfOpticalRotation', 'Angle of Optical Rotation', 'The "Angle of Optical Rotation" is the angle through which plane-polarized light is rotated clockwise, as seen when facing the light source, in passing through an optically active medium.'),
('http://qudt.org/vocab/quantitykind/AngularAcceleration', 'Angular Acceleration', 'Angular acceleration is the rate of change of angular velocity over time. Measurement of the change made in the rate of change of an angle that a spinning object undergoes per unit time. It is a vector quantity. Also called Rotational acceleration. In SI units, it is measured in radians per second squared (rad/s^2), and is usually denoted by the Greek letter alpha.'),
('http://qudt.org/vocab/quantitykind/AngularCrossSection', 'Angular Cross-section', '"Angular Cross-section" is the cross-section for ejecting or scattering a particle into an elementary cone, divided by the solid angle dΩ of that cone.'),
('http://qudt.org/vocab/quantitykind/AngularDistance', 'Angular Distance', 'Angular distance travelled by orbiting vehicle measured from the azimuth of closest approach.'),
('http://qudt.org/vocab/quantitykind/AngularFrequency', 'Angular Frequency', '"Angular frequency", symbol ω (also referred to by the terms angular speed, radial frequency, circular frequency, orbital frequency, radian frequency, and pulsatance) is a scalar measure of rotation rate. Angular frequency (or angular speed) is the magnitude of the vector quantity angular velocity.'),
('http://qudt.org/vocab/quantitykind/AngularImpulse', 'Angular Impulse', 'The Angular Impulse, also known as angular momentum, is the moment of linear momentum around a point. It is defined asH = ∫ Mdt, where M is the moment of force and t is time.'),
('http://qudt.org/vocab/quantitykind/AngularMomentum', 'Angular Momentum', 'Angular Momentum of an object rotating about some reference point is the measure of the extent to which the object will continue to rotate about that point unless acted upon by an external torque. In particular, if a point mass rotates about an axis, then the angular momentum with respect to a point on the axis is related to the mass of the object, the velocity and the distance of the mass to the axis. While the motion associated with linear momentum has no absolute frame of reference, the rotation associated with angular momentum is sometimes spoken of as being measured relative to the fixed stars. Angular Momentum, Moment of Momentum, or Rotational Momentum", is a vector quantity that represents the product of a body''s rotational inertia and rotational velocity about a particular axis.'),
('http://qudt.org/vocab/quantitykind/AngularMomentumPerAngle', 'Angular Momentum per Angle', NULL),
('http://qudt.org/vocab/quantitykind/AngularReciprocalLatticeVector', 'Angular Reciprocal Lattice Vector', '"Angular Reciprocal Lattice Vector" is a vector whose scalar products with all fundamental lattice vectors are integral multiples of 2π.'),
('http://qudt.org/vocab/quantitykind/AngularVelocity', 'Angular Velocity', 'The change of angle per unit time; specifically, in celestial mechanics, the change in angle of the radius vector per unit time.'),
('http://qudt.org/vocab/quantitykind/AngularWavenumber', 'Angular Wavenumber', '"wavenumber" is the spatial frequency of a wave - the number of waves that exist over a specified distance. More formally, it is the reciprocal of the wavelength. It is also the magnitude of the wave vector.'),
('http://qudt.org/vocab/quantitykind/ApogeeRadius', 'Apogee Radius', 'Apogee radius of an elliptical orbit'),
('http://qudt.org/vocab/quantitykind/ApparentEnergy', 'Apparent Energy', 'Apparent energy is the integral of apparent power over a time interval. It is commonly measured in volt-ampere hours (VA·h) or kilovolt-ampere hours (kVA·h).'),
('http://qudt.org/vocab/quantitykind/ApparentPower', 'Apparent Power', '"Apparent Power" is the product of the rms voltage U between the terminals of a two-terminal element or two-terminal circuit and the rms electric current I in the element or circuit. Under sinusoidal conditions, the apparent power is the modulus of the complex power.'),
('http://qudt.org/vocab/quantitykind/ApparentThermalInertia', 'Measurement Unit for a Quantity Approximately Proportional to Thermal Inertia', 'Thermal inertia is a term used to describe the observed delays in a body''s temperature response during heat transfers'),
('http://qudt.org/vocab/quantitykind/Area', 'Area', 'Area is a quantity expressing the two-dimensional size of a defined part of a surface, typically a region bounded by a closed curve.'),
('http://qudt.org/vocab/quantitykind/AreaAngle', 'Area Angle', NULL),
('http://qudt.org/vocab/quantitykind/AreaBitDensity', 'Areic Bit Density', NULL),
('http://qudt.org/vocab/quantitykind/AreaChargeDensity', 'Areic Charge Density', NULL),
('http://qudt.org/vocab/quantitykind/AreaMass', 'Areic Mass', NULL),
('http://qudt.org/vocab/quantitykind/AreaPerLength', 'Area per Length', 'Measure used to indicate the surface area of structural steel per unit length of the steel part.'),
('http://qudt.org/vocab/quantitykind/AreaPerPower', 'Area per Heating Load', 'The ratio of an area and the power required for maintaining room temperature at a given level'),
('http://qudt.org/vocab/quantitykind/AreaPerTime', 'Area per Time', NULL),
('http://qudt.org/vocab/quantitykind/AreaRatio', 'Area Ratio', NULL),
('http://qudt.org/vocab/quantitykind/AreaTemperature', 'Area Temperature', NULL),
('http://qudt.org/vocab/quantitykind/AreaThermalExpansion', 'Area Thermal Expansion', 'When the temperature of a substance changes, the energy that is stored in the intermolecular bonds between atoms changes. When the stored energy increases, so does the length of the molecular bonds. As a result, solids typically expand in response to heating and contract on cooling; this dimensional response to temperature change is expressed by its coefficient of thermal expansion.'),
('http://qudt.org/vocab/quantitykind/AreaTime', 'Area Time', NULL),
('http://qudt.org/vocab/quantitykind/AreaTimeTemperature', 'Area Time Temperature', NULL),
('http://qudt.org/vocab/quantitykind/AreicDataVolume', 'Areic Data Volume', 'volume of data, which is usually dependent on the respective complexity of the information or its coding procedure, divided by the related area'),
('http://qudt.org/vocab/quantitykind/AreicEnergyFlow', 'Areic Energy Flow', 'energy in a defined direction of propagation through a surface perpendicular to this, divided by its area'),
('http://qudt.org/vocab/quantitykind/AreicHeatFlowRate', 'Aeric Heat Flow Rate', 'Density of heat flow rate.'),
('http://qudt.org/vocab/quantitykind/AreicMass', 'Areic Mass', 'mass divided by the related area'),
('http://qudt.org/vocab/quantitykind/AreicTorque', 'Areic Torque', 'ratio of a torque acting on a surface and causing a rotation or shearing divided by this area'),
('http://qudt.org/vocab/quantitykind/Asset', 'Asset', 'An Asset is an economic resource owned by a business or company. Simply stated, assets are things of value that can be readily converted into cash (although cash itself is also considered an asset).'),
('http://qudt.org/vocab/quantitykind/AtmosphericHydroxylationRate', 'Atmospheric Hydroxylation Rate', 'A second order reaction rate constant that is a specific second order reaction rate constant that governs the kinetics of an atmospheric, gas-phase reaction between hydroxyl radicals and an organic chemical.'),
('http://qudt.org/vocab/quantitykind/AtmosphericPressure', 'Atmospheric Pressure', 'The pressure exerted by the weight of the air above it at any point on the earth''s surface. At sea level the atmosphere will support a column of mercury about 760 mm high. This decreases with increasing altitude. The standard value for the atmospheric pressure at sea level in SI units is 101,325 pascals.'),
('http://qudt.org/vocab/quantitykind/AtomScatteringFactor', 'Atom Scattering Factor', '"Atom Scattering Factor" is measure of the scattering power of an isolated atom.'),
('http://qudt.org/vocab/quantitykind/AtomicAttenuationCoefficient', 'Atomic Attenuation Coefficient', '"Atomic Attenuation Coefficient" is a measurement of how strongly a chemical species or substance absorbs or scatters light at a given wavelength, per the number of atoms in the substance.'),
('http://qudt.org/vocab/quantitykind/AtomicCharge', 'Atomic Charge', 'The electric charge of an ion, equal to the number of electrons the atom has gained or lost in its ionization multiplied by the charge on one electron.'),
('http://qudt.org/vocab/quantitykind/AtomicEnergy', 'Atomic Energy', 'scalar quantity of elementary particles which is retained within a system following any change and, as saved energy, constitutes the capability of a physical system to carry out work'),
('http://qudt.org/vocab/quantitykind/AtomicMass', 'Atomic Mass', 'The "Atomic Mass" is the mass of a specific isotope, most often expressed in unified atomic mass units.'),
('http://qudt.org/vocab/quantitykind/AtomicNumber', 'Atomic Number', 'The "Atomic Number", also known as the proton number, is the number of protons found in the nucleus of an atom and therefore identical to the charge number of the nucleus. A nuclide is a species of atom with specified numbers of protons and neutrons. Nuclides with the same value of Z but different values of N are called isotopes of an element. The ordinal number of an element in the periodic table is equal to the atomic number. The atomic number equals the charge of the nucleus in units of the elementary charge.'),
('http://qudt.org/vocab/quantitykind/AtomicStoppingPower', 'Atomic Stopping Power', 'ratio of the linear stopping power to the number density of the atoms in the medium'),
('http://qudt.org/vocab/quantitykind/AttenuationCoefficient', 'Attenuation Coefficient', 'The attenuation coefficient is a quantity that characterizes how easily a material or medium can be penetrated by a beam of light, sound, particles, or other energy or matter. A large attenuation coefficient means that the beam is quickly "attenuated" (weakened) as it passes through the medium, and a small attenuation coefficient means that the medium is relatively transparent to the beam. The Attenuation Coefficient is also called linear attenuation coefficient, narrow beam attenuation coefficient, or absorption coefficient.'),
('http://qudt.org/vocab/quantitykind/AuditoryThresholds', 'Auditory Thresholds', '"Auditory Thresholds" is the thresholds of sensitivity to auditory signals and other input to the ear or the sense of hearing.'),
('http://qudt.org/vocab/quantitykind/AuxillaryMagneticField', 'Auxillary Magnetic Field', 'Magnetic Fields surround magnetic materials and electric currents and are detected by the force they exert on other magnetic materials and moving electric charges. The electric and magnetic fields are two interrelated aspects of a single object, called the electromagnetic field. A pure electric field in one reference frame is observed as a combination of both an electric field and a magnetic field in a moving reference frame. The Auxillary Magnetic Field, H characterizes how the true Magnetic Field B influences the organization of magnetic dipoles in a given medium.'),
('http://qudt.org/vocab/quantitykind/AverageEnergyLossPerElementaryChargeProduced', 'Average Energy Loss per Elementary Charge Produced', '"Average Energy Loss per Elementary Charge Produced" is also referred to as average energy loss per ion pair formed.'),
('http://qudt.org/vocab/quantitykind/AverageHeadEndPressure', 'Average Head End Pressure', NULL),
('http://qudt.org/vocab/quantitykind/AverageLogarithmicEnergyDecrement', 'Average Logarithmic Energy Decrement', '"Average Logarithmic Energy Decrement" is a measure of the amount of energy a neutron loses upon colliding with various nuclei. It is the average value of the increase in lethargy in elastic collisions between neutrons and nuclei whose kinetic energy is negligible compared with that of the neutrons.'),
('http://qudt.org/vocab/quantitykind/AverageSpecificImpulse', 'Average Specific Impulse', NULL),
('http://qudt.org/vocab/quantitykind/AverageVacuumThrust', 'Average Vacuum Thrust', NULL),
('http://qudt.org/vocab/quantitykind/Azimuth', 'Azimuth', 'The horizontal angle between an object and a cardinal direction, generally north. In the context of architecture, this would refer to the direction a structure faces relative to the direction north.'),
('http://qudt.org/vocab/quantitykind/BandwidthDistanceProduct', 'Bandwidth Distance Product', 'The product of a transmission medium''s bandwidth and the transmission distance, characterising the signal-carrying capacity of the medium: a link may trade bandwidth against distance while their product remains limited (for example a multimode optical fibre rated in MHz·km). The same quantity as quantitykind:BandwidthLengthProduct, from a different source vocabulary.'),
('http://qudt.org/vocab/quantitykind/BandwidthLengthProduct', 'Bandwidth Length Product', 'parameter of transmission media for determination of frequency and length restrictions as reciprocal value of the multimode distortion corresponding to the product of maximum pulse frequency and maximum transmission distance'),
('http://qudt.org/vocab/quantitykind/Basicity', 'Basicity', 'Chemicals or substances having a pH higher than 7 are said to be basic; higher pH means higher basicity.'),
('http://qudt.org/vocab/quantitykind/BatteryCapacity', 'Battery Capacity', 'quantity of electricity or electrical charge which a fully charged battery can supply under specified conditions as a product of discharge current and discharge time'),
('http://qudt.org/vocab/quantitykind/BendingMomentOfForce', 'Bending Moment of Force', 'A bending moment exists in a structural element when a moment is applied to the element so that the element bends. It is the component of moment of force perpendicular to the longitudinal axis of a beam or a shaft.'),
('http://qudt.org/vocab/quantitykind/BetaDisintegrationEnergy', 'Beta Disintegration Energy', '"Beta Disintegration Energy" is the energy released by a beta particle radioactive decay. It is the sum of the maximum beta-particle kinetic energy and the recoil energy of the atom produced in the reference frame in which the emitting nucleus is at rest before its disintegration.'),
('http://qudt.org/vocab/quantitykind/BevelGearPitchAngle', 'Bevel Gear Pitch Angle', 'Pitch angle in bevel gears is the angle between an element of a pitch cone and its axis. In external and internal bevel gears, the pitch angles are respectively less than and greater than 90 degrees.'),
('http://qudt.org/vocab/quantitykind/BindingFraction', 'Binding Fraction', 'The "Binding Fraction" is the ratio of the binding energy of a nucleus to the atomic mass number.'),
('http://qudt.org/vocab/quantitykind/BioconcentrationFactor', 'Bioconcentration Factor', 'The bioconcentration factor is the ratio of the concentration of a chemical substance in biota over the concentration of the same chemical substance in water. It is related to the octanol-water partition coefficient.'),
('http://qudt.org/vocab/quantitykind/BiodegredationHalfLife', 'Biodegredation Half Life', 'A time that quantifies how long it takes to reduce a substance''s concentration by 50% from any concentration point in time in a water or soil environment by either bacteria or another living organism.'),
('http://qudt.org/vocab/quantitykind/BiogeochemicalRate', 'Biogeochemical Rate', 'the rate at which a specific chemical element or compound is processed or transformed, as amount per unit mass of the relevant material. Unreduced, SI unit is mole * kg-1 * s-1'),
('http://qudt.org/vocab/quantitykind/BitDataVolume', 'Bit Data Volume', 'name for a particular quantity of data on the basis of the binary digit "Bit" (basic indissoluble information unit) which can only assume a state of 1 or 0'),
('http://qudt.org/vocab/quantitykind/BitRate', 'Bit Rate', NULL),
('http://qudt.org/vocab/quantitykind/BitTransmissionRate', 'Bit Transmission Rate', 'speed with which one bit will be transmitted per second'),
('http://qudt.org/vocab/quantitykind/BloodGlucoseLevel', 'Blood Glucose Level', 'Blood sugar level, blood sugar concentration, or blood glucose level is the amount of glucose present in the blood of humans and animals. Glucose is a simple sugar and approximately 4 grams of glucose are present in the blood of humans at all times. Stored in skeletal muscle and liver cells in the form of glycogen, the body tightly regulates blood glucose levels as a part of metabolic homeostasis. During fasting blood glucose is maintained at a constant level at the expense of the glycogen stores in the liver and skeletal muscle. There are two main methods of describing concentrations: by weight, and by molecular count. Weights are in grams and molecular counts in moles. A mole is 6.022× 10^23 molecules. In both cases, the unit is usually modified by milli- or micro- or other prefix, and is always per some volume, often a litre. Conversion factors depend on the molecular weight of the substance in question. mmol/L is millimoles/liter, and is the world standard unit for measuring glucose in blood. Specifically, it is the designated SI (Systeme International) unit. Some countries use mg/dl. A mole is about 6× 10^23 molecules. mg/dL (milligrams/deciliter) is the traditional unit for measuring bG (blood glucose). There is a trend toward using mmol/L however mg/dL is much in practice. Some use is made of mmol/L as the primary unit with mg/dL quoted in parentheses. This acknowledges the large base of health care providers, researchers and patients who are already familiar with mg/dL.'),
('http://qudt.org/vocab/quantitykind/BodyMassIndex', 'Body Mass Index', 'Body Mass Index, BMI, is an index of weight for height, calculated as: BMI = M_body/H^2, where M_body is body mass in kg, and H is height in metres. The BMI has been used as a guideline for defining whether a person is overweight because it minimizes the effect of height, but it does not take into consideration other important factors, such as age and body build. The BMI has also been used as an indicator of obesity on the assumption that the higher the index, the greater the level of body fat.'),
('http://qudt.org/vocab/quantitykind/BoilingPoint', 'Boiling Point Temperature', 'A temperature that is the one at which a substance will change its physical state from a liquid to a gas. It is also the temperature where the liquid and gaseous forms of a pure substance can exist in equilibrium.'),
('http://qudt.org/vocab/quantitykind/BraggAngle', 'Bragg Angle', '"Bragg Angle" describes the condition for a plane wave to be diffracted from a family of lattice planes, the angle between the wavevector of the incident plane wave, and the lattice planes.'),
('http://qudt.org/vocab/quantitykind/Breadth', 'Breadth', '"Breadth" is the extent or measure of how broad or wide something is.'),
('http://qudt.org/vocab/quantitykind/BucklingFactor', 'Buckling Factor', NULL),
('http://qudt.org/vocab/quantitykind/BulkModulus', 'Bulk Modulus', 'The bulk modulus of a substance measures the substance''s resistance to uniform compression. It is defined as the ratio of the infinitesimal pressure increase to the resulting relative decrease of the volume.'),
('http://qudt.org/vocab/quantitykind/BurgersVector', 'Burgers Vector', '"Burgers Vector" is the vector characterizing a dislocation, i.e. the closing vector in a Burgers circuit encircling a dislocation line.'),
('http://qudt.org/vocab/quantitykind/BurnRate', 'Burn Rate', NULL),
('http://qudt.org/vocab/quantitykind/BurnTime', 'Burn Time', NULL),
('http://qudt.org/vocab/quantitykind/BurstFactor', 'Burst Factor', 'bursting pressure divided by areic mass'),
('http://qudt.org/vocab/quantitykind/ByteDataVolume', 'Byte Data Volume', 'particular quantity of data based on a string consisting of 8 bits'),
('http://qudt.org/vocab/quantitykind/ByteRate', 'Byte Rate', NULL),
('http://qudt.org/vocab/quantitykind/ByteTransmissionRate', 'Byte Transmission Rate', 'speed with which 8 bits are transmitted'),
('http://qudt.org/vocab/quantitykind/CO2Equivalent', 'CO2Equivalent', 'The CO2 equivalent is a measure used to compare the emissions from various greenhouse gases on the basis of their global-warming potential (GWP), by converting amounts of other gases to the equivalent amount of carbon dioxide with the same global warming potential.'),
('http://qudt.org/vocab/quantitykind/CanonicalPartitionFunction', 'Canonical Partition Function', 'A "Canonical Partition Function" applies to a canonical ensemble, in which the system is allowed to exchange heat with the environment at fixed temperature, volume, and number of particles.'),
('http://qudt.org/vocab/quantitykind/Capacitance', 'Capacitance', '"Capacitance" is the ability of a body to hold an electrical charge; it is quantified as the amount of electric charge stored for a given electric potential. Capacitance is a scalar-valued quantity.'),
('http://qudt.org/vocab/quantitykind/CarrierLifetime', 'Carrier Lifetime', '"Carrier LifetIme" is a time constant for recombination or trapping of minority charge carriers in semiconductors.'),
('http://qudt.org/vocab/quantitykind/CartesianArea', 'Cartesian Area', '"Area" is a quantity that expresses the extent of a two-dimensional surface or shape, or planar lamina, in the plane.'),
('http://qudt.org/vocab/quantitykind/CartesianCoordinates', 'Cartesian Coordinates', '"Cartesian Coordinates" specify each point uniquely in a plane by a pair of numerical coordinates, which are the signed distances from the point to two fixed perpendicular directed lines, measured in the same unit of length.'),
('http://qudt.org/vocab/quantitykind/CartesianVolume', 'Volume', '"Volume" is the quantity of three-dimensional space enclosed by some closed boundary, for example, the space that a substance (solid, liquid, gas, or plasma) or shape occupies or contains.'),
('http://qudt.org/vocab/quantitykind/CatalyticActivity', 'Catalytic Activity', 'An index of the actual or potential activity of a catalyst. The catalytic activity of an enzyme or an enzyme-containing preparation is defined as the property measured by the increase in the rate of conversion of a specified chemical reaction that the enzyme produces in a specified assay system. Catalytic activity is an extensive quantity and is a property of the enzyme, not of the reaction mixture; it is thus conceptually different from rate of conversion although measured by and equidimensional with it. The unit for catalytic activity is the katal; it may also be expressed in mol s^-1. Dimensions: N T^-1. Former terms such as catalytic ability, catalytic amount, and enzymic activity are no er recommended. Derived quantities are molar catalytic activity, specific catalytic activity, and catalytic activity concentration. Source(s): www.answers.com'),
('http://qudt.org/vocab/quantitykind/CatalyticActivityConcentration', 'Catalytic Activity Concentration', 'The catalytic activity of an enzyme per unit volume, where volume refers to that of the original enzyme‐containing preparation, not that of the assay system. It may be expressed in katals per litre.'),
('http://qudt.org/vocab/quantitykind/CationExchangeCapacity', 'Cation Exchange Capacity', 'The amount of positive ionic charge (in moles or charge or equivalents) that a solid material can exchange per unit mass. Widely used for soils and other materials with cation-exchange sites.'),
('http://qudt.org/vocab/quantitykind/CelsiusTemperature', 'Celsius Temperature', '"Celsius Temperature", the thermodynamic temperature T_0, is exactly 0.01 kelvin below the thermodynamic temperature of the triple point of water.'),
('http://qudt.org/vocab/quantitykind/CenterOfGravity_X', 'Center of Gravity in the X Axis', NULL),
('http://qudt.org/vocab/quantitykind/CenterOfGravity_Y', 'Center of Gravity in the Y Axis', NULL),
('http://qudt.org/vocab/quantitykind/CenterOfGravity_Z', 'Center of Gravity in the Z Axis', NULL),
('http://qudt.org/vocab/quantitykind/CharacteristicAcousticImpedance', 'Characteristic Acoustic Impedance', 'Characteristic impedance at a point in a non-dissipative medium and for a plane progressive wave, the quotient of the sound pressure p by the component of the sound particle velocity v in the direction of the wave propagation.'),
('http://qudt.org/vocab/quantitykind/CharacteristicNumber', 'Characteristic Number', 'quantity of dimension one (as a result of measuring technology theory) which clarifies facts, states or developments and is used as a scale e.g. to represent causes and effects of events'),
('http://qudt.org/vocab/quantitykind/CharacteristicVelocity', 'Characteristic Velocity', 'Characteristic velocity or c^* is a measure of the combustion performance of a rocket engine independent of nozzle performance, and is used to compare different propellants and propulsion systems.'),
('http://qudt.org/vocab/quantitykind/ChargeNumber', 'Charge Number', 'The "Charge Number", or just valance of an ion is the coefficient that, when multiplied by the elementary charge, gives the ion''s charge.'),
('http://qudt.org/vocab/quantitykind/ChemicalAffinity', 'Chemical Affinity', 'In chemical physics and physical chemistry, "Chemical Affinity" is the electronic property by which dissimilar chemical species are capable of forming chemical compounds. Chemical affinity can also refer to the tendency of an atom or compound to combine by chemical reaction with atoms or compounds of unlike composition.'),
('http://qudt.org/vocab/quantitykind/ChemicalConsumptionPerMass', 'Chemical Consumption per Mass', 'In the context of a chemical durability test, this is measure of how much of a solution (often a corrosive or reactive one) is consumed or used up per unit mass of a material being tested. In other words, this the volume of solution needed to cause a certain level of chemical reaction or damage to a given mass of the material.'),
('http://qudt.org/vocab/quantitykind/ChemicalPotential', 'Chemical Potential', '"Chemical Potential", also known as partial molar free energy, is a form of potential energy that can be absorbed or released during a chemical reaction.'),
('http://qudt.org/vocab/quantitykind/Chromaticity', 'Chromaticity', 'Chromaticity is an objective specification of the quality of a color regardless of its luminance'),
('http://qudt.org/vocab/quantitykind/Circulation', 'Circulation', 'In fluid dynamics, circulation is the line integral around a closed curve of the fluid velocity. It has dimensions of length squared over time.'),
('http://qudt.org/vocab/quantitykind/ClosestApproachRadius', 'Closest Approach Radius', NULL),
('http://qudt.org/vocab/quantitykind/CoefficientOfHeatTransfer', 'Coefficient of Heat Transfer', '"Coefficient of Heat Transfer", in thermodynamics and in mechanical and chemical engineering, is used in calculating the heat transfer, typically by convection or phase transition between a fluid and a solid. The heat transfer coefficient is the proportionality coefficient between the heat flux, that is heat flow per unit area, q/A, and the thermodynamic driving force for the flow of heat (that is, the temperature difference, (Delta T). Areic heat flow rate divided by thermodynamic temperature difference. In building technology, the "Coefficient of Heat Transfer", is often called "thermal transmittance" with the symbol "U". It has SI units in watts per squared meter kelvin.'),
('http://qudt.org/vocab/quantitykind/CoefficientOfPerformance', 'Coefficient of Performance', '"Coefficient of Performance" is a measure of the efficiency of a heating or cooling system, defined as the ratio of useful heating or cooling output to the energy input required to achieve it.'),
('http://qudt.org/vocab/quantitykind/Coercivity', 'Coercivity', 'Coercivity, also referred to as Coercive Field Strength, is the magnetic field strength to be applied to bring the magnetic flux density in a substance from its remaining magnetic flux density to zero. This is defined as the coercive field strength in a substance when either the magnetic flux density or the magnetic polarization and magnetization is brought from its value at magnetic saturation to zero by monotonic reduction of the applied magnetic field strength. The quantity which is brought to zero should be stated, and the appropriate symbol used: H_cB, H_cJ or H_cM for the coercivity relating to the magnetic flux density, the magnetic polarization or the magnetization respectively, where H_cJ = H_cM.'),
('http://qudt.org/vocab/quantitykind/CoherenceLength', 'Coherence Length', '"Coherence Length" characterizes the distance in a superconductor over which the effect of a perturbation is appreciable.'),
('http://qudt.org/vocab/quantitykind/ColdReceptorThreshold', 'Cold Receptor Threshold', '"Cold Receptor Threshold" is the threshold of cold-sensitive free nerve-ending.'),
('http://qudt.org/vocab/quantitykind/CombinedNonEvaporativeHeatTransferCoefficient', 'Combined Non Evaporative Heat Transfer Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/ComplexFrequency_Imaginary', 'Imaginary Part of Complex Frequency', NULL),
('http://qudt.org/vocab/quantitykind/ComplexFrequency_Real', 'Real Part of Complex Frequency', NULL),
('http://qudt.org/vocab/quantitykind/CompoundPlaneAngle', 'Compound Plane Angle', 'A "Compound Plane Angle" is a compound measure of plane angle in degrees, minutes, seconds, and optionally millionth-seconds of arc.'),
('http://qudt.org/vocab/quantitykind/Compressibility', 'Compressibility', 'Compressibility is a measure of the relative volume change of a fluid or solid as a response to a pressure (or mean stress) change.'),
('http://qudt.org/vocab/quantitykind/CompressibilityFactor', 'Compressibility Factor', 'The compressibility factor (Z) is a useful thermodynamic property for modifying the ideal gas law to account for the real gas behaviour. The closer a gas is to a phase change, the larger the deviations from ideal behavior. It is simply defined as the ratio of the molar volume of a gas to the molar volume of an ideal gas at the same temperature and pressure. Values for compressibility are calculated using equations of state (EOS), such as the virial equation and van der Waals equation. The compressibility factor for specific gases can be obtained, with out calculation, from compressibility charts. These charts are created by plotting Z as a function of pressure at constant temperature.'),
('http://qudt.org/vocab/quantitykind/Concentration', 'Concentration', 'In chemistry, concentration is defined as the abundance of a constituent divided by the total volume of a mixture. Furthermore, in chemistry, four types of mathematical description can be distinguished: mass concentration, molar concentration, number concentration, and volume concentration. The term concentration can be applied to any kind of chemical mixture, but most frequently it refers to solutes in solutions.'),
('http://qudt.org/vocab/quantitykind/Conductance', 'Conductance', 'Conductance, for a resistive two-terminal element or two-terminal circuit with terminals A and B, quotient of the electric current i in the element or circuit by the voltage u_AB between the terminals: G = 1/R, where the electric current is taken as positive if its direction is from A to B and negative in the opposite case. The conductance of an element or circuit is the inverse of its resistance.'),
('http://qudt.org/vocab/quantitykind/ConductionSpeed', 'Conduction Speed', '"Conduction Speed" is the speed of impulses in nerve fibers.'),
('http://qudt.org/vocab/quantitykind/ConductiveHeatTransferRate', 'Conductive Heat Transfer Rate', '"Conductive Heat Transfer Rate" is proportional to temperature gradient and area of contact.'),
('http://qudt.org/vocab/quantitykind/ConductivityVariance', 'Conductivity Variance', 'Variance for conductivity data.'),
('http://qudt.org/vocab/quantitykind/Constringence', 'Constringence', 'In optics and lens design, constringence of a transparent material, also known as the Abbe number or the V-number, is an approximate measure of the material''s dispersion (change of refractive index versus wavelength), with high values of V indicating low dispersion.'),
('http://qudt.org/vocab/quantitykind/ConvectiveHeatTransfer', 'Convective Heat Transfer', '"Convective Heat Transfer" is convective heat transfer coefficient multiplied by temperature difference and exchange area.'),
('http://qudt.org/vocab/quantitykind/CoolingPerformanceRatio', 'Cooling Performance Ratio', 'Ratio of input power to delivered cooling capacity, used to assess the efficiency of cooling systems such as chillers. Commonly expressed in kW per ton of refrigeration, where lower values indicate better performance.'),
('http://qudt.org/vocab/quantitykind/CorrelatedColorTemperature', 'Correlated Colour Temperature', 'Correlated color temperature (CCT) is a measure of light source color appearance defined by the proximity of the light source''s chromaticity coordinates to the blackbody locus, as a single number rather than the two required to specify a chromaticity.'),
('http://qudt.org/vocab/quantitykind/CostPerArea', 'Cost per Area', 'In the construction industry, cost per area is the unit rate which, when multiplied by the gross internal floor area (GIFA), gives the total building works estimate (i.e.works cost estimate less main contractor’s preliminaries and main contractor’s overheads and profit).'),
('http://qudt.org/vocab/quantitykind/CostPerEnergy', 'Energy Cost', 'The monetary cost of a unit of energy'),
('http://qudt.org/vocab/quantitykind/CostPerMass', 'Cost per Mass', 'Represents the cost associated with a unit mass of a substance or material. It is typically used in economic and engineering contexts to evaluate the expense incurred per kilogram, gram, or other units of mass. This measure helps in comparing the economic efficiency of different materials or substances based on their mass.'),
('http://qudt.org/vocab/quantitykind/CostPerPower', 'Cost per Power', 'In photovoltaics, cost per power of electricity produced measures the cost of installing the hardware relative to the power produced.'),
('http://qudt.org/vocab/quantitykind/Count', 'Count', '"Count" is the value of a count of items.'),
('http://qudt.org/vocab/quantitykind/CountRate', 'Count Rate', 'This measure may be used for measuring integer units per second or per hour. For example, it may be used to measure the number of books per hour passing along a part of a mechanical book handling system, the number of people per hour travelling along a moving walkway or the number of vehicles per hour travelling along a section of road.'),
('http://qudt.org/vocab/quantitykind/CouplingFactor', 'Coupling Factor', '"Coupling Factor" is the ratio of an electromagnetic quantity, usually voltage or current, appearing at a specified location of a given circuit to the corresponding quantity at a specified location in the circuit from which energy is transferred by coupling.'),
('http://qudt.org/vocab/quantitykind/CrossSection', 'Cross-section', '"Cross-section" is used to express the likelihood of interaction between particles. For a specified target particle and for a specified reaction or process produced by incident charged or uncharged particles of specified type and energy, it is the mean number of such reactions or processes divided by the incident-particle fluence.'),
('http://qudt.org/vocab/quantitykind/CrossSectionalArea', 'Cross-sectional Area', NULL),
('http://qudt.org/vocab/quantitykind/CubicElectricDipoleMomentPerSquareEnergy', 'Cubic Electric Dipole Moment per Square Energy', NULL),
('http://qudt.org/vocab/quantitykind/CubicExpansionCoefficient', 'Cubic Expansion Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/CurieTemperature', 'Curie Temperature', '"Curie Temperature" is the critical thermodynamic temperature of a ferromagnet.'),
('http://qudt.org/vocab/quantitykind/Currency', 'Currency', 'In economics, currency is a generally accepted medium of exchange. These are usually the coins and banknotes of a particular government, which comprise the physical aspects of a nation''s money supply. The other part of a nation''s money supply consists of bank deposits (sometimes called deposit money), ownership of which can be transferred by means of cheques, debit cards, or other forms of money transfer. Deposit money and currency are money in the sense that both are acceptable as a means of payment.'),
('http://qudt.org/vocab/quantitykind/CurrencyPerFlight', 'Currency per Flight', NULL),
('http://qudt.org/vocab/quantitykind/CurrencyPerTime', 'Currency per Time', 'A rate of currency flow, expressed as an amount of currency per unit time.'),
('http://qudt.org/vocab/quantitykind/CurrentLinkage', 'Current Linkage', '"Current Linkage" is the net electric current through a surface delimited by a closed loop.'),
('http://qudt.org/vocab/quantitykind/CurrentOfTheAmountOfSubstance', 'Current of the Amount of Substance', 'ratio of the amount of substance divided by the related time'),
('http://qudt.org/vocab/quantitykind/Curvature', 'Curvature', 'The canonical example of extrinsic curvature is that of a circle, which has curvature equal to the inverse of its radius everywhere. Smaller circles bend more sharply, and hence have higher curvature. The curvature of a smooth curve is defined as the curvature of its osculating circle at each point. The osculating circle of a sufficiently smooth plane curve at a given point on the curve is the circle whose center lies on the inner normal line and whose curvature is the same as that of the given curve at that point. This circle is tangent to the curve at the given point. That is, given a point P on a smooth curve C, the curvature of C at P is defined to be 1/R where R is the radius of the osculating circle of C at P. The magnitude of curvature at points on physical curves can be measured in diopters (also spelled dioptre) — this is the convention in optics. [Wikipedia],'),
('http://qudt.org/vocab/quantitykind/CurvatureFromRadius', 'Curvature', 'In mathematics "Curvature" is the amount by which a geometric object deviates from being flat, or straight in the case of a line, but this is defined in different ways depending on the context.'),
('http://qudt.org/vocab/quantitykind/CutoffCurrentRating', 'I²t-value', 'cut-off current parameter as rating for fuses and switches, derived from the so-called Joule integral'),
('http://qudt.org/vocab/quantitykind/CyclotronAngularFrequency', 'Larmor Angular Frequency', 'The "Cyclotron Angular Frequency" describes angular momentum vector precession about the external field axis with an angular frequency.'),
('http://qudt.org/vocab/quantitykind/DataCapacity', 'Data Capacity', 'The largest amount of digital data that a storage or transmission medium can hold or convey, expressed as a number of bits or bytes (and their multiples). A specialisation of quantitykind:AmountOfData denoting a maximum or rated capacity rather than an actual quantity stored.'),
('http://qudt.org/vocab/quantitykind/DataRate', 'Data Rate', 'The frequency derived from the period of time required to transmit one bit. This represents the amount of data transferred per second by a communications channel or a computing or storage device. Data rate is measured in units of bits per second (written "b/s" or "bps"), bytes per second (Bps), or baud. When applied to data rate, the multiplier prefixes "kilo-", "mega-", "giga-", etc. (and their abbreviations, "k", "M", "G", etc.) always denote powers of 1000. For example, 64 kbps is 64,000 bits per second. This contrasts with units of storage which use different prefixes to denote multiplication by powers of 1024, for example 1 kibibit = 1024 bits.'),
('http://qudt.org/vocab/quantitykind/DataTransmissionRate', 'Data Transmission Rate', 'The rate at which data is transmitted over a communications channel: a specialisation of quantitykind:DataRate for the transmission context specifically (DataRate itself also covers non-transmission contexts, such as storage read/write or bus throughput).'),
('http://qudt.org/vocab/quantitykind/DatasetOfBits', 'Dataset of Bits', 'A quantity of data expressed as a number of bits. The same quantity as quantitykind:BitDataVolume, from a different source vocabulary (IEC 61360).'),
('http://qudt.org/vocab/quantitykind/DatasetOfBytes', 'Dataset of Bytes', 'A quantity of data expressed as a number of bytes. The same quantity as quantitykind:ByteDataVolume, from a different source vocabulary (IEC 61360).'),
('http://qudt.org/vocab/quantitykind/DebyeAngularFrequency', 'Debye Angular Frequency', '"Debye Angular Frequency" is the cut-off angular frequency in the Debye model of the vibrational spectrum of a solid.'),
('http://qudt.org/vocab/quantitykind/DebyeAngularWavenumber', 'Debye Angular Wavenumber', '"Debye Angular Wavenumber" is the cut-off angular wavenumber in the Debye model of the vibrational spectrum of a solid.'),
('http://qudt.org/vocab/quantitykind/DebyeTemperature', 'Debye Temperature', '"Debye Temperature" is the temperature at which the highest-frequency mode (and hence all modes) are excited.'),
('http://qudt.org/vocab/quantitykind/DebyeWallerFactor', 'Debye-Waller Factor', '"Debye-Waller Factor" (DWF), named after Peter Debye and Ivar Waller, is used in condensed matter physics to describe the attenuation of x-ray scattering or coherent neutron scattering caused by thermal motion. Also, a factor by which the intensity of a diffraction line is reduced because of the lattice vibrations.'),
('http://qudt.org/vocab/quantitykind/DecayConstant', 'Decay Constant', 'The "Decay Constant" is the proportionality between the size of a population of radioactive atoms and the rate at which the population decreases because of radioactive decay.'),
('http://qudt.org/vocab/quantitykind/DegreeOfDissociation', 'Degree of Dissociation', 'The "Degree of Dissociation" is the fraction of original solute molecules that have dissociated.'),
('http://qudt.org/vocab/quantitykind/Density', 'Density', 'The mass density or density of a material is defined as its mass per unit volume. The symbol most often used for density is ρ. Mathematically, density is defined as mass divided by volume: ρ = m/V, where ρ is the density, m is the mass, and V is the volume. In some cases, density is also defined as its weight per unit volume, although this quantity is more properly called specific weight.'),
('http://qudt.org/vocab/quantitykind/DensityInCombustionChamber', 'Density in Combustion Chamber', NULL),
('http://qudt.org/vocab/quantitykind/Depth', 'Depth', 'Depth typically refers to the vertical measure of length from the surface of a liquid.'),
('http://qudt.org/vocab/quantitykind/DewPointTemperature', 'Dew Point Temperature', '"Dew Point Temperature" is the temperature at which vapour in air reaches saturation.'),
('http://qudt.org/vocab/quantitykind/Diameter', 'Diameter', 'In classical geometry, the "Diameter" of a circle is any straight line segment that passes through the center of the circle and whose endpoints lie on the circle.'),
('http://qudt.org/vocab/quantitykind/DiastolicBloodPressure', 'Diastolic Blood Pressure', 'The pressure of blood in the arteries which rises to a maximum as blood is pumped out by the left ventricle (systole) and drops to a minimum in diastole. The systolic/diastolic pressure is normally ~120/80 mmHg in a young adult.'),
('http://qudt.org/vocab/quantitykind/DiffusionArea', 'Diffusion Area', '"Diffusion Area" in an infinite homogenous medium, is one-sixth of the mean square distance between the point where a neutron enters a specified class and the point where it leaves that class.'),
('http://qudt.org/vocab/quantitykind/DiffusionCoefficient', 'Diffusion Coefficient', 'The "Diffusion Coefficient" is a proportionality constant between the molar flux due to molecular diffusion and the gradient in the concentration of the species (or the driving force for diffusion). Diffusivity is encountered in Fick''s law and numerous other equations of physical chemistry.'),
('http://qudt.org/vocab/quantitykind/DiffusionCoefficientForFluenceRate', 'Diffusion Coefficient for Fluence Rate', 'The "Diffusion Coefficient for Fluence Rate" is a proportionality constant between the .'),
('http://qudt.org/vocab/quantitykind/DiffusionLength', 'Diffusion Length', '"Diffusion Length" is the average distance traveled by a particle, or a thermal neutron in a nuclear reactor, from the point at which it is formed to the point at which it is absorbed.'),
('http://qudt.org/vocab/quantitykind/DigitRate', 'Digit Rate', NULL),
('http://qudt.org/vocab/quantitykind/Dimensionless', 'Dimensionless', 'In dimensional analysis, a dimensionless quantity or quantity of dimension one is a quantity without an associated physical dimension. It is thus a "pure" number, and as such always has a dimension of 1. Dimensionless quantities are widely used in mathematics, physics, engineering, economics, and in everyday life (such as in counting). Numerous well-known quantities, such as π, ε, and ψ, are dimensionless. By contrast, non-dimensionless quantities are measured in units of length, area, time, etc. Dimensionless quantities are often defined as products or ratios of quantities that are not dimensionless, but whose dimensions cancel out when their powers are multiplied.'),
('http://qudt.org/vocab/quantitykind/DimensionlessRatio', 'Dimensionless Ratio', NULL),
('http://qudt.org/vocab/quantitykind/Displacement', 'Displacement', '"Displacement" is the shortest distance from the initial to the final position of a point P.'),
('http://qudt.org/vocab/quantitykind/DisplacementCurrent', 'Displacement Current', '"Displacement Current" is a quantity appearing in Maxwell''s equations that is defined in terms of the rate of change of electric displacement field. Displacement current has the units of electric current density, and it has an associated magnetic field just as actual currents do. However it is not an electric current of moving charges, but a time-varying electric field. In materials, there is also a contribution from the slight motion of charges bound in atoms, dielectric polarization.'),
('http://qudt.org/vocab/quantitykind/DisplacementCurrentDensity', 'Displacement Current Density', 'Displacement Current Density is the time rate of change of the Electric Flux Density. This is a measure of how quickly the electric field changes if we observe it as a function of time. This is different than if we look at how the electric field changes spatially, that is, over a region of space for a fixed amount of time.'),
('http://qudt.org/vocab/quantitykind/DisplacementVectorOfIon', 'Displacement Vector of Ion', '"Displacement Vector of Ion" is the .'),
('http://qudt.org/vocab/quantitykind/Dissipance', 'Dissipance', 'Dissipance, or dissipation factor for sound power, is the ratio of dissipated sound power to incident sound power. The dissipation factor (DF) is a measure of loss-rate of energy of a mode of oscillation (mechanical, electrical, or electromechanical) in a dissipative system. It is the reciprocal of quality factor, which represents the quality of oscillation.'),
('http://qudt.org/vocab/quantitykind/Distance', 'Distance', '"Distance" is a numerical description of how far apart objects are.'),
('http://qudt.org/vocab/quantitykind/DistanceTraveledDuringBurn', 'Distance Traveled During a Burn', NULL),
('http://qudt.org/vocab/quantitykind/DonorDensity', 'Donor Density', '"Donor Density" is the number per volume of donor levels.'),
('http://qudt.org/vocab/quantitykind/DonorIonizationEnergy', 'Donor Ionization Energy', '"Donor Ionization Energy" is the ionization energy of a donor.'),
('http://qudt.org/vocab/quantitykind/DoseEquivalent', 'Dose Equivalent', '"Dose Equivalent" (former), or Equivalent Absorbed Radiation Dose, usually shortened to Equivalent Dose, is a computed average measure of the radiation absorbed by a fixed mass of biological tissue, that attempts to account for the different biological damage potential of different types of ionizing radiation. The equivalent dose to a tissue is found by multiplying the absorbed dose, in gray, by a dimensionless "quality factor" Q, dependent upon radiation type, and by another dimensionless factor N, dependent on all other pertinent factors. N depends upon the part of the body irradiated, the time and volume over which the dose was spread, even the species of the subject.'),
('http://qudt.org/vocab/quantitykind/DoseEquivalentQualityFactor', 'Dose Equivalent Quality Factor', '"Dose Equivalent Quality Factor" is a factor in the caculation and measurement of dose equivalent, by which the absorbed dose is to be weighted in order to account for different biological effectiveness of radiations, for radiation protection purposes.'),
('http://qudt.org/vocab/quantitykind/DoseEquivalentRate', 'Dose Equivalent Rate', NULL),
('http://qudt.org/vocab/quantitykind/DotsPerInch', 'Dots per Inch', NULL),
('http://qudt.org/vocab/quantitykind/DragCoefficient', 'Drag Coefficient', 'In fluid dynamics, the drag coefficient is a dimensionless quantity that is used to quantify the drag or resistance of an object in a fluid environment such as air or water.'),
('http://qudt.org/vocab/quantitykind/DragForce', 'Drag Force', 'In fluid dynamics, drag refers to forces which act on a solid object in the direction of the relative fluid flow velocity. Unlike other resistive forces such as dry friction, which is nearly independent of velocity, drag forces depend on velocity. Drag forces always decrease fluid velocity relative to the solid object in the fluid''s path.'),
('http://qudt.org/vocab/quantitykind/DryBulbTemperature', 'Dry Bulb Temperature', 'The temperature of air measured by a thermometer freely exposed to the air, but shielded from radiation.'),
('http://qudt.org/vocab/quantitykind/DryVolume', 'Dry Volume', 'Dry measures are units of volume used to measure bulk commodities which are not gas or liquid. They are typically used in agriculture, agronomy, and commodity markets to measure grain, dried beans, and dried and fresh fruit; formerly also salt pork and fish. They are also used in fishing for clams, crabs, etc. and formerly for many other substances (for example coal, cement, lime) which were typically shipped and delivered in a standardized container such as a barrel. In the original metric system, the unit of dry volume was the stere, but this is not part of the modern metric system; the liter and the cubic meter (m^3) are now used. However, the stere is still widely used for firewood.'),
('http://qudt.org/vocab/quantitykind/DutyCycle', 'Duty Cycle', 'A duty cycle or power cycle is the fraction of one period in which a signal or system is active.'),
('http://qudt.org/vocab/quantitykind/Duv', 'Delta u,v', 'Duv is a metric that is short for Delta u,v (not to be confused with Delta u'',v'') and describes the distance of a light color point from the black body curve.'),
('http://qudt.org/vocab/quantitykind/DynamicFriction', 'Dynamic Friction', 'Kinetic (or dynamic) friction occurs when two objects are moving relative to each other and rub together (like a sled on the ground).'),
('http://qudt.org/vocab/quantitykind/DynamicFrictionCoefficient', 'Dynamic Friction Coefficient', 'Kinetic (or dynamic) friction occurs when two objects are moving relative to each other and rub together (like a sled on the ground).'),
('http://qudt.org/vocab/quantitykind/DynamicPressure', 'Dynamic Pressure', 'Dynamic Pressure (indicated with q, or Q, and sometimes called velocity pressure) is the quantity defined by: q = 1/2 * ρ v^2, where (using SI units), q is dynamic pressure in pascals, ρ is fluid density in kg/m^3 (for example, density of air) and v is fluid velocity in m/s.'),
('http://qudt.org/vocab/quantitykind/DynamicViscosity', 'Dynamic Viscosity', 'A measure of the molecular frictional resistance of a fluid as calculated using Newton''s law.'),
('http://qudt.org/vocab/quantitykind/EarthquakeMagnitude', 'Earthquake Magnitude', NULL),
('http://qudt.org/vocab/quantitykind/EccentricityOfOrbit', 'Eccentricity of Orbit', 'The orbital eccentricity of an astronomical object is a parameter that determines the amount by which its orbit around another body deviates from a perfect circle. In a two-body problem with inverse-square-law force, every orbit is a Kepler orbit. The eccentricity of this Kepler orbit is a positive number that defines its shape.'),
('http://qudt.org/vocab/quantitykind/EffectiveMass', 'Effective Mass', '"Effective Mass" is used in the motional equation for electrons in solid state bodies, depending on the wavenumber and corresponding to its velocity and energy level.'),
('http://qudt.org/vocab/quantitykind/EffectiveMultiplicationFactor', 'Effective Multiplication Factor', 'The "Effective Multiplication Factor" is the multiplication factor for a finite medium.'),
('http://qudt.org/vocab/quantitykind/Efficiency', 'Efficiency', 'Efficiency is the ratio of output power to input power.'),
('http://qudt.org/vocab/quantitykind/EinsteinCoefficients', 'Einstein Coefficients', 'The Einstein coefficients characterize the probability per unit time of radiative transitions between two energy levels of an atom or molecule: spontaneous emission, and absorption or stimulated emission in proportion to the spectral energy density of the radiation field. This quantity kind covers the induced (B) coefficients, expressed per spectral radiance, with unit second per kilogram.'),
('http://qudt.org/vocab/quantitykind/EinsteinTransitionProbability', 'Einstein Transition Probability', 'Given two atomic states of energy E_j and E_k. Let E_j > E_k. Assume the atom is bathed in radiation of energy density u(w). Transitions between these states can take place in three different ways. Spontaneous, induced/stimulated emission, and induced absorption. A_jk represents the Einstein transition probability for spontaneous emission.'),
('http://qudt.org/vocab/quantitykind/EinsteinTransitionProbabilityForSpontaneousOrInducedEmissionAndAbsorption', 'Einstein Transition Probability for Spontaneous Or Induced Emission and Absorption', 'nuclear constant for the special transition where the probability of the absorption, spontaneous emission or induced emission of energy depends on the number of existing quantums of light, expressed as energy density in the wave model of light: energy divided by volume and frequency'),
('http://qudt.org/vocab/quantitykind/ElectricCharge', 'Electric Charge', '"Electric Charge" is a fundamental conserved property of some subatomic particles, which determines their electromagnetic interaction. Electrically charged matter is influenced by, and produces, electromagnetic fields. The electric charge on a body may be positive or negative. Two positively charged bodies experience a mutual repulsive force, as do two negatively charged bodies. A positively charged body and a negatively charged body experience an attractive force. Electric charge is carried by discrete particles and can be positive or negative. The sign convention is such that the elementary electric charge e, that is, the charge of the proton, is positive. The SI derived unit of electric charge is the coulomb.'),
('http://qudt.org/vocab/quantitykind/ElectricChargeDensity', 'Electric Charge Density', 'In electromagnetism, charge density is a measure of electric charge per unit volume of space, in one, two or three dimensions. More specifically: the linear, surface, or volume charge density is the amount of electric charge per unit length, surface area, or volume, respectively.'),
('http://qudt.org/vocab/quantitykind/ElectricChargeLineDensity', 'Electric Charge Line Density', 'In electromagnetism, charge density is a measure of electric charge per unit volume of space, in one, two or three dimensions. More specifically: the linear, surface, or volume charge density is the amount of electric charge per unit length, surface area, or volume, respectively. The respective SI units are C · , m^-1, C · m^-2 or C · m^-3.'),
('http://qudt.org/vocab/quantitykind/ElectricChargePerAmountOfSubstance', 'Electric Charge per Amount of Substance', '"Electric Charge Per Amount Of Substance" is the charge assocated with a given amount of substance. Un the ISO and SI systems this is 1 mol.'),
('http://qudt.org/vocab/quantitykind/ElectricChargePerArea', 'Electric Charge per Area', 'In electromagnetism, charge density is a measure of electric charge per unit volume of space, in one, two or three dimensions. More specifically: the linear, surface, or volume charge density is the amount of electric charge per unit length, surface area, or volume, respectively. The respective SI units are C · m^-1, C · m^-2 or C · m^-3.'),
('http://qudt.org/vocab/quantitykind/ElectricChargePerMass', 'Electric Charge per Mass', '"Electric Charge Per Mass" is the charge associated with a specific mass of a substance. In the SI and ISO systems this is 1 kg.'),
('http://qudt.org/vocab/quantitykind/ElectricChargeSurfaceDensity', 'Electric Charge Surface Density', 'In electromagnetism, charge density is a measure of electric charge per unit volume of space, in one, two or three dimensions. More specifically: the linear, surface, or volume charge density is the amount of electric charge per unit length, surface area, or volume, respectively.'),
('http://qudt.org/vocab/quantitykind/ElectricChargeVolumeDensity', 'Electric Charge Volume Density', 'In electromagnetism, charge density is a measure of electric charge per unit volume of space, in one, two or three dimensions. More specifically: the linear, surface, or volume charge density is the amount of electric charge per unit length, surface area, or volume, respectively. The respective SI units are C · m^-1, C · m^-2 or C · m^-3.'),
('http://qudt.org/vocab/quantitykind/ElectricConductivity', 'Electric Conductivity', '"Electric Conductivity" is a scalar or tensor quantity the product of which by the electric field strength in a medium is equal to the electric current density. For an isotropic medium the conductivity is a scalar quantity; for an anisotropic medium it is a tensor quantity.'),
('http://qudt.org/vocab/quantitykind/ElectricCurrent', 'Electric Current', '"Electric Current" is the flow (movement) of electric charge. The amount of electric current through some surface, for example, a section through a copper conductor, is defined as the amount of electric charge flowing through that surface over time. Current is a scalar-valued quantity. Electric current is one of the base quantities in the International System of Quantities, ISQ, on which the International System of Units, SI, is based.'),
('http://qudt.org/vocab/quantitykind/ElectricCurrentDensity', 'Electric Current Density', '"Electric Current Density" is a measure of the density of flow of electric charge; it is the electric current per unit area of cross section. Electric current density is a vector-valued quantity. Electric current, I, through a surface S is defined as I = ∫_S J · e_n dA, where e_ndA is the vector surface element.'),
('http://qudt.org/vocab/quantitykind/ElectricCurrentImbalance', 'Electric Current Imbalance', 'Electric current imbalance is the percentage deviation of individual phase currents from the average current across phases in a polyphase electrical system.'),
('http://qudt.org/vocab/quantitykind/ElectricCurrentPerAngle', 'Electric Current per Angle', NULL),
('http://qudt.org/vocab/quantitykind/ElectricCurrentPerEnergy', 'Electric Current per Energy', NULL),
('http://qudt.org/vocab/quantitykind/ElectricCurrentPerLength', 'Electric Current per Length', NULL),
('http://qudt.org/vocab/quantitykind/ElectricCurrentPerTemperature', 'Electric Current per Temperature', '"Electric Current per Temperature" is used to express how a current is subject to temperature. Originally used in Wien''s Law to describe phenomena related to filaments. One use today is to express how a current generator derates with temperature.'),
('http://qudt.org/vocab/quantitykind/ElectricCurrentPhasor', 'Electric Current Phasor', '"Electric Current Phasor" is a representation of current as a sinusoidal integral quantity using a complex quantity whose argument is equal to the initial phase and whose modulus is equal to the root-mean-square value. A phasor is a constant complex number, usually expressed in exponential form, representing the complex amplitude (magnitude and phase) of a sinusoidal function of time. Phasors are used by electrical engineers to simplify computations involving sinusoids, where they can often reduce a differential equation problem to an algebraic one.'),
('http://qudt.org/vocab/quantitykind/ElectricDipoleMoment', 'Electric Dipole Moment', '"Electric Dipole Moment" is a measure of the separation of positive and negative electrical charges in a system of (discrete or continuous) charges. It is a vector-valued quantity. If the system of charges is neutral, that is if the sum of all charges is zero, then the dipole moment of the system is independent of the choice of a reference frame; however in a non-neutral system, such as the dipole moment of a single proton, a dependence on the choice of reference point arises. In such cases it is conventional to choose the reference point to be the center of mass of the system or the center of charge, not some arbitrary origin. This convention ensures that the dipole moment is an intrinsic property of the system. The electric dipole moment of a substance within a domain is the vector sum of electric dipole moments of all electric dipoles included in the domain.'),
('http://qudt.org/vocab/quantitykind/ElectricDisplacement', 'Electric Displacement', 'In a dielectric material the presence of an electric field E causes the bound charges in the material (atomic nuclei and their electrons) to slightly separate, inducing a local electric dipole moment. The Electric Displacement Field, D, is a vector field that accounts for the effects of free charges within such dielectric materials. This describes also the charge density on an extended surface that could be causing the field.'),
('http://qudt.org/vocab/quantitykind/ElectricDisplacementField', 'Electric Displacement Field', NULL),
('http://qudt.org/vocab/quantitykind/ElectricEnergy', 'Electric Energy', 'Electric energy is the energy transferred to or from an electrical circuit over time. It is the integral of electric power over time and is commonly measured in watt-hours (Wh) or kilowatt-hours (kWh).'),
('http://qudt.org/vocab/quantitykind/ElectricField', 'Electric Field', 'The space surrounding an electric charge or in the presence of a time-varying magnetic field has a property called an electric field. This electric field exerts a force on other electrically charged objects. In the idealized case, the force exerted between two point charges is inversely proportional to the square of the distance between them. (Coulomb''s Law).'),
('http://qudt.org/vocab/quantitykind/ElectricFieldStrength', 'Electric Field Strength', 'Electric Field Strength is the magnitude and direction of an electric field, expressed by the value of E, also referred to as electric field intensity or simply the electric field.'),
('http://qudt.org/vocab/quantitykind/ElectricFlux', 'Electric Flux', '"Electric Flux" through an area is defined as the electric field multiplied by the area of the surface projected in a plane perpendicular to the field. Electric Flux is a scalar-valued quantity.'),
('http://qudt.org/vocab/quantitykind/ElectricFluxDensity', 'Electric Flux Density', 'Electric Flux Density, also referred to as Electric Displacement, is related to electric charge density by the following equation: div D = ρ, where div denotes the divergence.'),
('http://qudt.org/vocab/quantitykind/ElectricPolarizability', 'Electric Polarizability', '"Electric Polarizability" is the relative tendency of a charge distribution, like the electron cloud of an atom or molecule, to be distorted from its normal shape by an external electric field, which is applied typically by inserting the molecule in a charged parallel-plate capacitor, but may also be caused by the presence of a nearby ion or dipole.'),
('http://qudt.org/vocab/quantitykind/ElectricPolarization', 'Electric Polarization', '"Electric Polarization" is the relative shift of positive and negative electric charge in opposite directions within an insulator, or dielectric, induced by an external electric field. Polarization occurs when an electric field distorts the negative cloud of electrons around positive atomic nuclei in a direction opposite the field. This slight separation of charge makes one side of the atom somewhat positive and the opposite side somewhat negative. In some materials whose molecules are permanently polarized by chemical forces, such as water molecules, some of the polarization is caused by molecules rotating into the same alignment under the influence of the electric field. One of the measures of polarization is electric dipole moment, which equals the distance between the slightly shifted centres of positive and negative charge multiplied by the amount of one of the charges. Polarization P in its quantitative meaning is the amount of dipole moment p per unit volume V of a polarized material, P = p/V.'),
('http://qudt.org/vocab/quantitykind/ElectricPotential', 'Electric Potential', 'The Electric Potential is a scalar valued quantity associated with an electric field. The electric potential φ(x) at a point, x, is formally defined as the line integral of the electric field taken along a path from x to the point at infinity. If the electric field is static, that is time independent, then the choice of the path is arbitrary; however if the electric field is time dependent, taking the integral a different paths will produce different results.'),
('http://qudt.org/vocab/quantitykind/ElectricPotentialDifference', 'Electric Potential Difference', '"Electric Potential Difference" is a scalar valued quantity associated with an electric field.'),
('http://qudt.org/vocab/quantitykind/ElectricPower', 'Electric Power', '"Electric Power" is the rate at which electrical energy is transferred by an electric circuit. In the simple case of direct current circuits, electric power can be calculated as the product of the potential difference in the circuit (V) and the amount of current flowing in the circuit (I): P = VI, where P is the power, V is the potential difference, and I is the current. However, in general electric power is calculated by taking the integral of the vector cross-product of the electrical and magnetic fields over a specified area.'),
('http://qudt.org/vocab/quantitykind/ElectricQuadrupoleMoment', 'Electric Quadrupole Moment', 'The Electric Quadrupole Moment is a quantity which describes the effective shape of the ellipsoid of nuclear charge distribution. A non-zero quadrupole moment Q indicates that the charge distribution is not spherically symmetric. By convention, the value of Q is taken to be positive if the ellipsoid is prolate and negative if it is oblate. In general, the electric quadrupole moment is tensor-valued.'),
('http://qudt.org/vocab/quantitykind/ElectricSusceptibility', 'Electric Susceptibility', '"Electric Susceptibility" is the ratio of electric polarization to electric field strength, normalized to the electric constant. The definition applies to an isotropic medium. For an anisotropic medium, electric susceptibility is a second order tensor.'),
('http://qudt.org/vocab/quantitykind/ElectricalConductance', 'Electrical Conductance', 'measure of the capability of a material to conduct electric current, the value of which is defined as the reciprocal of the electrical resistance'),
('http://qudt.org/vocab/quantitykind/ElectricalPowerToMassRatio', 'Electrical Power to Mass Ratio', NULL),
('http://qudt.org/vocab/quantitykind/ElectricalResistance', 'Electrical Resistance', 'different properties of materials which impede the electrical current in its movement when the free charged particles in these materials are set in motion by electrical fields and/or electrical potentials'),
('http://qudt.org/vocab/quantitykind/ElectrolyticConductivity', 'Electrolytic Conductivity', '"Electrolytic Conductivity" of an electrolyte solution is a measure of its ability to conduct electricity.'),
('http://qudt.org/vocab/quantitykind/ElectromagneticEnergyDensity', 'Electromagnetic Energy Density', 'Electromagnetic Energy Density, also known as the Volumic Electromagnetic Energy, is the energy associated with an electromagnetic field, per unit volume of the field.'),
('http://qudt.org/vocab/quantitykind/ElectromagneticPermeability', 'Permeability', 'Permeability is the degree of magnetization of a material that responds linearly to an applied magnetic field. In general permeability is a tensor-valued quantity. The definition given applies to an isotropic medium. For an anisotropic medium permeability is a second order tensor. In electromagnetism, permeability is the measure of the ability of a material to support the formation of a magnetic field within itself. In other words, it is the degree of magnetization that a material obtains in response to an applied magnetic field. Magnetic permeability is typically represented by the Greek letter μ. The term was coined in September, 1885 by Oliver Heaviside. The reciprocal of magnetic permeability is Magnetic Reluctivity.'),
('http://qudt.org/vocab/quantitykind/ElectromagneticPermeabilityRatio', 'Electromagnetic Permeability Ratio', 'The ratio of the electromagnetic permeability of a specific medium to the electromagnetic permeability of free space.'),
('http://qudt.org/vocab/quantitykind/ElectromagneticWavePhaseSpeed', 'Electromagnetic Wave Phase Speed', '"Electromagnetic Wave Phase Speed" is the ratio of angular velocity and wavenumber.'),
('http://qudt.org/vocab/quantitykind/ElectromotiveForce', 'Electromotive Force', 'In physics, Electromotive Force, or most commonly emf (seldom capitalized), or (occasionally) electromotance is that which tends to cause current (actual electrons and ions) to flow. More formally, emf is the external work expended per unit of charge to produce an electric potential difference across two open-circuited terminals. Electromotive Force is deprecated in the ISO System of Quantities.'),
('http://qudt.org/vocab/quantitykind/ElectronAffinity', 'Electron Affinity', '"Electron Affinity" is the energy difference between an electron at rest at infinity and an electron at the lowest level of the conduction band in an insulator or semiconductor. The the amount of energy released when an electron is added to a neutral atom or molecule to form a negative ion.'),
('http://qudt.org/vocab/quantitykind/ElectronDensity', 'Electron Density', '"Electron Density" is the number of electrons per volume in conduction bands. It is the measure of the probability of an electron being present at a specific location.'),
('http://qudt.org/vocab/quantitykind/ElectronMeanFreePath', 'Electron Mean Free Path', '"Electron Mean Free Path" is the mean free path of electrons.'),
('http://qudt.org/vocab/quantitykind/ElectronMobility', 'Electron Mobility', NULL),
('http://qudt.org/vocab/quantitykind/ElectronRadius', 'Electron Radius', '"Electron Radius", also known as the Lorentz radius or the Thomson scattering length, is based on a classical (i.e., non-quantum) relativistic model of the electron.'),
('http://qudt.org/vocab/quantitykind/ElevationRelativeToNAP', 'Elevation Relative to NAP', 'Height measurement relative to the Normaal Amsterdams Peil (NAP) (en: Amsterdam Ordnance System). Being a form of gravity related height'),
('http://qudt.org/vocab/quantitykind/Emissivity', 'Emissivity', 'Emissivity of a material (usually written ε or e) is the relative ability of its surface to emit energy by radiation.'),
('http://qudt.org/vocab/quantitykind/Energy', 'Energy', 'Energy is the quantity characterizing the ability of a system to do work.'),
('http://qudt.org/vocab/quantitykind/EnergyContent', 'Energy Content', 'saved quantity of energy which can be used physically or chemically'),
('http://qudt.org/vocab/quantitykind/EnergyDensity', 'Energy Density', 'Energy density is defined as energy per unit volume. The SI unit for energy density is the joule per cubic meter.'),
('http://qudt.org/vocab/quantitykind/EnergyDensityOfStates', 'Energy Density of States', '"Energy Density of States" refers to electrons or other entities, e.g. phonons. It quantifies the numnber of states in an infitesimal energy range, per volume, and has dimensionality of inverse energy times inverse volume.'),
('http://qudt.org/vocab/quantitykind/EnergyExpenditure', 'Energy Expenditure', 'Energy expenditure is dependent on a person''s sex, metabolic rate, body-mass composition, the thermic effects of food, and activity level. The approximate energy expenditure of a man lying in bed is 1.0 kilo calorie per hour per kilogram. For slow walking (just over two miles per hour), 3.0 kilo calorie per hour per kilogram. For fast steady running (about 10 miles per hour), 16.3 kilo calorie per hour per kilogram. Females expend about 10 per cent less energy than males of the same size doing a comparable activity. For people weighing the same, individuals with a high percentage of body fat usually expend less energy than lean people, because fat is not as metabolically active as muscle.'),
('http://qudt.org/vocab/quantitykind/EnergyFluence', 'Energy Fluence', '"Energy Fluence" can be used to describe the energy delivered per unit area'),
('http://qudt.org/vocab/quantitykind/EnergyFluenceRate', 'Energy Fluence Rate', '"Energy Fluence Rate" can be used to describe the energy fluence delivered per unit time.'),
('http://qudt.org/vocab/quantitykind/EnergyImparted', 'Energy Imparted', 'The "Energy Imparted", is a physical quantity associated with the energy delivered to a particular volume of matter by all the directly and indirectly ionizing particles (i.e. charged and uncharged) entering that volume.'),
('http://qudt.org/vocab/quantitykind/EnergyLevel', 'Energy Level', '"Energy Level" is the ionization energy for an electron at the Fermi energy in the interior of a substance.'),
('http://qudt.org/vocab/quantitykind/EnergyPerArea', 'Energy per Area', 'Energy per unit area is a measure of the energy either impinging upon or generated from a given unit of area. This can be a measure of the "toughness" of a material, being the amount of energy that needs to be applied per unit area of a crack to cause it to fracture. This is a constant for a given material..'),
('http://qudt.org/vocab/quantitykind/EnergyPerAreaElectricCharge', 'Energy per Area Electric Charge', '"Energy Per Area Electric Charge" is the amount of electric energy associated with a unit of area.'),
('http://qudt.org/vocab/quantitykind/EnergyPerElectricCharge', 'Energy per Electric Charge', 'Voltage is a representation of the electric potential energy per unit charge. If a unit of electrical charge were placed in a location, the voltage indicates the potential energy of it at that point. In other words, it is a measurement of the energy contained within an electric field, or an electric circuit, at a given point. Voltage is a scalar quantity. The SI unit of voltage is the volt, such that 1 volt = 1 joule/coulomb.'),
('http://qudt.org/vocab/quantitykind/EnergyPerMassAmountOfSubstance', 'Energy and Work per Mass Amount of Substance', NULL),
('http://qudt.org/vocab/quantitykind/EnergyPerSquareMagneticFluxDensity', 'Energy per Square Magnetic Flux Density', '"Energy Per Square Magnetic Flux Density" is a measure of energy for a unit of magnetic flux density.'),
('http://qudt.org/vocab/quantitykind/EnergyPerTemperature', 'Energy per Temperature', NULL),
('http://qudt.org/vocab/quantitykind/Enthalpy', 'Enthalpy', 'In thermodynamics, enthalpy is the sum of the internal energy U and the product of pressure p and volume V of a system. The characteristic function (also known as thermodynamic potential) enthalpy used to be called heat content, which is why it is conventionally indicated by H. The specific enthalpy of a working mass is a property of that mass used in thermodynamics, defined as h=u+p · v, where u is the specific internal energy, p is the pressure, and v is specific volume. In other words, h = H / m where m is the mass of the system. The SI unit for Specific Enthalpy is joules per kilogram'),
('http://qudt.org/vocab/quantitykind/Entropy', 'Entropy', 'When a small amount of heat dQ is received by a system whose thermodynamic temperature is T, the entropy of the system increases by dQ/T, provided that no irreversible change takes place in the system.'),
('http://qudt.org/vocab/quantitykind/EquilibriumConstant', 'Equilibrium Constant', 'The "Equlilbrium Constant", also known as the thermodynamic equilibrium constant, is an expression that gives us a ratio of the products and reactants of a reaction at equilibrium with respect to a specific unit.'),
('http://qudt.org/vocab/quantitykind/EquilibriumConstantBasedOnConcentration', 'Equilibrium Constant Based On Concentration', 'The equilibrium constant of a reaction in solution expressed in absolute concentration units: Kc = ΠB(cB)νB, the product of the equilibrium amount-of-substance concentrations raised to their stoichiometric numbers. This is the dimensional form, maintained from the ECLASS vocabulary, carrying the dimension of amount-of-substance concentration with values typically quoted in mol/L. The IEC 61360 / ISO 80000 vocabularies model the same concept as a dimensionless quantity by referring each concentration to its standard value — that dimensionless form is maintained separately as quantitykind:EquilibriumConstantOnConcentrationBasis, because the two dimension conventions cannot be reconciled by a fixed conversion factor.'),
('http://qudt.org/vocab/quantitykind/EquilibriumConstantBasedOnPressure', 'Equilibrium Constant Based On Pressure', 'The equilibrium constant of a gas-phase reaction expressed in absolute pressure units: Kp = ΠB(pB)νB, the product of the equilibrium partial pressures raised to their stoichiometric numbers. This is the dimensional form, maintained from the ECLASS vocabulary, carrying the dimension of pressure with values typically quoted in Pa or bar. The IEC 61360 / ISO 80000 vocabularies model the same concept as a dimensionless quantity by referring each partial pressure to the standard pressure — that dimensionless form is maintained separately as quantitykind:EquilibriumConstantOnPressureBasis, because the two dimension conventions cannot be reconciled by a fixed conversion factor.'),
('http://qudt.org/vocab/quantitykind/EquilibriumConstantOnConcentrationBasis', 'Equilibrium Constant On Concentration Basis', 'The equilibrium constant of a reaction in solution expressed on a concentration basis, Kc: the product of the equilibrium amount-of-substance concentrations raised to their stoichiometric numbers, with each concentration referred to its standard value so that the quantity is dimensionless. This dimensionless convention follows the ISO 80000 / IEC 61360 vocabularies. The ECLASS vocabulary models the same concept dimensionally, with concentrations in absolute units — that form is maintained separately as quantitykind:EquilibriumConstantBasedOnConcentration, because the two dimension conventions cannot be reconciled by a fixed conversion factor.'),
('http://qudt.org/vocab/quantitykind/EquilibriumConstantOnPressureBasis', 'Equilibrium Constant On Pressure Basis', 'The equilibrium constant of a gas-phase reaction expressed on a pressure basis, Kp: the product of the equilibrium partial pressures raised to their stoichiometric numbers, with each partial pressure referred to the standard pressure so that the quantity is dimensionless. This dimensionless convention follows the ISO 80000 / IEC 61360 vocabularies. The ECLASS vocabulary models the same concept dimensionally, with partial pressures in absolute units — that form is maintained separately as quantitykind:EquilibriumConstantBasedOnPressure, because the two dimension conventions cannot be reconciled by a fixed conversion factor.'),
('http://qudt.org/vocab/quantitykind/EquilibriumPositionVectorOfIon', 'Equilibrium Position Vector of Ion', '"Equilibrium Position Vector of Ion" is the position vector of a particle in equilibrium.'),
('http://qudt.org/vocab/quantitykind/EquivalenceDoseOutput', 'Equivalence Dose Output', 'ratio of equivalence dose within an appropriately small interval to this interval, calculated as the differential quotient: q • D = q • ∂D/∂t as a measure of the current radiation exposure'),
('http://qudt.org/vocab/quantitykind/EquivalentAbsorptionArea', 'Equivalent Absorption Area', 'In a diffuse sound field, the Equivalent Absorption Area is that area of a surface having an absorption factor equal to 1, which, if diffraction effects are neglected, would, in the same diffuse sound field, absorb the same power.'),
('http://qudt.org/vocab/quantitykind/EquivalentConcentration', 'Equivalent Concentration', 'The amount of a substance that reacts with (or is equivalent to) an arbitrary amount (typically one mole) of another substance in a given chemical reaction, per volume.'),
('http://qudt.org/vocab/quantitykind/EquivalentDensity', 'Equivalent Density', '"Equivalent Density" is the mass of a substance that reacts with (or is equivalent to) an arbitrary mass of another substance in a given chemical reaction, per volume.'),
('http://qudt.org/vocab/quantitykind/EvaporativeHeatTransfer', 'Evaporative Heat Transfer', '"Evaporative Heat Transfer" is the heat flow rate due to evaporation, given by the evaporative heat transfer coefficient multiplied by the water-vapour partial pressure difference and the surface area.'),
('http://qudt.org/vocab/quantitykind/EvaporativeHeatTransferCoefficient', 'Evaporative Heat Transfer Coefficient', '"Evaporative Heat Transfer Coefficient" is the areic heat transfer coefficient multiplied by the water vapour pressure difference between skin and the environment, and by the exchange area.'),
('http://qudt.org/vocab/quantitykind/ExchangeIntegral', 'Exchange Integral', '"Exchange Integral" is the constituent of the interaction energy between the spins of adjacent electrons in matter arising from the overlap of electron state functions.'),
('http://qudt.org/vocab/quantitykind/ExpansionRatio', 'Expansion Ratio', NULL),
('http://qudt.org/vocab/quantitykind/Exposure', 'Exposure', '"Exposure" reflects the extent of ionization events taking place when air is irradiated by ionizing photons (gamma radiation and/or x rays). In photography, exposure is the amount of light allowed to fall on each area unit of a photographic medium (photographic film or image sensor) during the process of taking a photograph. Exposure is measured in lux seconds, and can be computed from exposure value (EV) and scene luminance in a specified region.'),
('http://qudt.org/vocab/quantitykind/ExposureOfIonizingRadiation', 'Exposure of Ionizing Radiation', 'measure of an electromagnetic radiation field to which a material is exposed in terms of ionization, which the radiation produces as reference material air, expressed as ratio of ∂Q and ∂m, where ∂Q is the absolute value of the total charge of the ions of one sign produced in the air of mass ∂m when all of the electrons (and positrons) liberated by photons in this mass element are completely stopped'),
('http://qudt.org/vocab/quantitykind/ExposureRate', 'Exposure Rate', '"Exposure Rate" expresses the rate of charge production per unit mass of air and is commonly expressed in roentgens per hour (R/h) or milliroentgens per hour (mR/h).'),
('http://qudt.org/vocab/quantitykind/ExposureRateOfIonizingRadiation', 'Exposure Rate of Ionizing Radiation', 'ratio between the exposure of ionizing radiation dJ in a time interval and the duration dt of this interval'),
('http://qudt.org/vocab/quantitykind/ExtentOfReaction', 'Extent of Reaction', 'In physical chemistry, the "Extent of Reaction" is a quantity that measures the extent in which the reaction proceeds.'),
('http://qudt.org/vocab/quantitykind/FahrenheitTemperature', 'Fahrenheit Temperature', 'quantity whose zero point is defined by the temperature of a mixture of ice, water and ammonium chloride (-17.8 °C) and its fixed points on the Fahrenheit scale are 32 °F (melting point of ice) and 212 °F (boiling point of water)'),
('http://qudt.org/vocab/quantitykind/FailureRate', 'Failure Rate', 'limiting value - if it exists - of the ratio between the conditional probability that the fault time t of a resource will fall within a defined interval (t, t + Δt), and the duration of this interval if Δt approaches zero and the unit is in an operational state at the beginning of the interval'),
('http://qudt.org/vocab/quantitykind/FastFissionFactor', 'Fast Fission Factor', '"Fast Fission Factor" in an infinite medium, is the ratio of the mean number of neutrons produced by fission due to neutrons of all energies to the mean number of neutrons produced by fissions due to thermal neutrons only.'),
('http://qudt.org/vocab/quantitykind/FermiAngularWavenumber', 'Fermi Angular Wavenumber', NULL),
('http://qudt.org/vocab/quantitykind/FermiEnergy', 'Fermi Energy', '"Fermi Energy" in a metal is the highest occupied energy level at zero thermodynamic temperature.'),
('http://qudt.org/vocab/quantitykind/FermiTemperature', 'Fermi Temperature', '"Fermi Temperature" is the temperature associated with the Fermi energy.'),
('http://qudt.org/vocab/quantitykind/FirstMomentOfArea', 'First Moment of Area', 'The first moment of area is the summation of area times distance to an axis. It is a measure of the distribution of the area of a shape in relationship to an axis.'),
('http://qudt.org/vocab/quantitykind/FishBiotransformationHalfLife', 'Fish Biotransformation Half Life', 'A time that quantifies how long its takes to transform 50% of a substance''s total concentration from any concentration point in time in fish via whole body metabolic reactions.'),
('http://qudt.org/vocab/quantitykind/FissionCoreRadiusToHeightRatio', 'Fission Core Radius to Height Ratio', NULL),
('http://qudt.org/vocab/quantitykind/FissionFuelUtilizationFactor', 'Fission Fuel Utilization Factor', NULL),
('http://qudt.org/vocab/quantitykind/FissionMultiplicationFactor', 'Fission Multiplication Factor', 'The number of fission neutrons produced per absorption in the fuel.'),
('http://qudt.org/vocab/quantitykind/FlashPoint', 'Flash Point Temperature', 'A temperature that is the lowest one at which the vapours of a volatile material will ignite if exposed to an ignition source. It is frequently used to characterize fire hazards and distinguish different flammable fuels.'),
('http://qudt.org/vocab/quantitykind/FlightPathAngle', 'Flight Path Angle', 'Flight path angle is defined in two different ways. To the aerodynamicist, it is the angle between the flight path vector (where the airplane is going) and the local atmosphere. To the flight crew, it is normally known as the angle between the flight path vector and the horizon, also known as the climb (or descent) angle.'),
('http://qudt.org/vocab/quantitykind/FloatingPointCalculationCapability', 'Floating Point Calculation Capability', NULL),
('http://qudt.org/vocab/quantitykind/Fluidity', 'Fluidity', 'fluidity of a material as complement of the dynamic viscosity'),
('http://qudt.org/vocab/quantitykind/Flux', 'Flux', 'Flux describes any effect that appears to pass or travel (whether it actually moves or not) through a surface or substance. [Wikipedia]'),
('http://qudt.org/vocab/quantitykind/Force', 'Force', '"Force" is an influence that causes mass to accelerate. It may be experienced as a lift, a push, or a pull. Force is defined by Newton''s Second Law as F = m × a , where F is force, m is mass and a is acceleration. Net force is mathematically equal to the time rate of change of the momentum of the body on which it acts. Since momentum is a vector quantity (has both a magnitude and direction), force also is a vector quantity.'),
('http://qudt.org/vocab/quantitykind/ForceConstant', 'Force Constant', 'The force constant of an electromechanical transducer such as a linear motor or voice coil: the quotient of the force produced and the current through the device (F = k·I), expressed in newtons per ampere. Equal to the product of the magnetic flux density and the effective conductor length (k = B·l), and numerically equal to the back-EMF constant in V·s/m. Not to be confused with the spring constant of mechanics (force per displacement, N/m); for that quantity see quantitykind:ForcePerLength.'),
('http://qudt.org/vocab/quantitykind/ForceMagnitude', 'Force Magnitude', 'The ''magnitude'' of a force is its ''size'' or ''strength'', regardless of the direction in which it acts.'),
('http://qudt.org/vocab/quantitykind/ForcePerAngle', 'Force per Angle', NULL),
('http://qudt.org/vocab/quantitykind/ForcePerArea', 'Force per Area', 'The force applied to a unit area of surface; measured in pascals (SI unit) or in dynes (cgs unit)'),
('http://qudt.org/vocab/quantitykind/ForcePerAreaTime', 'Force per Area Time', NULL),
('http://qudt.org/vocab/quantitykind/ForcePerElectricCharge', 'Force per Electric Charge', 'The electric field depicts the force exerted on other electrically charged objects by the electrically charged particle the field is surrounding. The electric field is a vector field with SI units of newtons per coulomb (N C^-1) or, equivalently, volts per metre (V m^-1 ). The SI base units of the electric field are kg m s^-3 A^-1. The strength or magnitude of the field at a given point is defined as the force that would be exerted on a positive test charge of 1 coulomb placed at that point'),
('http://qudt.org/vocab/quantitykind/ForcePerLength', 'Force per Length', NULL),
('http://qudt.org/vocab/quantitykind/Frequency', 'Frequency', '"Frequency" is the number of occurrences of a repeating event per unit time. The repetition of the events may be periodic (that is. the length of time between event repetitions is fixed) or aperiodic (i.e. the length of time between event repetitions varies). Therefore, we distinguish between periodic and aperiodic frequencies. In the SI system, periodic frequency is measured in hertz (Hz) or multiples of hertz, while aperiodic frequency is measured in becquerel (Bq). In spectroscopy, ν is mostly used. Light passing through different media keeps its frequency, but not its wavelength or wavenumber.'),
('http://qudt.org/vocab/quantitykind/Friction', 'Friction', '"Friction" is the force of two surfaces In contact, or the force of a medium acting on a moving object (that is air on an aircraft). When contacting surfaces move relative to each other, the friction between the two objects converts kinetic energy into thermal energy.'),
('http://qudt.org/vocab/quantitykind/FrictionCoefficient', 'Friction Coefficient', '"Friction Coefficient" is the ratio of the force of friction between two bodies and the force pressing them together'),
('http://qudt.org/vocab/quantitykind/Fugacity', 'Fugacity', '"Fugacity" of a real gas is an effective pressure which replaces the true mechanical pressure in accurate chemical equilibrium calculations. It is equal to the pressure of an ideal gas which has the same chemical potential as the real gas.'),
('http://qudt.org/vocab/quantitykind/FundamentalLatticeVector', 'Fundamental Lattice Vector', '"Fundamental Lattice vector" are fundamental translation vectors for the crystal lattice.'),
('http://qudt.org/vocab/quantitykind/FundamentalReciprocalLatticeVector', 'Fundamental Reciprocal Lattice Vector', '"Fundamental Reciprocal Lattice Vector" are fundamental, or primary, translation vectors of the reciprocal lattice.'),
('http://qudt.org/vocab/quantitykind/GFactorOfNucleus', 'g-Factor of Nucleus', 'The "g-Factor of Nucleus" is associated with the spin and magnetic moments of protons, neutrons, and many nuclei.'),
('http://qudt.org/vocab/quantitykind/Gain', 'Gain', 'A general term used to denote an increase in signal power or signal strength in transmission from one point to another. Gain is usually expressed in decibels and is widely used to denote transducer gain. An increase or amplification. In radar there are two general usages of the term: (a) antenna gain, or gain factor, is the ratio of the power transmitted along the beam axis to that of an isotropic radiator transmitting the same total power; (b) receiver gain, or video gain, is the amplification given a signal by the receiver.'),
('http://qudt.org/vocab/quantitykind/GapEnergy', 'Gap Energy', '"Gap Energy" is the difference in energy between the lowest level of conduction band and the highest level of valence band. It is an energy range in a solid where no electron states can exist.'),
('http://qudt.org/vocab/quantitykind/GasLeakRate', 'Gas Leak Rate', 'ratio of the pV value of a gas (product of pressure and volume of a given quantity of gas at the respective temperature) flowing through a pipe cross-section during a time interval and the related interval'),
('http://qudt.org/vocab/quantitykind/GaugePressure', 'Gauge Pressure', 'Gauge Pressure is the pressure of a system relative to the pressure of the surrounding atmosphere. It is the difference between the absolute pressure and the atmospheric pressure. Gauge pressure is positive for pressures above atmospheric pressure and negative for pressures below it. A Quantity in QUDT having a QuantityKind of GaugePressure would typically also assert the value of qudt:isDeltaQuantity to be true, indicating that the value is a difference between two pressures.'),
('http://qudt.org/vocab/quantitykind/GeneFamilyAbundance', 'Gene Family Abundance', 'The abundance of each gene family in the community. Gene families are groups of evolutionarily-related protein-coding sequences that often perform similar functions. Gene family abundance is reported in RPK (reads per kilobase) units to normalize for gene length.'),
('http://qudt.org/vocab/quantitykind/GeneralizedCoordinate', 'Generalized Coordinate', 'Generalized Coordinates refers to the parameters that describe the configuration of the system relative to some reference configuration. These parameters must uniquely define the configuration of the system relative to the reference configuration.'),
('http://qudt.org/vocab/quantitykind/GeneralizedForce', 'Generalized Force', 'Generalized Forces find use in Lagrangian mechanics, where they play a role conjugate to generalized coordinates.'),
('http://qudt.org/vocab/quantitykind/GeneralizedMomentum', 'Generalized Force', 'Generalized Momentum, also known as the canonical or conjugate momentum, extends the concepts of both linear momentum and angular momentum. To distinguish it from generalized momentum, the product of mass and velocity is also referred to as mechanical, kinetic or kinematic momentum.'),
('http://qudt.org/vocab/quantitykind/GeneralizedVelocity', 'Generalized Velocity', 'Generalized Velocities are the time derivatives of the generalized coordinates of the system.'),
('http://qudt.org/vocab/quantitykind/GibbsEnergy', 'Gibbs Energy', 'Gibbs Energy is one of the potentials used to measure energy changes in systems as they evolve from an initial state to a final state. The potential used depends on the constraints of the system, such as constant temperature or pressure. Internal Energy is the internal energy of the system, Enthalpy is the internal energy of the system plus the energy related to pressure-volume work, and Helmholtz and Gibbs free energy are the energies available in a system to do useful work when the temperature and volume or the pressure and temperature are fixed, respectively. The name Gibbs Free Energy is also used.'),
('http://qudt.org/vocab/quantitykind/Gradient', 'Gradient', NULL),
('http://qudt.org/vocab/quantitykind/GrandCanonicalPartitionFunction', 'Grand Canonical Partition Function', 'An "Grand Canonical Partition Function" for a grand canonical ensemble, a system that can exchange both heat and particles with the environment, which has a constant temperature and a chemical potential.'),
('http://qudt.org/vocab/quantitykind/GravitationalAttraction', 'Gravitational Attraction', 'The force of attraction between all masses in the universe; especially the attraction of the earth''s mass for bodies near its surface; the more remote the body the less the gravity; the gravitation between two bodies is proportional to the product of their masses and inversely proportional to the square of the distance between them.'),
('http://qudt.org/vocab/quantitykind/GrossTonnage', 'Gross Tonnage', 'Gross tonnage (GT, G.T. or gt) is a nonlinear measure of a ship''s overall internal volume. Gross tonnage is different from gross register tonnage. Gross tonnage is used to determine things such as a ship''s manning regulations, safety rules, registration fees, and port dues, whereas the older gross register tonnage is a measure of the volume of only certain enclosed spaces.'),
('http://qudt.org/vocab/quantitykind/GroupSpeedOfSound', 'Group Speed of Sound', 'In a dispersive medium sound speed is a function of sound frequency, through the dispersion relation. The spatial and temporal distribution of a propagating disturbance will continually change. The group speed of sound describes the propagation of the disturbance.'),
('http://qudt.org/vocab/quantitykind/GrowingDegreeDay', 'Growing Degree Days (Cereals)', 'The sum of excess temperature over 5.5°C, where the temperature is the mean of the minimum and maximum atmospheric temperature in a day. This measure is appropriate for most cereal crops.'),
('http://qudt.org/vocab/quantitykind/GruneisenParameter', 'Gruneisen Parameter', '"Gruneisen Parameter" named after Eduard Grüneisen, describes the effect that changing the volume of a crystal lattice has on its vibrational properties, and, as a consequence, the effect that changing temperature has on the size or dynamics of the lattice.'),
('http://qudt.org/vocab/quantitykind/GustatoryThreshold', 'Gustatory Threshold', '"Gustatory Threshold" is the lowest concentration of a substance in solution that can be detected by the sense of taste — the threshold of sensitivity of the human mouth to classes of taste in foods, drinks and other substances. It is expressed as the amount-of-substance (or mass) concentration of the tastant at the detection limit.'),
('http://qudt.org/vocab/quantitykind/GyromagneticRatio', 'Gyromagnetic Ratio', 'Gyromagnetic Ratio, also sometimes known as the magnetogyric ratio in other disciplines, of a particle or system is the ratio of its magnetic dipole moment to its angular momentum, and it is often denoted by the symbol, γ. Its SI coherent unit is the radian per second per tesla (rad · s^-1 · T^-1); because the radian is dimensionless this is equal to the coulomb per kilogram (C · kg^-1).'),
('http://qudt.org/vocab/quantitykind/HalfLife', 'Half-life', 'The "Half-Life" is the average duration required for the decay of one half of the atoms or nuclei.'),
('http://qudt.org/vocab/quantitykind/HalfValueThickness', 'Half-Value Thickness', 'The "Half-Value Thickness" is the thickness of the material at which the intensity of radiation entering it is reduced by one half.'),
('http://qudt.org/vocab/quantitykind/HallCoefficient', 'Hall Coefficient', '"Hall Coefficient" is defined as the ratio of the induced electric field to the product of the current density and the applied magnetic field.'),
('http://qudt.org/vocab/quantitykind/HamiltonFunction', 'Hamilton Function', 'The Hamilton function, or Hamiltonian, H of a mechanical system is the Legendre transform of the Lagrange function, H = sum_i p_i q_i-dot - L, expressed in terms of the generalized coordinates q_i and their conjugate momenta p_i. When the constraints and the potential are independent of time it equals the total energy (kinetic plus potential) of the system, and it accordingly has the dimension of energy.'),
('http://qudt.org/vocab/quantitykind/HeadEndPressure', 'Head End Pressure', NULL),
('http://qudt.org/vocab/quantitykind/HeartRate', 'Heart Rate', 'The number of heartbeats per unit of time, usually per minute. The heart rate is based on the number of contractions of the ventricles (the lower chambers of the heart). The heart rate may be too fast (tachycardia) or too slow (bradycardia). The average adult pulse rate at rest is 60–80 per minute, but exercise, injury, illness, and emotion may produce much faster rates.'),
('http://qudt.org/vocab/quantitykind/Heat', 'Heat', '"Heat" is the energy transferred by a thermal process. Heat can be measured in terms of the dynamical units of energy, as the erg, joule, etc., or in terms of the amount of energy required to produce a definite thermal change in some substance, as, for example, the energy required per degree to raise the temperature of a unit mass of water at some temperature ( calorie, Btu).'),
('http://qudt.org/vocab/quantitykind/HeatCapacity', 'Heat Capacity', '"Heat Capacity" (usually denoted by a capital C, often with subscripts), or thermal capacity, is the measurable physical quantity that characterizes the amount of heat required to change a substance''s temperature by a given amount. In the International System of Units (SI), heat capacity is expressed in units of joule(s) (J) per kelvin (K).'),
('http://qudt.org/vocab/quantitykind/HeatCapacityRatio', 'Heat Capacity Ratio', 'The heat capacity ratio, or ratio of specific heats, is the ratio of the heat capacity at constant pressure (C_P) to heat capacity at constant volume (C_V). For an ideal gas, the heat capacity is constant with temperature (θ). Accordingly we can express the enthalpy as H = C_P*θ and the internal energy as U = C_V · θ. Thus, it can also be said that the heat capacity ratio is the ratio between enthalpy and internal energy.'),
('http://qudt.org/vocab/quantitykind/HeatFlowRate', 'Heat Flow Rate', 'The rate of heat flow between two systems is measured in watts (joules per second). The formula for rate of heat flow is Δ Q / Δ t = -K × A × Δ T/x, where Δ Q / Δ t is the rate of heat flow; -K is the thermal conductivity factor; A is the surface area; Δ T is the change in temperature and x is the thickness of the material. Δ T/ x is called the temperature gradient and is always negative because of the heat of flow always goes from more thermal energy to less).'),
('http://qudt.org/vocab/quantitykind/HeatFlowRatePerArea', 'Heat Flow Rate per Unit Area', 'Heat Flux is the heat rate per area. In SI units, heat flux is measured in W/m^2. Heat rate is a scalar quantity, while heat flux is a vectorial quantity. To define the heat flux at a certain point in space, one takes the limiting case where the size of the surface becomes infinitesimally small.'),
('http://qudt.org/vocab/quantitykind/HeatFluxDensity', 'Heat Flux Density', NULL),
('http://qudt.org/vocab/quantitykind/HeatingValue', 'Calorific Value', 'The heating value (or energy value or calorific value) of a substance, usually a fuel or food (see food energy), is the amount of heat released during the combustion of a specified amount of it.'),
('http://qudt.org/vocab/quantitykind/Height', 'Height', '"Height" is the measurement of vertical distance, but has two meanings in common use. It can either indicate how "tall" something is, or how "high up" it is.'),
('http://qudt.org/vocab/quantitykind/HelmholtzEnergy', 'Helmholtz Energy', 'Helmholtz Energy is one of the potentials are used to measure energy changes in systems as they evolve from an initial state to a final state. The potential used depends on the constraints of the system, such as constant temperature or pressure. Internal Energy is the internal energy of the system, Enthalpy is the internal energy of the system plus the energy related to pressure-volume work, and Helmholtz and Gibbs free energy are the energies available in a system to do useful work when the temperature and volume or the pressure and temperature are fixed, respectively. The name Helmholz Free Energy is also used.'),
('http://qudt.org/vocab/quantitykind/HenrysLawVolatilityConstant', 'Henry''s Law Volatility Constant', 'A quantity kind that is a proportionality constant that relates the partial pressure of a gas above a liquid and the concentration of the gas dissolved in the liquid. The numerator contains the gaseous concentration and the denominator contains the liquid concentration.'),
('http://qudt.org/vocab/quantitykind/HoleDensity', 'Hole Density', '"Hole Density" is the number of holes per volume in a valence band.'),
('http://qudt.org/vocab/quantitykind/HorizontalVelocity', 'Horizontal Velocity', 'Component of a projectile''s velocity, which acts parallel to the ground and does not lift the projectile in the air.'),
('http://qudt.org/vocab/quantitykind/HydraulicPermeability', 'Hydraulic Permeability', 'Permeability is a property of porous materials that is an indication of the ability for fluids (gas or liquid) to flow through them. Fluids can more easily flow through a material with high permeability than one with low permeability. The permeability of a medium is related to the porosity, but also to the shapes of the pores in the medium and their level of connectedness.'),
('http://qudt.org/vocab/quantitykind/HyperfineStructureQuantumNumber', 'Hyperfine Structure Quantum Number', 'The "Hyperfine Structure Quantum Number" is a quantum number of an atom describing inclination of the nuclear spin with respect to a quantization axis given by the magnetic field produced by the orbital electrons.'),
('http://qudt.org/vocab/quantitykind/IgnitionIntervalTime', 'Ignition Interval Time', NULL),
('http://qudt.org/vocab/quantitykind/Illuminance', 'Illuminance', 'Illuminance is the total luminous flux incident on a surface, per unit area. It is a measure of the intensity of the incident light, wavelength-weighted by the luminosity function to correlate with human brightness perception.'),
('http://qudt.org/vocab/quantitykind/Impedance', 'Impedance', '"Impedance" is the measure of the opposition that a circuit presents to the passage of a current when a voltage is applied. In quantitative terms, it is the complex ratio of the voltage to the current in an alternating current (AC) circuit. Impedance extends the concept of resistance to AC circuits, and possesses both magnitude and phase, unlike resistance, which has only magnitude. When a circuit is driven with direct current (DC), there is no distinction between impedance and resistance; the latter can be thought of as impedance with zero phase angle.'),
('http://qudt.org/vocab/quantitykind/Impulse', 'Impulse', 'product of force and time'),
('http://qudt.org/vocab/quantitykind/Incidence', 'Incidence', 'In epidemiology, incidence is the rate at which new cases of a given medical condition occur in a population: the number of new occurrences counted per unit time. The same quantity as quantitykind:IncidenceRate, from a different source vocabulary (IEC 61360). For the dimensionless fraction of a population affected within a specified period, see quantitykind:IncidenceProportion.'),
('http://qudt.org/vocab/quantitykind/IncidenceProportion', 'Incidence Proportion', 'Incidence proportion (also known as cumulative incidence) is the number of new cases within a specified time period divided by the size of the population initially at risk. For example, if a population initially contains 1,000 non-diseased persons and 28 develop a condition over two years of observation, the incidence proportion is 28 cases per 1,000 persons per two years, i.e. 2.8% per two years.'),
('http://qudt.org/vocab/quantitykind/IncidenceRate', 'Incidence Rate', 'The incidence rate is a measure of the frequency with which a disease or other incident occurs over a specified time period. It is also known as the incidence density rate or person-time incidence rate, when the denominator is the combined person-time of the population at risk (the sum of the time duration of exposure across all persons exposed)'),
('http://qudt.org/vocab/quantitykind/Inductance', 'Inductance', '"Inductance" is an electromagentic quantity that characterizes a circuit''s resistance to any change of electric current; a change in the electric current through induces an opposing electromotive force (EMF). Quantitatively, inductance is proportional to the magnetic flux per unit of electric current.'),
('http://qudt.org/vocab/quantitykind/InductanceBasedTimeConstant', 'Inductance Based Time Constant', 'The inductance-based time constant, tau = L/R, of an RL circuit is the time taken for the current to reach a fraction 1 - 1/e (about 63%) of its final value after a step change in the applied voltage. It is the ratio of the inductance L to the resistance R and has the dimension of time, expressed in seconds.'),
('http://qudt.org/vocab/quantitykind/InfiniteMultiplicationFactor', 'Infinite Multiplication Factor', 'The "Infinite Multiplication Factor" is the multiplication factor for an infinite medium or for an infinite repeating lattice.'),
('http://qudt.org/vocab/quantitykind/InformationContent', 'Information Content', 'The information content (or self-information) I(x) of an outcome x is a measure of the information gained when x occurs, defined as the logarithm of the reciprocal of its probability: I(x) = log(1/p(x)). The value depends on the base of the logarithm, which fixes the unit — base 2 gives the shannon (Sh), base e the nat, and base 10 the hartley (Hart). It is the per-outcome quantity whose expectation over a distribution is the information entropy.'),
('http://qudt.org/vocab/quantitykind/InformationEntropy', 'Information Entropy', 'Information Entropy is a concept from information theory. It tells how much information there is in an event. In general, the more uncertain or random the event is, the more information it will contain. The concept of information entropy was created by a mathematician. He was named Claude Elwood Shannon. It has applications in many areas, including lossless data compression, statistical inference, cryptography and recently in other disciplines such as biology, physics or machine learning.'),
('http://qudt.org/vocab/quantitykind/InformationFlowRate', 'Information Flow Rate', 'The rate at which information content (Shannon entropy) is conveyed by a source or over a channel: information content per unit time, measured in shannons, nats, or hartleys per second according to the logarithm base. It is an information-theoretic quantity, distinct from quantitykind:DataRate, which counts raw bits transferred per second regardless of their information content; by the source coding theorem the information flow rate of a channel is at most its data rate.'),
('http://qudt.org/vocab/quantitykind/InitialExpansionRatio', 'Initial Expansion Ratio', NULL),
('http://qudt.org/vocab/quantitykind/InitialVehicleMass', 'Initial Vehicle Mass', NULL),
('http://qudt.org/vocab/quantitykind/InitialVelocity', 'Initial Velocity', 'The velocity of a moving body at starting; especially, the velocity of a projectile as it leaves the mouth of a firearm from which it is discharged.'),
('http://qudt.org/vocab/quantitykind/InstantaneousPower', 'Instantaneous Power', 'For a two-terminal element or a two-terminal circuit with terminals A and B, Instantaneous Power is the product of the voltage u_AB between the terminals and the electric current i in the element or circuit: p = u_AB · i Where u_AB is the line integral of the electric field strength from A to B, and where the electric current in the element or circuit is taken positive if its direction is from A to B and negative in the opposite case. For an n-terminal circuit, it is the sum of the instantaneous powers relative to the n - 1 pairs of terminals when one of the terminals is chosen as a common terminal for the pairs. For a polyphase element, it is the sum of the instantaneous powers in all phase elements of a polyphase element. For a polyphase line consisting of m line conductors and one neutral conductor, it is the sum of the m instantaneous powers expressed for each line conductor by the product of the polyphase line-to-neutral voltage and the corresponding line current.'),
('http://qudt.org/vocab/quantitykind/InternalConversionFactor', 'Internal Conversion Factor', 'The "InternalConversionFactor" describes the rate of internal conversion. It is the ratio of the number of internal conversion electrons to the number of gamma quanta emitted by the radioactive atom in a given transition.'),
('http://qudt.org/vocab/quantitykind/InternalEnergy', 'Internal Energy', '"Internal Energy" is simply its energy. "internal" refers to the fact that some energy contributions are not considered. For instance, when the total system is in uniform motion, it has kinetic energy. This overall kinetic energy is never seen as part of the internal energy; one could call it external energy. Or, if the system is at constant non-zero height above the surface the Earth, it has constant potential energy in the gravitational field of the Earth. Gravitational energy is only taken into account when it plays a role in the phenomenon of interest, for instance in a colloidal suspension, where the gravitation influences the up- downward motion of the small particles comprising the colloid. In all other cases, gravitational energy is assumed not to contribute to the internal energy; one may call it again external energy.'),
('http://qudt.org/vocab/quantitykind/IntrinsicCarrierDensity', 'Intrinsic Carrier Density', '"Intrinsic Carrier Density" is proportional to electron and hole densities.'),
('http://qudt.org/vocab/quantitykind/InverseAmountOfSubstance', 'Inverse Amount of Substance', NULL),
('http://qudt.org/vocab/quantitykind/InverseArea', 'Inverse Area', 'A quantity with dimension of inverse area (L⁻²), used for generic inverse-area units such as microscopic cross-sections and attenuation coefficients that do not imply a count of discrete particles.'),
('http://qudt.org/vocab/quantitykind/InverseEnergy', 'Inverse Energy', NULL),
('http://qudt.org/vocab/quantitykind/InverseLength', 'Inverse Length', 'Reciprocal length or inverse length is a measurement used in several branches of science and mathematics. As the reciprocal of length, common units used for this measurement include the reciprocal metre or inverse metre (m^-1), the reciprocal centimetre or inverse centimetre (cm^-1), and, in optics, the dioptre.'),
('http://qudt.org/vocab/quantitykind/InverseLengthTemperature', 'Inverse Length Temperature', NULL),
('http://qudt.org/vocab/quantitykind/InverseMagneticFlux', 'Inverse Magnetic Flux', NULL),
('http://qudt.org/vocab/quantitykind/InverseMass', 'Reciprocal Mass', NULL),
('http://qudt.org/vocab/quantitykind/InversePermittivity', 'Inverse Permittivity', NULL),
('http://qudt.org/vocab/quantitykind/InversePressure', 'Inverse Pressure', NULL),
('http://qudt.org/vocab/quantitykind/InverseSquareEnergy', 'Inverse Square Energy', NULL),
('http://qudt.org/vocab/quantitykind/InverseSquareMass', 'Inverse Square Mass', NULL),
('http://qudt.org/vocab/quantitykind/InverseSquareTime', 'Inverse Square Time', NULL),
('http://qudt.org/vocab/quantitykind/InverseTemperature', 'Inverse Temperature', NULL),
('http://qudt.org/vocab/quantitykind/InverseTime', 'Inverse Time', NULL),
('http://qudt.org/vocab/quantitykind/InverseTimeTemperature', 'Inverse Time Temperature', NULL),
('http://qudt.org/vocab/quantitykind/InverseVolume', 'Inverse Volume', NULL),
('http://qudt.org/vocab/quantitykind/IonConcentration', 'Ion Concentration', '"Ion Concentration" is the number of moles of ions per volume. This is the same physical concept as IonDensity, but with the dimensionality of moles per volume rather than number per volume.'),
('http://qudt.org/vocab/quantitykind/IonCurrent', 'Ion Current', 'An ion current is the influx and/or efflux of ions through an ion channel.'),
('http://qudt.org/vocab/quantitykind/IonDensity', 'Ion Density', '"Ion Density" is the number of ions per unit volume.'),
('http://qudt.org/vocab/quantitykind/IonTransportNumber', 'Ion Transport Number', 'The "Ion Transport Number" is a quantity which indicates the different contribution of ions to the electric current in electrolytes due to different electrical mobility.'),
('http://qudt.org/vocab/quantitykind/IonicCharge', 'Ionic Charge', 'The total charge of an ion. The charge of an electron; the charge of any ion is equal to this electron charge in magnitude, or is an integral multiple of it.'),
('http://qudt.org/vocab/quantitykind/IonicStrength', 'Ionic Strength', 'The "Ionic Strength" of a solution is a measure of the concentration of ions in that solution.'),
('http://qudt.org/vocab/quantitykind/IonizationEnergy', 'Ionization Energy', '"Ionization Energy" is the energy difference between an electron at rest at infinity and an electron at a certain energy level. The amount of energy required to remove an electron from that atom or molecule in the gas phase.'),
('http://qudt.org/vocab/quantitykind/Irradiance', 'Irradiance', 'Irradiance and Radiant Emittance are radiometry terms for the power per unit area of electromagnetic radiation at a surface. "Irradiance" is used when the electromagnetic radiation is incident on the surface. "Radiant emmitance" (or "radiant exitance") is used when the radiation is emerging from the surface.'),
('http://qudt.org/vocab/quantitykind/IsentropicCompressibility', 'Isentropic Compressibility', 'Isentropic compressibility is the extent to which a material reduces its volume when it is subjected to compressive stresses at a constant value of entropy.'),
('http://qudt.org/vocab/quantitykind/IsentropicExponent', 'Isentropic Exponent', 'Isentropic Exponent is a variant of Specific Heat Ratio Capacities. For an ideal gas Isentropic Exponent, ϰ. is equal to γ, the ratio of its specific heat capacities c_p and c_v under steady pressure and volume.'),
('http://qudt.org/vocab/quantitykind/IsothermalCompressibility', 'Isothermal Compressibility', 'The isothermal compressibility defines the rate of change of system volume with pressure.'),
('http://qudt.org/vocab/quantitykind/IsothermalMoistureCapacity', 'Isothermal Moisture Capacity', '"Isothermal Moisture Capacity" is the capacity of a material to absorb moisture in the Effective Moisture Penetration Depth (EMPD) model.'),
('http://qudt.org/vocab/quantitykind/Kerma', 'Kerma', '"Kerma" is the sum of the initial kinetic energies of all the charged particles liberated by uncharged ionizing radiation (i.e., indirectly ionizing radiation such as photons and neutrons) in a sample of matter, divided by the mass of the sample.'),
('http://qudt.org/vocab/quantitykind/KermaRate', 'Kerma Rate', '"Kerma Rate" is the kerma per unit time.'),
('http://qudt.org/vocab/quantitykind/KinematicViscosity', 'Kinematic Viscosity', 'The ratio of the viscosity of a liquid to its density. Viscosity is a measure of the resistance of a fluid which is being deformed by either shear stress or tensile stress. In many situations, we are concerned with the ratio of the inertial force to the viscous force (that is the Reynolds number), the former characterized by the fluid density ρ. This ratio is characterized by the kinematic viscosity (Greek letter ν), defined as follows: ν = μ / ρ. The SI unit of ν is m^2/s. The SI unit of ν is kg/m^1.'),
('http://qudt.org/vocab/quantitykind/KineticEnergy', 'Kinetic Energy', 'The kinetic energy of an object is the energy which it possesses due to its motion. It is defined as the work needed to accelerate a body of a given mass from rest to its stated velocity.'),
('http://qudt.org/vocab/quantitykind/LagrangeFunction', 'Lagrange Function', 'The Lagrange Function is a function that summarizes the dynamics of the system.'),
('http://qudt.org/vocab/quantitykind/LandauGinzburgNumber', 'Landau-Ginzburg Number', '"Landau-Ginzburg Number", also known as the Ginzburg-Landau parameter, describes the relationship between London penetration depth and coherence length.'),
('http://qudt.org/vocab/quantitykind/LandeGFactor', 'Lande g-Factor', 'The "Lande g-Factor" is a particular example of a g-factor, namely for an electron with both spin and orbital angular momenta. It is named after Alfred Landé, who first described it in 1921.'),
('http://qudt.org/vocab/quantitykind/LarmorAngularFrequency', 'Larmor Angular Frequency', 'The "Larmor Frequency" describes angular momentum vector precession about the external field axis with an angular frequency.'),
('http://qudt.org/vocab/quantitykind/LatticePlaneSpacing', 'Lattice Plane Spacing', '"Lattice Plane Spacing" is the distance between successive lattice planes.'),
('http://qudt.org/vocab/quantitykind/LatticeVector', 'Lattice Vector', '"Lattice Vector" is a translation vector that maps the crystal lattice on itself.'),
('http://qudt.org/vocab/quantitykind/LeakageFactor', 'Leakage Factor', '"Leakage Factor" is the ratio of the total magnetic flux to the useful magnetic flux of a magnetic circuit.'),
('http://qudt.org/vocab/quantitykind/Length', 'Length', 'In geometric measurements, length most commonly refers to the longest dimension of an object. In some contexts, the term "length" is reserved for a certain dimension of an object along which the length is measured.'),
('http://qudt.org/vocab/quantitykind/LengthByForce', 'Length Force', NULL),
('http://qudt.org/vocab/quantitykind/LengthEnergy', 'Length Energy', NULL),
('http://qudt.org/vocab/quantitykind/LengthMass', 'Length Mass', NULL),
('http://qudt.org/vocab/quantitykind/LengthMolarEnergy', 'Length Molar Energy', NULL),
('http://qudt.org/vocab/quantitykind/LengthPerElectricCurrent', 'Length per Electric Current', 'Length divided by electric current. Its SI coherent derived unit is the metre per ampere (m/A).'),
('http://qudt.org/vocab/quantitykind/LengthRatio', 'Length Ratio', NULL),
('http://qudt.org/vocab/quantitykind/LengthTemperature', 'Length Temperature', NULL),
('http://qudt.org/vocab/quantitykind/LengthTemperatureTime', 'Length Temperature Time', NULL),
('http://qudt.org/vocab/quantitykind/Lethargy', 'Lethargy', 'The "Lethargy" is a dimensionless logarithm of the ratio of the energy of source neutrons to the energy of neutrons after a collision.'),
('http://qudt.org/vocab/quantitykind/LevelWidth', 'Level Width', 'The "Level Width" is the uncertainty in the energy of a quantum-mechanical system having discrete energy levels in a state that is not strictly stationary. The system may be an atom, a molecule, or an atomic nucleus.'),
('http://qudt.org/vocab/quantitykind/LiftCoefficient', 'Lift Coefficient', 'The lift coefficient is a dimensionless coefficient that relates the lift generated by a lifting body, the dynamic pressure of the fluid flow around the body, and a reference area associated with the body.'),
('http://qudt.org/vocab/quantitykind/LiftForce', 'Lift Force', 'The lift force, lifting force or simply lift is the sum of all the forces on a body that force it to move perpendicular to the direction of flow.'),
('http://qudt.org/vocab/quantitykind/LinearAbsorptionCoefficient', 'Linear Absorption Coefficient', 'The Linear Absorption Coefficient is a quantity that characterizes how easily a material or medium can be penetrated by a beam of light, sound, particles, or other energy or matter.'),
('http://qudt.org/vocab/quantitykind/LinearAcceleration', 'Linear Acceleration', NULL),
('http://qudt.org/vocab/quantitykind/LinearAttenuationCoefficient', 'Linear Attenuation Coefficient', '"Linear Attenuation Coefficient", also called the attenuation coefficient, narrow beam attenuation coefficient, or absorption coefficient, is a quantity that characterizes how easily a material or medium can be penetrated by a beam of light, sound, particles, or other energy or matter.'),
('http://qudt.org/vocab/quantitykind/LinearBitDensity', 'Lineic Bit Density', NULL),
('http://qudt.org/vocab/quantitykind/LinearCompressibility', 'Linear Compressibility', 'Linear Compressibility is a measure of the relative length change of a solid as a response to a normal force change.'),
('http://qudt.org/vocab/quantitykind/LinearDensity', 'Linear Density', 'The Linear density, linear mass density or linear mass is a measure of mass per unit of length, and it is a characteristic of strings or other one-dimensional objects.'),
('http://qudt.org/vocab/quantitykind/LinearElectricCharge', 'Lineic Electric Charge', NULL),
('http://qudt.org/vocab/quantitykind/LinearElectricChargeDensity', 'Electric Charge Linear Density', 'In electromagnetism, charge density is a measure of electric charge per unit volume of space, in one, two or three dimensions. More specifically: the linear, surface, or volume charge density is the amount of electric charge per unit length, surface area, or volume, respectively.'),
('http://qudt.org/vocab/quantitykind/LinearElectricCurrent', 'Linear Electric Current', '"Linear Electric Current" is the electric current per unit length.'),
('http://qudt.org/vocab/quantitykind/LinearElectricCurrentDensity', 'Linear Electric Current Density', '"Linear Electric Current Density" is the electric current per unit length. Electric current, I, through a curve C is defined as I = ∫_C J _s × e_n, where e_n is a unit vector perpendicular to the surface and line vector element, and dr is the differential of position vector r.'),
('http://qudt.org/vocab/quantitykind/LinearEnergyTransfer', 'Linear Energy Transfer', '"Linear Energy Transfer" (LET) is the linear density of energy lost by a charged ionizing particle travelling through matter.Typically, this measure is used to quantify the effects of ionizing radiation on biological specimens or electronic devices.'),
('http://qudt.org/vocab/quantitykind/LinearExpansionCoefficient', 'Linear Expansion Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/LinearForce', 'Linear Force', 'Another name for Force Per Length, used by the Industry Foundation Classes (IFC) standard.'),
('http://qudt.org/vocab/quantitykind/LinearIonization', 'Linear Ionization', '"Linear Ionization" is a description of how the ionization of an atom or molecule takes place. For example, an ion with a +2 charge can be created only from an ion with a +1 charge or a +3 charge. That is, the numerical charge of an atom or molecule must change sequentially, always moving from one number to an adjacent, or sequential, number. Using sequential ionization definition.'),
('http://qudt.org/vocab/quantitykind/LinearMass', 'Lineic Mass', NULL),
('http://qudt.org/vocab/quantitykind/LinearMomentum', 'Linear Momentum', 'Linear momentum is the quantity obtained by multiplying the mass of a body by its linear velocity. The momentum of a continuous medium is given by the integral of the velocity over the mass of the medium or by the product of the total mass of the medium and the velocity of the center of gravity of the medium.The SI unit for linear momentum is meter-kilogram per second (m-kg/s).'),
('http://qudt.org/vocab/quantitykind/LinearNumberDensity', 'Linear Number Density', 'The number of countable entities (particles, objects, events) per unit length.'),
('http://qudt.org/vocab/quantitykind/LinearPower', 'Lineic Power', NULL),
('http://qudt.org/vocab/quantitykind/LinearResistance', 'Lineic Resistance', NULL),
('http://qudt.org/vocab/quantitykind/LinearStiffness', 'Linear Force', 'Stiffness is the extent to which an object resists deformation in response to an applied force. Linear Stiffness is the term used in the Industry Foundation Classes (IFC) standard.'),
('http://qudt.org/vocab/quantitykind/LinearStrain', 'Linear Strain', 'A strain is a normalized measure of deformation representing the displacement between particles in the body relative to a reference length.'),
('http://qudt.org/vocab/quantitykind/LinearThermalExpansion', 'Linear Thermal Expansion', 'When the temperature of a substance changes, the energy that is stored in the intermolecular bonds between atoms changes. When the stored energy increases, so does the length of the molecular bonds. As a result, solids typically expand in response to heating and contract on cooling; this dimensional response to temperature change is expressed by its coefficient of thermal expansion. Different coefficients of thermal expansion can be defined for a substance depending on whether the expansion is measured by: linear thermal expansion, area thermal expansion, or volumetric thermal expansion.'),
('http://qudt.org/vocab/quantitykind/LinearTorque', 'Lineic Torque', NULL),
('http://qudt.org/vocab/quantitykind/LinearVelocity', 'Linear Velocity', 'Linear Velocity, as the name implies deals with speed in a straight line, the units are often km/hr or m/s or mph (miles per hour). Linear Velocity (v) = change in distance/change in time, where v = Δ d/Δ t'),
('http://qudt.org/vocab/quantitykind/LinearVoltageCoefficient', 'Linear Voltage Coefficient', 'ratio identifying the relationship between induced voltage and velocity'),
('http://qudt.org/vocab/quantitykind/LineicCharge', 'Lineic Charge', 'electric charge divided by related length'),
('http://qudt.org/vocab/quantitykind/LineicDataVolume', 'Lineic Data Volume', 'number of data, usually dependent on the respective information complexity or its coding procedure, divided by the related length'),
('http://qudt.org/vocab/quantitykind/LineicMass', 'Lineic Mass', 'ratio between mass divided by the related length'),
('http://qudt.org/vocab/quantitykind/LineicPower', 'Lineic Power', 'power divided by the associated length'),
('http://qudt.org/vocab/quantitykind/LineicQuantity', 'Lineic Quantity', NULL),
('http://qudt.org/vocab/quantitykind/LineicResistance', 'Lineic Resistance', 'ratio of resistance divided by length'),
('http://qudt.org/vocab/quantitykind/LineicResolution', 'Lineic Resolution', 'graphic resolution capacity of output devices such as printers or of data acquisition such as scanners, as a number of pixels per length'),
('http://qudt.org/vocab/quantitykind/LineicTorque', 'Lineic Torque', 'torque divided by the appropriate length'),
('http://qudt.org/vocab/quantitykind/LinkedFlux', 'Linked Flux', '"Linked Flux" is defined as the path integral of the magnetic vector potential. This is the line integral of a magnetic vector potential A along a curve C. The line vector element dr is the differential of position vector r.'),
('http://qudt.org/vocab/quantitykind/LiquidLevel', 'Liquid Level', 'Liquid level refers to the measurement of the height of a liquid within a container.'),
('http://qudt.org/vocab/quantitykind/LiquidVolume', 'Liquid Volume', 'Liquid volume is the volume of a given amount of liquid, that is, the amount of space a liquid takes up. There are a number of different units used to measure liquid volume, but most of them fall under either the metric system of measurement or the Imperial system of measurement.'),
('http://qudt.org/vocab/quantitykind/Log10FrequencyInterval', 'Logarithmic Frequency Interval to Base 10', 'The common (base-10) logarithm of the ratio of two frequencies, whereby the frequency forming the numerator is greater than the frequency forming the denominator. Its corresponding unit is the decade.'),
('http://qudt.org/vocab/quantitykind/Log10Ratio', 'Logarithmic Ratio to Base 10', 'The common (base-10) logarithm of the ratio between the value of a defined quantity and the value of a reference quantity of the same type.'),
('http://qudt.org/vocab/quantitykind/Log10RatioPerLength', 'Logarithmic Ratio to Base 10 per Length', 'The common (base-10) logarithm of the ratio between the value of a quantity and the value of a reference quantity of the same type, divided by the length over which the ratio arises. Typically used for attenuation or gain along a cable or transmission path, in bels or decibels per unit length.'),
('http://qudt.org/vocab/quantitykind/Log2FrequencyInterval', 'Logarithmic Frequency Interval to Base 2', NULL),
('http://qudt.org/vocab/quantitykind/LogERatio', 'Logarithmic Ratio to Base e', 'The natural (base-e) logarithm of the ratio between the value of a given quantity and the value of a reference quantity of the same type (base of logarithm: e = 2.718...).'),
('http://qudt.org/vocab/quantitykind/LogOctanolAirPartitionCoefficient', 'Octanol Air Partition Coefficient', 'A dimensionless ratio that is the logarithm of the ratio of a compound''s concentration within a two phase mixture of liquid octanol and gaseous air at equilibrium. More simply, it is a comparison of the solubilities of the compound solute in these two immiscible substances.'),
('http://qudt.org/vocab/quantitykind/LogOctanolWaterPartitionCoefficient', 'Logarithm of Octanol Water Partition Coefficient', 'A dimensionless ratio that is the logarithm of the ratio of a compound''s concentration within a two phase mixture of octanol and water at equilibrium. More simply, it is a comparison of the solubilities of the compound solute in these two immiscible liquids. This property is used to measure the lipophilicity and the hydrophilicity of a substance.'),
('http://qudt.org/vocab/quantitykind/LogarithmicFrequencyInterval', 'Logarithmic Frequency Interval', 'The binary (base-2) logarithm of the ratio of two frequencies, whereby the frequency forming the numerator is greater than the frequency forming the denominator. Its corresponding unit is the octave.'),
('http://qudt.org/vocab/quantitykind/LondonPenetrationDepth', 'London Penetration Depth', '"London Penetration Depth" characterizes the distance to which a magnetic field penetrates into a superconductor and becomes equal to 1/e times that of the magnetic field at the surface of the superconductor.'),
('http://qudt.org/vocab/quantitykind/LongRangeOrderParameter', 'Long-Range Order Parameter', '"Long-Range Order Parameter" is the fraction of atoms in an Ising ferromagnet having magnetic moments in one direction, minus the fraction having magnetic moments in the opposite direction.'),
('http://qudt.org/vocab/quantitykind/LorenzCoefficient', 'Lorenz Coefficient', '"Lorenz Coefficient" is part mof the Lorenz curve.'),
('http://qudt.org/vocab/quantitykind/LossAngle', 'Loss Angle', NULL),
('http://qudt.org/vocab/quantitykind/LossFactor', 'Loss Factor', 'Loss Factor is the inverse of Quality Factor and is the ratio of the resistance and modulus of reactance.'),
('http://qudt.org/vocab/quantitykind/Loudness', 'Loudness', 'measure of the subjective hearing sensation on a scale extending from soft to loud; a progressive mono-frequency (single-frequency) wave of frequency 1 kHz and sound pressure level 40 dB, directed head-on to hearers is assigned the loudness 1 sone, and a tone which is identified by the listeners as being n-times as loud as that identified by 1 sone is assigned the loudness n sone'),
('http://qudt.org/vocab/quantitykind/LoudnessLevel', 'Loudness Level', 'value specified in phon as a measure of the level of the subjective perception of a sound which corresponds to the sound pressure level of a reference sound specified in dB which comprises a wave coming from the front with a frequency of 1000 Hz and assessed to be just as loud as the noise'),
('http://qudt.org/vocab/quantitykind/LowerCriticalMagneticFluxDensity', 'Lower Critical Magnetic Flux Density', '"Lower Critical Magnetic Flux Density" for type II superconductors, is the threshold magnetic flux density for magnetic flux entering the superconductor.'),
('http://qudt.org/vocab/quantitykind/Luminance', 'Luminance', 'Luminance is a photometric measure of the luminous intensity per unit area of light travelling in a given direction. It describes the amount of light that passes through or is emitted from a particular area, and falls within a given solid angle.'),
('http://qudt.org/vocab/quantitykind/LuminousEfficacy', 'Luminous Efficacy', 'Luminous Efficacy is the ratio of luminous flux (in lumens) to power (usually measured in watts). Depending on context, the power can be either the radiant flux of the source''s output, or it can be the total electric power consumed by the source.'),
('http://qudt.org/vocab/quantitykind/LuminousEmittance', 'Luminous Emmitance', '"Luminous Emittance" is the luminous flux per unit area emitted from a surface.'),
('http://qudt.org/vocab/quantitykind/LuminousEnergy', 'Luminous Energy', 'Luminous Energy is the perceived energy of light. This is sometimes also called the quantity of light.'),
('http://qudt.org/vocab/quantitykind/LuminousExitance', 'Luminous Exitance', 'Luminous Exitance is the ratio of the luminous flux dΦ, leaving an element of the surface containing the point, by the area dA of that element.'),
('http://qudt.org/vocab/quantitykind/LuminousExposure', 'Luminous Exposure', 'Luminous Exposure is the time-integrated illuminance.'),
('http://qudt.org/vocab/quantitykind/LuminousFlux', 'Luminous Flux', 'Luminous Flux or Luminous Power is the measure of the perceived power of light. It differs from radiant flux, the measure of the total power of light emitted, in that luminous flux is adjusted to reflect the varying sensitivity of the human eye to different wavelengths of light.'),
('http://qudt.org/vocab/quantitykind/LuminousFluxPerArea', 'Luminous Flux per Area', 'In photometry, illuminance is the total luminous flux incident on a surface, per unit area. It is a measure of how much the incident light illuminates the surface, wavelength-weighted by the luminosity function to correlate with human brightness perception. Similarly, luminous emittance is the luminous flux per unit area emitted from a surface. In SI derived units these are measured in lux (lx) or lumens per square metre (cd · m^-2). In the CGS system, the unit of illuminance is the phot, which is equal to 10,000 lux. The foot-candle is a non-metric unit of illuminance that is used in photography.'),
('http://qudt.org/vocab/quantitykind/LuminousFluxRatio', 'Luminous Flux Ratio', 'Luminous Flux Ratio (or Relative Luminous Flux or Relative Luminous Power) is the measure of the perceived power of light. It differs from radiant flux, the measure of the total power of light emitted, in that luminous flux is adjusted to reflect the varying sensitivity of the human eye to different wavelengths of light. It is expressed as a percentage or fraction of full power.'),
('http://qudt.org/vocab/quantitykind/LuminousIntensity', 'Luminous Intensity', 'Luminous Intensity is a measure of the wavelength-weighted power emitted by a light source in a particular direction per unit solid angle. The weighting is determined by the luminosity function, a standardized model of the sensitivity of the human eye to different wavelengths.'),
('http://qudt.org/vocab/quantitykind/LuminousIntensityDistribution', 'Ion Concentration', '"Luminous Intensity Distribution" is a measure of the luminous intensity of a light source that changes according to the direction of the ray. It is normally based on some standardized distribution light distribution curves. Usually measured in Candela/Lumen (cd/lm) or (cd/klm).'),
('http://qudt.org/vocab/quantitykind/MachNumber', 'Mach Number', '"Mach Number" is a dimensionless quantity representing the speed of an object moving through air or other fluid divided by the local speed of sound. It is commonly used to represent the speed of an object when it is traveling close to or above the speed of sound. The Mach number is commonly used both with objects traveling at high speed in a fluid, and with high-speed fluid flows inside channels such as nozzles, diffusers or wind tunnels. As it is defined as a ratio of two speeds, it is a dimensionless number.'),
('http://qudt.org/vocab/quantitykind/MacroscopicCrossSection', 'Macroscopic Cross-section', '"Macroscopic Cross-section" is the sum of the cross-sections for a reaction or process of a specified type over all atoms or other entities in a given 3D domain, divided by the volume of that domain.'),
('http://qudt.org/vocab/quantitykind/MacroscopicTotalCrossSection', 'Macroscopic Total Cross-section', '"Macroscopic Total Cross-section" is the total cross-sections for all atoms or other entities in a given 3D domain, divided by the volume of that domain.'),
('http://qudt.org/vocab/quantitykind/MadelungConstant', 'Madelung Constant', '"Madelung Constant" is used in determining the electrostatic potential of a single ion in a crystal by approximating the ions by point charges. It is named after Erwin Madelung, a German physicist.'),
('http://qudt.org/vocab/quantitykind/MagneticAreaMoment', 'Magnetic Area Moment', '"Magnetic Area Moment", for a magnetic dipole, is a vector quantity equal to the product of the current, the loop area, and the unit vector normal to the loop plane, the direction of which corresponds to the loop orientation. "Magnetic Area Moment" is also referred to as "Magnetic Moment".'),
('http://qudt.org/vocab/quantitykind/MagneticDipoleMoment', 'Magnetic Dipole Moment', '"Magnetic Dipole Moment" is the magnetic moment of a system is a measure of the magnitude and the direction of its magnetism. Magnetic moment usually refers to its Magnetic Dipole Moment, and quantifies the contribution of the system''s internal magnetism to the external dipolar magnetic field produced by the system (that is, the component of the external magnetic field that is inversely proportional to the cube of the distance to the observer). The Magnetic Dipole Moment is a vector-valued quantity. For a particle or nucleus, vector quantity causing an increment Δ W = -μ · B to its energy W in an external magnetic field with magnetic flux density B.'),
('http://qudt.org/vocab/quantitykind/MagneticDipoleMomentOfAMolecule', 'Magnetic Dipole Moment of a Molecule', 'Em = -m•B, where Em is the interaction energy of the molecule with the magnetic dipole moment m and a magnetic field with the magnetic induced flux density B'),
('http://qudt.org/vocab/quantitykind/MagneticField', 'Magnetic Field', 'The Magnetic Field, denoted B, is a fundamental field in electrodynamics which characterizes the magnetic force exerted by electric currents. It is closely related to the auxillary magnetic field H (see quantitykind:AuxillaryMagneticField).'),
('http://qudt.org/vocab/quantitykind/MagneticFieldStrength', 'Magnetic Field Strength', 'Magnetic Field Strength is a vector quantity obtained at a given point by subtracting the magnetization M from the magnetic flux density B divided by the magnetic constant μ_0. The magnetic field strength is related to the total current density J_tot via: rot H = J_tot.'),
('http://qudt.org/vocab/quantitykind/MagneticFlux', 'Magnetic Flux', '"Magnetic Flux" is the product of the average magnetic field times the perpendicular area that it penetrates.'),
('http://qudt.org/vocab/quantitykind/MagneticFluxDensity', 'Magnetic Flux Density', '"Magnetic Flux Density" is a vector quantity and is the magnetic flux per unit area of a magnetic field at right angles to the magnetic force. It can be defined in terms of the effects the field has, for example by B = F/q v sin θ, where F is the force a moving charge q would experience if it was travelling at a velocity v in a direction making an angle θ with that of the field. The magnetic field strength is also a vector quantity and is related to B by: H = B/μ, where μ is the permeability of the medium.'),
('http://qudt.org/vocab/quantitykind/MagneticFluxPerLength', 'Magnetic Flux per Length', '"Magnetic Flux per Length" is a quantity in the SI and C.G.S. Systems of Quantities.'),
('http://qudt.org/vocab/quantitykind/MagneticMoment', 'Magnetic Moment', '"Magnetic Moment", for a magnetic dipole, is a vector quantity equal to the product of the current, the loop area, and the unit vector normal to the loop plane, the direction of which corresponds to the loop orientation. "Magnetic Moment" is also referred to as "Magnetic Area Moment", and is not to be confused with Magnetic Dipole Moment.'),
('http://qudt.org/vocab/quantitykind/MagneticPolarization', 'Magnetic Polarization', 'Magnetic Polarization is a vector quantity equal to the product of the magnetization M and the magnetic constant μ_0.'),
('http://qudt.org/vocab/quantitykind/MagneticQuantumNumber', 'Magnetic Quantum Number', 'The "Magnetic Quantum Number" describes the specific orbital (or "cloud") within that subshell, and yields the projection of the orbital angular momentum along a specified axis.'),
('http://qudt.org/vocab/quantitykind/MagneticReluctivity', 'Magnetic Reluctivity', 'Length Per Unit Magnetic Flux is the the resistance of a material to the establishment of a magnetic field in it. It is the reciprocal of Magnetic Permeability, the inverse of the measure of the ability of a material to support the formation of a magnetic field within itself.'),
('http://qudt.org/vocab/quantitykind/MagneticSusceptability', 'Magnetic Susceptability', '"Magnetic Susceptability" is a scalar or tensor quantity the product of which by the magnetic constant μ_0 and by the magnetic field strength H is equal to the magnetic polarization J. The definition given applies to an isotropic medium. For an anisotropic medium permeability is a second order tensor.'),
('http://qudt.org/vocab/quantitykind/MagneticTension', 'Magnetic Tension', 'Magnetic Tension is a scalar quantity equal to the line integral of the magnetic field strength H along a specified path linking two points a and b.'),
('http://qudt.org/vocab/quantitykind/MagneticVectorPotential', 'Magnetic Vector Potential', '"Magnetic Vector Potential" is the vector potential of the magnetic flux density. The magnetic vector potential is not unique since any irrotational vector field quantity can be added to a given magnetic vector potential without changing its rotation. Under static conditions the magnetic vector potential is often chosen so that its divergence is zero.'),
('http://qudt.org/vocab/quantitykind/Magnetization', 'Magnetization', '"Magnetization" is defined as the ratio of magnetic moment per unit volume. It is a vector-valued quantity.'),
('http://qudt.org/vocab/quantitykind/MagnetizationField', 'Magnetization Field', 'The Magnetization Field is defined as the ratio of magnetic moment per unit volume. It is a vector-valued quantity.'),
('http://qudt.org/vocab/quantitykind/MagnetomotiveForce', 'Magnetomotive Force', 'Magnetomotive Force, also referred to as (mmf), is the ability of an electric circuit to produce magnetic flux. Just as the ability of a battery to produce electric current is called its electromotive force or emf, mmf is taken as the work required to move a unit magnet pole from any point through any path which links the electric circuit back the same point in the presence of the magnetic force produced by the electric current in the circuit. Magnetomotive Force is the scalar line integral of the magnetic field strength along a closed path.'),
('http://qudt.org/vocab/quantitykind/Mass', 'Mass', 'In physics, mass, more specifically inertial mass, can be defined as a quantitative measure of an object''s resistance to acceleration. The SI unit of mass is the kilogram (kg)'),
('http://qudt.org/vocab/quantitykind/MassAbsorptionCoefficient', 'Mass Absorption Coefficient', 'The mass absorption coefficient is the linear absorption coefficient divided by the density of the absorber.'),
('http://qudt.org/vocab/quantitykind/MassAmountOfSubstanceTemperature', 'Mass Amount of Substance Temperature', NULL),
('http://qudt.org/vocab/quantitykind/MassAttenuationCoefficient', 'Mass Attenuation Coefficient', '"Mass Attenuation Coefficient" is a measurement of how strongly a chemical species or substance absorbs or scatters light at a given wavelength, per unit mass.'),
('http://qudt.org/vocab/quantitykind/MassBasedBloodGlucoseLevel', 'Blood Glucose Level by Mass', 'Blood sugar level, blood sugar concentration, or blood glucose level is the amount of glucose present in the blood of humans and animals. Glucose is a simple sugar and approximately 4 grams of glucose are present in the blood of humans at all times. Stored in skeletal muscle and liver cells in the form of glycogen, the body tightly regulates blood glucose levels as a part of metabolic homeostasis. During fasting blood glucose is maintained at a constant level at the expense of the glycogen stores in the liver and skeletal muscle. There are two main methods of describing concentrations: by weight, and by molecular count. Weights are in grams and molecular counts in moles. A mole is 6.022× 10^23 molecules. In both cases, the unit is usually modified by milli- or micro- or other prefix, and is always per some volume, often a litre. Conversion factors depend on the molecular weight of the substance in question. mmol/L is millimoles/liter, and is the world standard unit for measuring glucose in blood. Specifically, it is the designated SI (Systeme International) unit. Some countries use mg/dl. A mole is about 6× 10^23 molecules. mg/dL (milligrams/deciliter) is the traditional unit for measuring bG (blood glucose). There is a trend toward using mmol/L however mg/dL is much in practice. Some use is made of mmol/L as the primary unit with mg/dL quoted in parentheses. This acknowledges the large base of health care providers, researchers and patients who are already familiar with mg/dL.'),
('http://qudt.org/vocab/quantitykind/MassConcentration', 'Mass Concentration', 'The "Mass Concentration" of substance B is defined as the mass of a constituent divided by the volume of the mixture .'),
('http://qudt.org/vocab/quantitykind/MassConcentrationOfWater', 'Mass Concentration of Water', 'Mass Concentration of Water is one of a number of Concentration quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/MassConcentrationOfWaterVapour', 'Mass Concentration of Water Vapour', 'Mass Concentration of Water is one of a number of Concentration quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/MassConcentrationRateOfChange', 'Mass Concentration Rate of Change', 'the rate at which a specific chemical element or compound changes concentration over time, where with concentration expressed as mass per volume. SI unit is kg * m-3 * s-1'),
('http://qudt.org/vocab/quantitykind/MassDefect', 'Mass Defect', 'The "Mass Defect", also termed mass deficit, or mass packing fraction, describes mass change (decrease) in bound systems, particularly atomic nuclei.'),
('http://qudt.org/vocab/quantitykind/MassDensity', 'Mass Density', 'The mass density or density of a material is its mass per unit volume.'),
('http://qudt.org/vocab/quantitykind/MassEnergyTransferCoefficient', 'Mass Energy Transfer Coefficient', '"Mass Energy Transfer Coefficient" is that fraction of the mass attenuation coefficient which contributes to the production of kinetic energy in charged particles.'),
('http://qudt.org/vocab/quantitykind/MassEquivalent', 'Mass Equivalent', '"Mass Equivalent" is the mass of a substance that reacts with (or is equivalent to) an arbitrary mass of another substance in a given chemical reaction.'),
('http://qudt.org/vocab/quantitykind/MassExcess', 'Mass Excess', 'The "Mass Excess" of a nuclide is the difference between its actual mass and its mass number in atomic mass units. It is one of the predominant methods for tabulating nuclear mass.'),
('http://qudt.org/vocab/quantitykind/MassFlowRate', 'Mass Flow Rate', '"Mass Flow Rate" is a measure of Mass flux. The common symbol is m (pronounced m-dot), although sometimes μ is used. The SI units are kg s-1.'),
('http://qudt.org/vocab/quantitykind/MassFluxDensity', 'Mass Flux Density', 'product of flow velocity and density'),
('http://qudt.org/vocab/quantitykind/MassFraction', 'Mass Fraction', 'The "Mass Fraction" is the fraction of one substance with mass to the mass of the total mixture .'),
('http://qudt.org/vocab/quantitykind/MassFractionOfDryMatter', 'Mass Fraction of Dry Matter', '"Mass Fraction of Dry Matter" is one of a number of Concentration quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/MassFractionOfWater', 'Mass Fraction of Water', 'Mass Fraction of Water is one of a number of Concentration quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/MassNumber', 'Mass Number', 'The "Mass Number" (A), also called atomic mass number or nucleon number, is the total number of protons and neutrons (together known as nucleons) in an atomic nucleus. Nuclides with the same value of A are called isobars.'),
('http://qudt.org/vocab/quantitykind/MassOfElectricalPowerSupply', 'Mass of Electrical Power Supply', NULL),
('http://qudt.org/vocab/quantitykind/MassOfSolidBooster', 'Mass of Solid Booster', NULL),
('http://qudt.org/vocab/quantitykind/MassOfTheEarth', 'Mass of the Earth', 'Earth mass is the unit of mass equal to that of the Earth. Earth mass is often used to describe masses of rocky terrestrial planets.'),
('http://qudt.org/vocab/quantitykind/MassPerArea', 'Mass per Area', 'The area density (also known as areal density, surface density, or superficial density) of a two-dimensional object is calculated as the mass per unit area. The SI derived unit is: kilogram per square metre (kg · m^-2).'),
('http://qudt.org/vocab/quantitykind/MassPerAreaTime', 'Mass per Area Time', 'In Physics and Engineering, mass flux is the rate of mass flow per unit area. The common symbols are j, J, φ, or Φ (Greek lower or capital Phi), sometimes with subscript m to indicate mass is the flowing quantity. Its SI units are kg s^-1 m^-2.'),
('http://qudt.org/vocab/quantitykind/MassPerElectricCharge', 'Mass per Electric Charge', 'The mass-to-charge ratio ratio (m/Q) is a physical quantity that is widely used in the electrodynamics of charged particles, for example, in electron optics and ion optics. The importance of the mass-to-charge ratio, according to classical electrodynamics, is that two particles with the same mass-to-charge ratio move in the same path in a vacuum when subjected to the same electric and magnetic fields. Its SI units are kg/C, but it can also be measured in Thomson (Th).'),
('http://qudt.org/vocab/quantitykind/MassPerEnergy', 'Mass per Energy', 'Mass per Energy is a physical quantity that can be used to relate the energy of a system to its mass.'),
('http://qudt.org/vocab/quantitykind/MassPerLength', 'Mass per Length', 'Linear density, linear mass density or linear mass is a measure of mass per unit of length, and it is a characteristic of strings or other one-dimensional objects. The SI unit of linear density is the kilogram per metre (kg/m).'),
('http://qudt.org/vocab/quantitykind/MassPerTime', 'Mass per Time', NULL),
('http://qudt.org/vocab/quantitykind/MassRatio', 'Mass Ratio', 'In aerospace engineering, mass ratio is a measure of the efficiency of a rocket. It describes how much more massive the vehicle is with propellant than without; that is, it is the ratio of the rocket''s wet mass (vehicle plus contents plus propellant) to its dry mass (vehicle plus contents)'),
('http://qudt.org/vocab/quantitykind/MassRatioOfWaterToDryMatter', 'Mass Concentration of Water to Dry Matter', 'Mass Ratio of Water to Dry Matter is one of a number of Concentration Ratio quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/MassRatioOfWaterVapourToDryGas', 'Mass Ratio of Water Vapour to Dry Gas', 'Mass Ratio of Water Vapour to Dry Gas is one of a number of Concentration Ratio quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/MassRelatedElectricalCurrent', 'Mass-related Electrical Current', 'electrical current intensity divided by the associated mass'),
('http://qudt.org/vocab/quantitykind/MassSpecificBiogeochemicalRate', 'Mass Specific Biogeochemical Rate', 'the rate at which a specific chemical element or compound is processed or transformed within an ecosystem, calculated per unit mass of the relevant biological material. Unreduced, SI unit is g * g-1 * s-1'),
('http://qudt.org/vocab/quantitykind/MassStoppingPower', 'Mass Stopping Power', NULL),
('http://qudt.org/vocab/quantitykind/MassTemperature', 'Mass Temperature', NULL),
('http://qudt.org/vocab/quantitykind/MassicActivity', 'Massic Activity', '"Massic Activity" is the activity divided by the total mass of the sample.'),
('http://qudt.org/vocab/quantitykind/MassicElectricCurrent', 'Massic Electric Current', NULL),
('http://qudt.org/vocab/quantitykind/MassicHeatCapacity', 'Massic Heat Capacity', 'ratio of heat capacity divided by mass'),
('http://qudt.org/vocab/quantitykind/MassicPower', 'Massic Power', 'ratio energy divided by time and related mass'),
('http://qudt.org/vocab/quantitykind/MassicTorque', 'Massic Torque', 'ratio of torque divided by the mass to be moved'),
('http://qudt.org/vocab/quantitykind/MassieuFunction', 'Massieu Function', 'The Massieu function, Ψ, is defined as: Ψ = Ψ (X_1, … , X_i, Y_i+1, … , Y_r ), where for every system with degree of freedom r one may choose r variables, e.g. , to define a coordinate system, where X and Y are extensive and intensive variables, respectively, and where at least one extensive variable must be within this set in order to define the size of the system. The (r + 1)^th variable,Ψ , is then called the Massieu function.'),
('http://qudt.org/vocab/quantitykind/MaxExpectedOperatingThrust', 'Maximum Expected Operating Thrust', NULL),
('http://qudt.org/vocab/quantitykind/MaxOperatingThrust', 'Max Operating Thrust', NULL),
('http://qudt.org/vocab/quantitykind/MaxSeaLevelThrust', 'Max Sea Level Thrust', NULL),
('http://qudt.org/vocab/quantitykind/MaximumBetaParticleEnergy', 'Maximum Beta-Particle Energy', '"Maximum Beta-Particle Energy" is the maximum energy of the energy spectrum in a beta-particle disintegration process.'),
('http://qudt.org/vocab/quantitykind/MaximumExpectedOperatingPressure', 'Maximum Expected Operating Pressure', NULL),
('http://qudt.org/vocab/quantitykind/MaximumOperatingPressure', 'Maximum Operating Pressure', NULL),
('http://qudt.org/vocab/quantitykind/MeanEnergyImparted', 'Mean Energy Imparted', 'The "Mean Energy Imparted", is the average energy imparted to irradiated matter.'),
('http://qudt.org/vocab/quantitykind/MeanFreePath', 'Mean Free Path', '"Mean Free Path" is the average distance travelled by a moving particle (such as an atom, a molecule, a photon) between successive impacts (collisions) which modify its direction or energy or other particle properties.'),
('http://qudt.org/vocab/quantitykind/MeanLifetime', 'Mean Lifetime', 'The "Mean Lifetime" is the average length of time that an element remains in the set of discrete elements in a decaying quantity, N(t).'),
('http://qudt.org/vocab/quantitykind/MeanLinearRange', 'Mean Linear Range', '"Mean Linear Range" is, in a given material, for specified charged particles of a specified energy, the average displacement of the particles before they stop. That is, the mean totl rectified path length travelled by a particle in the course of slowing down to rest (or to some suitable cut-off energy) in a given substance under specified conditions averaged over a group of particles having the same initial energy.'),
('http://qudt.org/vocab/quantitykind/MeanMassRange', 'Mean Mass Range', '"Mean Mass Range" is the mean linear range multiplied by the mass density of the material.'),
('http://qudt.org/vocab/quantitykind/MechanicalEnergy', 'Mechanical Energy', 'Mechanical Energy is the sum of potential energy and kinetic energy. It is the energy associated with the motion and position of an object.'),
('http://qudt.org/vocab/quantitykind/MechanicalImpedance', 'Mechanical Impedance', 'Mechanical impedance is the complex quotient of the force applied to a system by the resulting velocity at the point of application, Z_m = F/v. Its coherent unit is the newton second per metre (N·s/m), historically called the mechanical ohm. Contrast quantitykind:MechanicalSurfaceImpedance, which is a force per unit area divided by velocity.'),
('http://qudt.org/vocab/quantitykind/MechanicalMobility', 'Mechanical Mobility', NULL),
('http://qudt.org/vocab/quantitykind/MechanicalSurfaceImpedance', 'Mechanical Surface Impedance', 'Mechanical surface impedance at a surface, is the complex quotient of the total force on the surface by the component of the average sound particle velocity at the surface in the direction of the force'),
('http://qudt.org/vocab/quantitykind/MechanicalTension', 'Mechanical Tension', 'at a point of a body upon which a force acts which attempts to change the shape of the body, the limit value of the ratio between the force and area of a flat surface around this point when the dimensions approach zero'),
('http://qudt.org/vocab/quantitykind/MeltingPoint', 'Melting Point Temperature', 'A temperature that is the one at which a substance will change its physical state from a solid to a liquid. It is also the temperature where the solid and liquid forms of a pure substance can exist in equilibrium.'),
('http://qudt.org/vocab/quantitykind/MicroCanonicalPartitionFunction', 'Micro Canonical Partition Function', 'A "Micro Canonical Partition Function" applies to a micro canonical ensemble, in which the system is allowed to exchange heat with the environment at fixed temperature, volume, and a fixed number of particles.'),
('http://qudt.org/vocab/quantitykind/MigrationArea', 'Migration Area', '"Migration Area" is the sum of the slowing-down area from fission energy to thermal energy and the diffusion area for thermal neutrons.'),
('http://qudt.org/vocab/quantitykind/MigrationLength', 'Migration Length', '"Migration Length" is the square root of the migration area.'),
('http://qudt.org/vocab/quantitykind/Mobility', 'Mobility', '"Mobility" characterizes how quickly a particle can move through a metal or semiconductor, when pulled by an electric field. The average drift speed imparted to a charged particle in a medium by an electric field, divided by the electric field strength.'),
('http://qudt.org/vocab/quantitykind/MobilityRatio', 'Mobility Ratio', '"MobilityRatio" describes permeability of a porous material to a given phase divided by the viscosity of that phase.'),
('http://qudt.org/vocab/quantitykind/ModulusOfAdmittance', 'Modulus of Admittance', '"Modulus Of Admittance" is the absolute value of the quantity "admittance".'),
('http://qudt.org/vocab/quantitykind/ModulusOfElasticity', 'Modulus of Elasticity', 'The Modulus of Elasticity is the mathematical description of an object or substance''s tendency to be deformed elastically (that is, non-permanently) when a force is applied to it.'),
('http://qudt.org/vocab/quantitykind/ModulusOfImpedance', 'Modulus of Impedance', '"Modulus Of Impedance is the absolute value of the quantity impedance. Apparent impedance is defined more generally as the quotient of rms voltage and rms electric current; it is often denoted by Z.'),
('http://qudt.org/vocab/quantitykind/ModulusOfLinearSubgradeReaction', 'Modulus of Linear Subgrade Reaction', 'Modulus of Linear Subgrade Reaction is a measure for modulus of linear subgrade reaction, which expresses the elastic bedding of a linear structural element per length, such as for a beam. It is typically measured in N/m^2'),
('http://qudt.org/vocab/quantitykind/ModulusOfRotationalSubgradeReaction', 'Modulus of Rotational Subgrade Reaction', 'Modulus of Rotational Subgrade Reaction is a measure for modulus of rotational subgrade reaction, which expresses the rotational elastic bending of a linear structural element per length, such as for a beam. It is typically measured in Nm/(m*rad).'),
('http://qudt.org/vocab/quantitykind/ModulusOfSubgradeReaction', 'Modulus of Subgrade Reaction', 'Modulus of Subgrade Reaction is a geotechnical measure describing interaction between foundation structures and the soil. May also be known as bedding measure. Usually measured in N/m3.'),
('http://qudt.org/vocab/quantitykind/MoistureDiffusivity', 'Moisture Diffusivity', NULL),
('http://qudt.org/vocab/quantitykind/MolalityOfSolute', 'Molality of Solute', 'The "Molality of Solute" of a solution is defined as the amount of substance of solute divided by the mass in kg of the solvent.'),
('http://qudt.org/vocab/quantitykind/MolarAbsorptionCoefficient', 'Molar Absorption Coefficient', '"Molar Absorption Coefficient" is a spectrophotometric unit indicating the light a substance absorbs with respect to length, usually centimeters, and concentration, usually moles per liter.'),
('http://qudt.org/vocab/quantitykind/MolarAngularMomentum', 'Molar Angular Momentum', NULL),
('http://qudt.org/vocab/quantitykind/MolarAttenuationCoefficient', 'Molar Attenuation Coefficient', '"Molar Attenuation Coefficient" is a measurement of how strongly a chemical species or substance absorbs or scatters light at a given wavelength, per amount of substance.'),
('http://qudt.org/vocab/quantitykind/MolarConductivity', 'Molar Conductivity', '"Molar Conductivity" is the conductivity of an electrolyte solution divided by the molar concentration of the electrolyte, and so measures the efficiency with which a given electrolyte conducts electricity in solution.'),
('http://qudt.org/vocab/quantitykind/MolarDensity', 'Molar Density', 'quantity whose value is inversely proportional to the quantity of material'),
('http://qudt.org/vocab/quantitykind/MolarEnergy', 'Molar Energy', '"Molar Energy" is the total energy contained by a thermodynamic system. The unit is J/mol, also expressed as joule/mole, or joules per mole. This unit is commonly used in the SI unit system. The quantity has the dimension of M · L^2 · T^-2 · N^-1 where M is mass, L is length, T is time, and N is amount of substance.'),
('http://qudt.org/vocab/quantitykind/MolarEntropy', 'Molar Entropy', 'The "Standard Molar Entropy" is the entropy content of one mole of substance, under standard conditions (not standard temperature and pressure STP).'),
('http://qudt.org/vocab/quantitykind/MolarEquivalent', 'Molar Equivalent', '"Molar Equivalent" is the amount of a substance that reacts with (or is equivalent to) an arbitrary amount (typically one mole) of another substance in a given chemical reaction.'),
('http://qudt.org/vocab/quantitykind/MolarFlowRate', 'Molar Flow Rate', 'Molar Flow Rate is a measure of the amount of substance (the number of molecules) that passes through a given area perpendicular to the flow in a given time. Typically this area is constrained, for example a section through a pipe, but it could also apply to an open flow.'),
('http://qudt.org/vocab/quantitykind/MolarFluxDensity', 'Molar Flux Density', 'the rate at which moles of a substance pass through a unit area per unit time. It is used for describing the flow of materials in terms of the transport of molecules or particles rather than bulk mass. The SI units are mol m-2 s-1'),
('http://qudt.org/vocab/quantitykind/MolarFluxDensityVariance', 'Molar Flux Density Variance', 'Variance for Molar Flux Density data.'),
('http://qudt.org/vocab/quantitykind/MolarHeatCapacity', 'Molar Heat Capacity', '"Molar Heat Capacity" is the amount of heat energy required to raise the temperature of 1 mole of a substance. In SI units, molar heat capacity (symbol: cn) is the amount of heat in joules required to raise 1 mole of a substance 1 Kelvin.'),
('http://qudt.org/vocab/quantitykind/MolarInternalEnergy', 'Molar Internal Energy', NULL),
('http://qudt.org/vocab/quantitykind/MolarMass', 'Molar Mass', 'In chemistry, the molar mass M is defined as the mass of a given substance (chemical element or chemical compound) divided by its amount of substance. It is a physical property of a given substance. The base SI unit for molar mass is kg/mol.'),
('http://qudt.org/vocab/quantitykind/MolarOpticalRotationalAbility', 'Molar Optical Rotational Ability', 'material-specific quantity resulting as the specific angle of rotation of a substance for a particular wavelength and a particular temperature from the relationship: ratio between measured angle of rotation divided by the concentration of material and the covered path'),
('http://qudt.org/vocab/quantitykind/MolarOpticalRotatoryPower', 'Molar Optical Rotatory Power', 'The "Molar Optical Rotatory Power" Angle of optical rotation divided by the optical path length through the medium and by the amount concentration giving the molar optical rotatory power.'),
('http://qudt.org/vocab/quantitykind/MolarRefractivity', 'Molar Refractivity', 'A quantity kind that is a measure of the total polarizability of a mole of substance that depends on the temperature, the index of refraction and the pressure.'),
('http://qudt.org/vocab/quantitykind/MolarThermalCapacity', 'Molar Thermal Capacity', 'thermal capacity divided by the amount of substance'),
('http://qudt.org/vocab/quantitykind/MolarThermodynamicEnergy', 'Molar Thermodynamic Energy', 'energy in relation to the amount of a substance'),
('http://qudt.org/vocab/quantitykind/MolarVolume', 'Molar Volume', 'The molar volume, symbol V_m, is the volume occupied by one mole of a substance (chemical element or chemical compound) at a given temperature and pressure. It is equal to the molar mass (M) divided by the mass density (ρ). It has the SI unit cubic metres per mole (m^1/mol). For ideal gases, the molar volume is given by the ideal gas equation: this is a good approximation for many common gases at standard temperature and pressure. For crystalline solids, the molar volume can be measured by X-ray crystallography.'),
('http://qudt.org/vocab/quantitykind/MoleFraction', 'Mole Fraction', 'In chemistry, the mole fraction of a component in a mixture is the relative proportion of molecules belonging to the component to those in the mixture, by number of molecules. It is one way of measuring concentration.'),
('http://qudt.org/vocab/quantitykind/MolecularConcentration', 'Molecular Concentration', 'The "Molecular Concentration" of substance B is defined as the number of molecules of B divided by the volume of the mixture'),
('http://qudt.org/vocab/quantitykind/MolecularMass', 'Molecular Mass', 'The molecular mass, or molecular weight of a chemical compound is the mass of one molecule of that compound, relative to the unified atomic mass unit, u. Molecular mass should not be confused with molar mass, which is the mass of one mole of a substance.'),
('http://qudt.org/vocab/quantitykind/MolecularViscosity', 'Molecular Viscosity', 'Molecules in a fluid close to a solid boundary sometime strike the boundary and transfer momentum to it. Molecules further from the boundary collide with molecules that have struck the boundary, further transferring the change in momentum into the interior of the fluid. This transfer of momentum is molecular viscosity. Molecules, however, travel only micrometers between collisions, and the process is very inefficient for transferring momentum even a few centimeters. Molecular viscosity is important only within a few millimeters of a boundary. The coefficient of molecular viscosity has the same value as the dynamic viscosity.'),
('http://qudt.org/vocab/quantitykind/MomentOfForce', 'Moment of Force', 'Moment of force (often just moment) is the tendency of a force to twist or rotate an object.'),
('http://qudt.org/vocab/quantitykind/MomentOfInertia', 'Moment of Inertia', 'The rotational inertia or resistance to change in direction or speed of rotation about a defined axis.'),
('http://qudt.org/vocab/quantitykind/MomentOfInertia_Y', 'Moment of Inertia in the Y Axis', 'The rotational inertia or resistance to change in direction or speed of rotation about a defined axis.'),
('http://qudt.org/vocab/quantitykind/MomentOfInertia_Z', 'Moment of Inertia in the Z Axis', 'The rotational inertia or resistance to change in direction or speed of rotation about a defined axis.'),
('http://qudt.org/vocab/quantitykind/Momentum', 'Momentum', 'The momentum of a system of particles is given by the sum of the momentums of the individual particles which make up the system or by the product of the total mass of the system and the velocity of the center of gravity of the system. The momentum of a continuous medium is given by the integral of the velocity over the mass of the medium or by the product of the total mass of the medium and the velocity of the center of gravity of the medium.'),
('http://qudt.org/vocab/quantitykind/MomentumPerAngle', 'Momentum per Angle', NULL),
('http://qudt.org/vocab/quantitykind/MorbidityRate', 'Morbidity Rate', 'Morbidity rate is a measure of the incidence of a disease in a particular population, scaled to the size of that population, per unit of time.'),
('http://qudt.org/vocab/quantitykind/MortalityRate', 'Mortality Rate', 'Mortality rate, or death rate, is a measure of the number of deaths (in general, or due to a specific cause) in a particular population, scaled to the size of that population, per unit of time.'),
('http://qudt.org/vocab/quantitykind/MotorConstant', 'Motor Constant', 'The motor constant, or motor size constant, K_m = τ / √P, is the torque of a motor divided by the square root of the power dissipated in its windings. It measures how effectively a motor produces torque per unit of resistive loss, independently of how the windings are wound, and is expressed in newton metres per square root watt (N · m / √W). Because it involves the square root of a power, its dimension carries the fractional exponents L^1 M^1/2 T^-1/2. The term "motor constant" is also used in the literature for two distinct quantities: the torque constant K_t = τ / I (see quantitykind:TorqueConstant) and the back-EMF constant K_e = V / ω, both of which have the dimension of magnetic flux and are numerically equal to one another in coherent SI units.'),
('http://qudt.org/vocab/quantitykind/MultiplicationFactor', 'Multiplication Factor', 'The "Multiplication Factor" is the ratio of the total number of fission or fission-dependent neutrons produced in a time interval to the total number of neutrons lost by absorption and leakage during the same interval.'),
('http://qudt.org/vocab/quantitykind/MutualInductance', 'Mutual Inductance', 'Mutual Inductance is the non-diagonal term of the inductance matrix. For two loops, the symbol M is used for L_12.'),
('http://qudt.org/vocab/quantitykind/NapierianAbsorbance', 'Napierian Absorbance', 'Napierian Absorbance is the natural (Napierian) logarithm of the reciprocal of the spectral internal transmittance.'),
('http://qudt.org/vocab/quantitykind/NeelTemperature', 'Neel Temperature', '"Neel Temperature" is the critical thermodynamic temperature of an antiferromagnet.'),
('http://qudt.org/vocab/quantitykind/NetTonnage', 'Net Tonnage', 'Net tonnage is used in the United States to determine eligibility for registering boats with the federal government. It is a nonlinear unit derived from the total volume of a ship''s cargo space as well as some dimensionless factors. Net tonnage is not a measure of the weight of the ship or its cargo, and should not be confused with terms such as deadweight tonnage or displacement. Net tonnage is also used to determine the amount of money that can be charged to a ship for using a port''s facilities.'),
('http://qudt.org/vocab/quantitykind/NeutralRatio', 'Neutral Ratio', 'ratio between two physical variables of the same type, expressed as a number which describes the relationship between these variables where the units are cancelled against each other'),
('http://qudt.org/vocab/quantitykind/NeutronDiffusionCoefficient', 'Diffusion Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/NeutronDiffusionLength', 'Neutron Diffusion Length', 'The neutron diffusion length is equivalent to the relaxation length, that is, to the distance, in which the neutron flux decreases by a factor e'),
('http://qudt.org/vocab/quantitykind/NeutronNumber', 'Neutron Number', '"Neutron Number", symbol N, is the number of neutrons in a nuclide. Nuclides with the same value of N but different values of Z are called isotones. N - Z is called the neutron excess number.'),
('http://qudt.org/vocab/quantitykind/NeutronYieldPerAbsorption', 'Neutron Yield per Absorption', 'The "Neutron Yield per Absorption" is the average number of fission neutrons, both prompt and delayed, emitted per neutron absorbed in a fissionable nuclide or in a nuclear fuel, as specified.'),
('http://qudt.org/vocab/quantitykind/NeutronYieldPerFission', 'Neutron Yield per Fission', 'The "Neutron Yield per Fission" is the average number of fission neutrons, both prompt and delayed, emitted per fission event.'),
('http://qudt.org/vocab/quantitykind/NonActivePower', 'Non-active Power', '"Non-active Power", for a two-terminal element or a two-terminal circuit under periodic conditions, is the quantity equal to the square root of the difference of the squares of the apparent power and the active power.'),
('http://qudt.org/vocab/quantitykind/NonLeakageProbability', 'Non-Leakage Probability', 'The "Non-Leakage Probability" is the probability that a neutron will not escape from the reactor during the slowing-down process or while it diffuses as a thermal neutron'),
('http://qudt.org/vocab/quantitykind/NonNegativeLength', 'Positive Length', '"NonNegativeLength" is a measure of length greater than or equal to zero.'),
('http://qudt.org/vocab/quantitykind/NormalStress', 'Normal Stress', 'Normal stress is defined as the stress resulting from a force acting normal to a body surface. Normal stress can be caused by several loading methods, the most common being axial tension and compression, bending, and hoop stress.'),
('http://qudt.org/vocab/quantitykind/NormalizedDimensionlessRatio', 'Positive Dimensionless Ratio', 'A "Normalized Dimensionless Ratio" is a dimensionless ratio ranging from 0.0 to 1.0'),
('http://qudt.org/vocab/quantitykind/NuclearEnergy', 'Nuclear Energy', NULL),
('http://qudt.org/vocab/quantitykind/NuclearQuadrupoleMoment', 'Nuclear Quadrupole Moment', '"Nuclear Quadrupole Moment" is a quantity that characterizes the deviation from spherical symmetry of the electrical charge distribution in an atomic nucleus.'),
('http://qudt.org/vocab/quantitykind/NuclearRadius', 'Nuclear Radius', '"Nuclear Radius" is the conventional radius of sphere in which the nuclear matter is included'),
('http://qudt.org/vocab/quantitykind/NuclearSpinQuantumNumber', 'Spin Quantum Number', 'The "Spin Quantum Number" describes the spin (intrinsic angular momentum) of the electron within that orbital, and gives the projection of the spin angular momentum S along the specified axis'),
('http://qudt.org/vocab/quantitykind/NucleonNumber', 'Nucleon Number', 'Number of nucleons in an atomic nucleus.A = Z+N. Nuclides with the same value of A are called isobars.'),
('http://qudt.org/vocab/quantitykind/NumberDensity', 'Number Density', 'In physics, astronomy, and chemistry, number density (symbol: n) is a kind of quantity used to describe the degree of concentration of countable objects (atoms, molecules, dust particles, galaxies, etc.) in the three-dimensional physical space.'),
('http://qudt.org/vocab/quantitykind/NumberOfElectricalPhases', 'Number of Electrical Phases', '"Number of Electrical Phases" is used to characterize AC electrical service to a facility.'),
('http://qudt.org/vocab/quantitykind/NumberOfParticles', 'Number of Particles', '"Number of Particles", also known as the particle number, of a thermodynamic system, conventionally indicated with the letter N, is the number of constituent particles in that system.'),
('http://qudt.org/vocab/quantitykind/OlfactoryThreshold', 'Olfactory Threshold', '"Olfactory Threshold" are thresholds for the concentrations of various classes of smell that can be detected.'),
('http://qudt.org/vocab/quantitykind/OpeningRatio', 'Opening Ratio', 'In the context of mechanical systems, "opening ratio" might refer to the proportion of time or the extent to which a valve or gate is open relative to its maximum capacity.'),
('http://qudt.org/vocab/quantitykind/OrbitalAngularMomentumPerMass', 'Orbital Angular Momentum per Mass', 'Angular momentum of the orbit per mass of the vehicle'),
('http://qudt.org/vocab/quantitykind/OrbitalAngularMomentumQuantumNumber', 'Orbital Angular Momentum Quantum Number', 'The "Principal Quantum Number" describes the electron shell, or energy level, of an atom. The value of n ranges from 1 to the shell containing the outermost electron of that atom.'),
('http://qudt.org/vocab/quantitykind/OrbitalRadialDistance', 'Orbital Radial Distance', NULL),
('http://qudt.org/vocab/quantitykind/OrderOfReflection', 'Order of Reflection', '"Order of Reflection" is n in the Bragg''s Law equation.'),
('http://qudt.org/vocab/quantitykind/OsmoticCoefficient', 'Osmotic Coefficient', 'The "Osmotic Coefficient" is a quantity which characterises the deviation of a solvent from ideal behavior.'),
('http://qudt.org/vocab/quantitykind/OsmoticConcentration', 'Osmotic Concentration', 'The "Osmotic Concentration" is the moles of an osmotically active entity (solute) in the volume of a solution.'),
('http://qudt.org/vocab/quantitykind/OsmoticPressure', 'Osmotic Pressure', 'The "Osmotic Pressure" is the pressure which needs to be applied to a solution to prevent the inward flow of water across a semipermeable membrane.'),
('http://qudt.org/vocab/quantitykind/OverRangeDistance', 'Over-range Distance', 'Additional distance traveled by a rocket because Of excessive initial velocity.'),
('http://qudt.org/vocab/quantitykind/Pace', 'Pace', 'Running is often measured in terms of pace, expressed in units of minutes per mile or minutes per kilometer (the inverse of speed, in mph or km/h).'),
('http://qudt.org/vocab/quantitykind/PackingFraction', 'Packing Fraction', 'The "Packing Fraction" is the fraction of volume in a crystal structure that is occupied by atoms.'),
('http://qudt.org/vocab/quantitykind/PartialPressure', 'Partial Pressure', '"Partial Pressure" is the pressure that the gas would have if it alone occupied the volume of the mixture at the same temperature.'),
('http://qudt.org/vocab/quantitykind/ParticleCurrent', 'Particle Current', '"Particle Current" can be used to describe the net number of particles passing through a surface in an infinitesimal time interval.'),
('http://qudt.org/vocab/quantitykind/ParticleCurrentDensity', 'Particle Current Density', 'The quantity kind Particle Current Density is a vector whose component is perpendicular to a surface equal to the net number of particles crossing that surface in the positive direction per unit area and per unit time.'),
('http://qudt.org/vocab/quantitykind/ParticleFluence', 'Particle Fluence', '"Particle Fluence" is the total number of particles that intersect a unit area in a specific time interval of interest, and has units of /m2 (number of particles per meter squared).'),
('http://qudt.org/vocab/quantitykind/ParticleFluenceRate', 'Particle Fluence Rate', '"Particle Fluence Rate" can be defined as the total number of particles (typically Gamma Ray Photons ) crossing over a sphere of unit cross section which surrounds a Point Source of Ionising Radiation.'),
('http://qudt.org/vocab/quantitykind/ParticleNumberDensity', 'Particle Number Density', 'The "Particle Number Density" is obtained by dividing the particle number of a system by its volume.'),
('http://qudt.org/vocab/quantitykind/ParticlePositionVector', 'Particle Position Vector', '"Particle Position Vector" is the position vector of a particle.'),
('http://qudt.org/vocab/quantitykind/ParticleSourceDensity', 'Particle Source Density', '"Particle Source Density" is the rate of production of particles in a 3D domain divided by the volume of that element.'),
('http://qudt.org/vocab/quantitykind/PathLength', 'Path Length', '"PathLength" is'),
('http://qudt.org/vocab/quantitykind/PayloadMass', 'Payload Mass', 'Payload mass is the mass of the payload carried by the craft. In a multistage spacecraft the payload mass of the last stage is the mass of the payload and the payload masses of the other stages are considered to be the gross masses of the next stages.'),
('http://qudt.org/vocab/quantitykind/PayloadRatio', 'Payload Ratio', 'The payload ratio is defined as the mass of the payload divided by the empty mass of the structure. Because of the extra cost involved in staging rockets, given the choice, it''s often more economic to use few stages with a small payload ratio rather than more stages each with a high payload ratio.'),
('http://qudt.org/vocab/quantitykind/PeltierCoefficient', 'Peltier Coefficient', '"Peltier Coefficient" represents how much heat current is carried per unit charge through a given material. It is the heat power developed at a junction, divided by the electric current flowing from substance a to substance b.'),
('http://qudt.org/vocab/quantitykind/Period', 'Period', 'Duration of one cycle of a periodic phenomenon.'),
('http://qudt.org/vocab/quantitykind/Permeability', 'Permeability', NULL),
('http://qudt.org/vocab/quantitykind/PermeabilityRatio', 'Permeability Ratio', 'The ratio of the effective permeability of a porous phase to the absolute permeability.'),
('http://qudt.org/vocab/quantitykind/Permeance', 'Permeance', '"Permeance" is the inverse of reluctance. Permeance is a measure of the quantity of flux for a number of current-turns in magnetic circuit. A magnetic circuit almost acts as though the flux is "conducted", therefore permeance is larger for large cross sections of a material and smaller for longer lengths. This concept is analogous to electrical conductance in the electric circuit.'),
('http://qudt.org/vocab/quantitykind/Permittivity', 'Permittivity', '"Permittivity" is a physical quantity that describes how an electric field affects, and is affected by a dielectric medium, and is determined by the ability of a material to polarize in response to the field, and thereby reduce the total electric field inside the material. Permittivity is often a scalar valued quantity, however in the general case it is tensor-valued.'),
('http://qudt.org/vocab/quantitykind/PermittivityRatio', 'Permittivity Ratio', '"Permittivity Ratio" is the ratio of permittivity to the permittivity of a vacuum.'),
('http://qudt.org/vocab/quantitykind/PhaseCoefficient', 'Phase Coefficient', 'The phase coefficient is the amount of phase shift that occurs as the wave travels one meter. Increasing the loss of the material, via the manipulation of the material''s conductivity, will decrease the wavelength (increase β) and increase the attenuation coefficient (increase α).'),
('http://qudt.org/vocab/quantitykind/PhaseDifference', 'Phase Difference', '"Phase Difference" is the difference, expressed in degrees, between two waves having the same frequency and referenced to the same point in time. Two oscillators that have the same frequency and different phases have a phase difference, and the oscillators are said to be out of phase with each other. The amount by which such oscillators are out of step with each other can be expressed in degrees from 0° to 360°, or in radians from 0 to 2π. If the phase difference is 180° (π radians), then the two oscillators are said to be in antiphase.'),
('http://qudt.org/vocab/quantitykind/PhaseSpeedOfSound', 'Phase Speed of Sound', 'In a dispersive medium sound speed is a function of sound frequency, through the dispersion relation. The spatial and temporal distribution of a propagating disturbance will continually change. Each frequency component propagates at its own Phase Velocity of Sound.'),
('http://qudt.org/vocab/quantitykind/PhononMeanFreePath', 'Phonon Mean Free Path', '"Phonon Mean Free Path" is the mean free path of phonons.'),
('http://qudt.org/vocab/quantitykind/PhotoThresholdOfAwarenessFunction', 'Photo Threshold of Awareness Function', '"Photo Threshold of Awareness Function" is the smallest amount of light the human eye can detect for a stimulus subtending a 1° radial angle at the eye. Because detection is governed by temporal summation (Bloch''s law), within the critical duration the threshold is reached when luminous energy — luminance integrated over time — attains a constant value, so the quantity is expressed as a luminous energy (lumen second). Where the presentation duration is instead held fixed, the same threshold may be reported as a light level, i.e. a luminance (candela per square metre) or illuminance (lux).'),
('http://qudt.org/vocab/quantitykind/PhotonIntensity', 'Photon Intensity', 'A measure of flux of photons per solid angle'),
('http://qudt.org/vocab/quantitykind/PhotonLuminance', 'Photon Luminance', 'ratio between the photon flux at a point on a surface and in a given direction and the product of the solid angle and the orthogonal projection of this element on a plane perpendicular to the given direction'),
('http://qudt.org/vocab/quantitykind/PhotonRadiance', 'Photon Radiance', 'A measure of flux of photons per surface area per solid angle'),
('http://qudt.org/vocab/quantitykind/PhotosyntheticPhotonFlux', 'Photosynthetic Photon Flux', 'Photosynthetic Photon Flux (PPF) is a measurement of the total number of photons emitted by a light source each second within the PAR wavelength range and is measured in μmol/s. Lighting manufacturers may specify their grow light products in terms of PPF. It can be considered as analogous to measuring the luminous flux (lumens) of visible light which would typically require the use of an integrating sphere or a goniometer system with spectroradiometer sensor.'),
('http://qudt.org/vocab/quantitykind/PhotosyntheticPhotonFluxDensity', 'Photosynthetic Photon Flux Density', 'Photosynthetically Active Radiation are the wavelengths of light within the visible range of 400 to 700 nanometers (nm) that are critical for photosynthesis. PPFD measures the amount of PAR light (photons) that arrive at the plant’s surface each second. The PPFD is measured at various distances with a Full-spectrum Quantum Sensor, also known as a PAR meter. Natural sunlight has a PAR value of 900-1500μMol/m2/s when the sun is directly overhead. For a grow light to be effective, it should have PAR values of 500-1500 μMol/m2/s.'),
('http://qudt.org/vocab/quantitykind/PictureElement', 'Picture Element', 'smallest element of a display space (cell size) of a digitized two-dimensional field representation of an image which has an address (x and y coordinates corresponding to its position in the field) and a specific brightness value'),
('http://qudt.org/vocab/quantitykind/Piece', 'Piece', NULL),
('http://qudt.org/vocab/quantitykind/PlanarForce', 'Planar Force', 'Another name for Force Per Area, used by the Industry Foundation Classes (IFC) standard.'),
('http://qudt.org/vocab/quantitykind/PlanckFunction', 'Planck Function', 'In the ISO System of Quantities, the Planck function is defined by the formula Y = -G/T, where G is Gibbs energy and T is thermodynamic temperature. It is a thermodynamic potential divided by temperature (a "free entropy"), expressed in joules per kelvin, and is the Gibbs-energy counterpart of the Massieu function J = -A/T. The same name is also widely used in radiometry for the spectral radiance B(T) emitted by a black body, given by Planck''s law; that is a different quantity, of a different dimension, and is covered by quantitykind:SpectralRadiance.'),
('http://qudt.org/vocab/quantitykind/PlaneAngle', 'Plane Angle', 'An angle formed by two straight lines (in the same plane) angle - the space between two lines or planes that intersect; the inclination of one line to another; measured in degrees or radians'),
('http://qudt.org/vocab/quantitykind/PlasmaLevel', 'Plasma Level', 'Concentration of a biologically active substance in blood plasma, expressed in International Units per volume (e.g. IU/L). It is dimensioned as mass concentration, following the mass-equivalent treatment of the International Unit (see unit:IU and quantitykind:AmountOfBiologicallyActiveSubstance), not as amount-of-substance concentration.'),
('http://qudt.org/vocab/quantitykind/PoissonRatio', 'Poisson Ratio', 'The Poisson Ratio is the negative ratio of transverse to axial strain. In fact, when a sample object is stretched (or squeezed), to an extension (or contraction) in the direction of the applied load, it corresponds a contraction (or extension) in a direction perpendicular to the applied load. The ratio between these two quantities is the Poisson''s ratio.'),
('http://qudt.org/vocab/quantitykind/PolarMomentOfInertia', 'Polar Moment of Inertia', 'The polar moment of inertia is a quantity used to predict an object''s ability to resist torsion, in objects (or segments of objects) with an invariant circular cross-section and no significant warping or out-of-plane deformation. It is used to calculate the angular displacement of an object subjected to a torque. It is analogous to the area moment of inertia, which characterizes an object''s ability to resist bending.'),
('http://qudt.org/vocab/quantitykind/Polarizability', 'Polarisability', '"Polarizability" is the relative tendency of a charge distribution, like the electron cloud of an atom or molecule, to be distorted from its normal shape by an external electric field, which may be caused by the presence of a nearby ion or dipole. The electronic polarizability α is defined as the ratio of the induced dipole moment of an atom to the electric field that produces this dipole moment. Polarizability is often a scalar valued quantity, however in the general case it is tensor-valued.'),
('http://qudt.org/vocab/quantitykind/PolarizationField', 'Polarization Field', 'The Polarization Field is the vector field that expresses the density of permanent or induced electric dipole moments in a dielectric material. The polarization vector P is defined as the ratio of electric dipole moment per unit volume.'),
('http://qudt.org/vocab/quantitykind/Population', 'Population', 'Population typically refers to the number of people in a single area, whether it be a city or town, region, country, continent, or the world, but can also represent the number of any kind of entity.'),
('http://qudt.org/vocab/quantitykind/PositionVector', 'Position Vector', 'A "Position Vector", also known as location vector or radius vector, is a Euclidean vector which represents the position of a point P in space in relation to an arbitrary reference origin O.'),
('http://qudt.org/vocab/quantitykind/PositiveDimensionlessRatio', 'Positive Dimensionless Ratio', 'A "Positive Dimensionless Ratio" is a dimensionless ratio that is greater than zero'),
('http://qudt.org/vocab/quantitykind/PositiveLength', 'Positive Length', '"PositiveLength" is a measure of length strictly greater than zero.'),
('http://qudt.org/vocab/quantitykind/PositivePlaneAngle', 'Positive Plane Angle', 'A "PositivePlaneAngle" is a plane angle strictly greater than zero.'),
('http://qudt.org/vocab/quantitykind/PotentialEnergy', 'Potential Energy', 'Energy possessed by a body by virtue of its position in a gravity field in contrast with kinetic energy, that possessed by virtue of its motion.'),
('http://qudt.org/vocab/quantitykind/Power', 'Power', 'Power is the rate at which work is performed or energy is transmitted, or the amount of energy required or expended for a given unit of time. As a rate of change of work done or the energy of a subsystem, power is: P = W/t, where P is power, W is work and t is time.'),
('http://qudt.org/vocab/quantitykind/PowerArea', 'Power Area', NULL),
('http://qudt.org/vocab/quantitykind/PowerAreaPerSolidAngle', 'Power Area per Solid Angle', NULL),
('http://qudt.org/vocab/quantitykind/PowerConstant', 'Power Constant', 'ratio indicating the relationship between continuous power and continuous current'),
('http://qudt.org/vocab/quantitykind/PowerDensity', 'Power Density', NULL),
('http://qudt.org/vocab/quantitykind/PowerFactor', 'Power Factor', '"Power Factor", under periodic conditions, is the ratio of the absolute value of the active power P to the apparent power S.'),
('http://qudt.org/vocab/quantitykind/PowerPerArea', 'Power per Area', NULL),
('http://qudt.org/vocab/quantitykind/PowerPerAreaAngle', 'Power per Area Angle', NULL),
('http://qudt.org/vocab/quantitykind/PowerPerAreaQuarticTemperature', 'Power per Area Quartic Temperature', NULL),
('http://qudt.org/vocab/quantitykind/PowerPerElectricCharge', 'Power per Electric Charge', '"Power Per Electric Charge" is the amount of energy generated by a unit of electric charge.'),
('http://qudt.org/vocab/quantitykind/PowerPerVolume', 'Power per Volume', NULL),
('http://qudt.org/vocab/quantitykind/PoyntingVector', 'Poynting Vector', '"Poynting Vector" is the vector product of the electric field strength E and the magnetic field strength H" of the electromagnetic field at a given point. The flux of the Poynting vector through a closed surface is equal to the electromagnetic power passing through this surface. For a periodic electromagnetic field, the time average of the Poynting vector is a vector of which, with certain reservations, the direction may be considered as being the direction of propagation of electromagnetic energy and the magnitude considered as being the average electromagnetic power flux density.'),
('http://qudt.org/vocab/quantitykind/Pressure', 'Pressure', 'Pressure is an effect which occurs when a force is applied on a surface. Pressure is the amount of force acting on a unit area. Pressure is distinct from stress, as the former is the ratio of the component of force normal to a surface to the surface area. Stress is a tensor that relates the vector force to the vector area.'),
('http://qudt.org/vocab/quantitykind/PressureBasedAmountOfSubstanceConcentration', 'Pressure-based Amount-of-substance Concentration', 'ratio between the amount-of-substance concentration of a dissolved material (its amount of substance divided by the volume of the solution) and the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedDensity', 'Pressure-based Density', 'ratio of density divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedDynamicViscosity', 'Pressure-based Dynamic Viscosity', 'ratio of dynamic viscosity divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedElectricCurrent', 'Pressure-based Electric Current', 'ratio of electric current divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedElectricVoltage', 'Pressure-based Electric Voltage', 'ratio of electric voltage divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedKinematicViscosity', 'Pressure-based Kinematic Viscosity', 'ratio of dynamic viscosity and density of the material divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedLength', 'Pressure-based Length', 'ratio of length divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedMass', 'Pressure-based Mass', 'ratio of mass divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedMassFlow', 'Pressure-based Mass Flow', 'ratio of mass flow divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedMolality', 'Pressure-based Molality', 'ratio of molality divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedQuantity', 'Pressure-based Quantity', NULL),
('http://qudt.org/vocab/quantitykind/PressureBasedTemperature', 'Pressure-based Temperature', 'ratio of temperature divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedVelocity', 'Pressure-based Velocity', 'ratio of velocity divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedVolume', 'Pressure-based Volume', 'ratio of volume divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBasedVolumeFlow', 'Pressure-based Volume Flow', 'ratio of volume flow divided by the related pressure'),
('http://qudt.org/vocab/quantitykind/PressureBurningRateConstant', 'Pressure Burning Rate Constant', NULL),
('http://qudt.org/vocab/quantitykind/PressureBurningRateIndex', 'Pressure Burning Rate Index', NULL),
('http://qudt.org/vocab/quantitykind/PressureCoefficient', 'Pressure Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/PressureGradient', 'Pressure Gradient', 'differential pressure divided by the associated length'),
('http://qudt.org/vocab/quantitykind/PressureInRelationToVolumeFlow', 'Pressure in Relation to Volume Flow', 'ratio between pressure and the volume flow at a given cross-sectional area, passing through this cross-sectional area'),
('http://qudt.org/vocab/quantitykind/PressureInRelationToVolumeFlowRate', 'Pressure in Relation to Volume Flow Rate', NULL),
('http://qudt.org/vocab/quantitykind/PressureLossPerLength', 'Pressure Loss per Length', '"Pressure Loss per Length" refers to the power lost in overcoming the friction between two moving surfaces. Also referred to as "Friction Loss".'),
('http://qudt.org/vocab/quantitykind/PressureRatio', 'Pressure Ratio', NULL),
('http://qudt.org/vocab/quantitykind/Prevalence', 'Prevalence', 'In epidemiology, prevalence is the proportion of a particular population found to be affected by a medical condition (typically a disease or a risk factor such as smoking or seatbelt use) at a specific time. (Wikipedia)'),
('http://qudt.org/vocab/quantitykind/PrincipalQuantumNumber', 'Principal Quantum Number', 'The "Principal Quantum Number" describes the electron shell, or energy level, of an atom. The value of n ranges from 1 to the shell containing the outermost electron of that atom.'),
('http://qudt.org/vocab/quantitykind/ProductOfInertia', 'Product of Inertia', 'A measure of a body''s dynamic (or coupled) imbalance resulting in a precession when rotating about an axis other than the body''s principal axis.'),
('http://qudt.org/vocab/quantitykind/ProductOfInertia_X', 'Product of Inertia in the X Axis', 'A measure of a body''s dynamic (or coupled) imbalance resulting in a precession when rotating about an axis other than the body''s principal axis.'),
('http://qudt.org/vocab/quantitykind/ProductOfInertia_Y', 'Product of Inertia in the Y Axis', 'The quantity kind ''Product of Inertia in the Y axis'' is a measure of a body''s dynamic (or coupled) imbalance resulting in a precession when rotating about an axis other than the body''s principal axis.'),
('http://qudt.org/vocab/quantitykind/ProductOfInertia_Z', 'Product of Inertia in the Z Axis', 'A measure of a body''s dynamic (or coupled) imbalance resulting in a precession when rotating about an axis other than the body''s principal axis.'),
('http://qudt.org/vocab/quantitykind/PropagationCoefficient', 'Propagation Coefficient', 'The propagation constant, symbol γ, for a given system is defined by the ratio of the amplitude at the source of the wave to the amplitude at some distance x.'),
('http://qudt.org/vocab/quantitykind/QualityFactor', 'Quality Factor', '"Quality Factor", of a resonant circuit, is a measure of the "goodness" or quality of a resonant circuit. A higher value for this figure of merit correspondes to a more narrow bandwith, which is desirable in many applications. More formally, Q is the ratio of power stored to power dissipated in the circuit reactance and resistance, respectively'),
('http://qudt.org/vocab/quantitykind/QuantityOfLight', 'Quantity of Light', 'work of a light source provided in the form of light as the product of the luminous flux Φ produced by the light source and the time t for which this is radiated'),
('http://qudt.org/vocab/quantitykind/QuantumNumber', 'Quantum Number', 'The "Quantum Number" describes values of conserved quantities in the dynamics of the quantum system. Perhaps the most peculiar aspect of quantum mechanics is the quantization of observable quantities, since quantum numbers are discrete sets of integers or half-integers.'),
('http://qudt.org/vocab/quantitykind/QuarticElectricDipoleMomentPerCubicEnergy', 'Quartic Electric Dipole Moment per Cubic Energy', NULL),
('http://qudt.org/vocab/quantitykind/RFPower', 'RF-Power Level', 'Radio-Frequency Power. Power level of electromagnetic waves alternating at the frequency of radio waves (up to 10^10 Hz).'),
('http://qudt.org/vocab/quantitykind/RadialDistance', 'Radial Distance', 'In classical geometry, the "Radial Distance" is a coordinate in polar coordinate systems (r, θ). Basically the radial distance is the scalar Euclidean distance between a point and the origin of the system of coordinates.'),
('http://qudt.org/vocab/quantitykind/Radiance', 'Radiance', '"Radiance" is a radiometric measure that describes the amount of light that passes through or is emitted from a particular area, and falls within a given solid angle in a specified direction.'),
('http://qudt.org/vocab/quantitykind/RadianceFactor', 'Radiance Factor', 'Radiance Factor is the ratio of the radiance of the surface element in the given direction to that of a perfect reflecting or transmitting diffuser identically irradiated unit.'),
('http://qudt.org/vocab/quantitykind/RadiantEmmitance', 'Radiant Emmitance', 'Irradiance and Radiant Emittance are radiometry terms for the power per unit area of electromagnetic radiation at a surface. "Irradiance" is used when the electromagnetic radiation is incident on the surface. "Radiant emmitance" (or "radiant exitance") is used when the radiation is emerging from the surface.'),
('http://qudt.org/vocab/quantitykind/RadiantEnergy', 'Radiant Energy', 'In radiometry,"Radiant Energy is the energy of electromagnetic waves. The quantity of radiant energy may be calculated by integrating radiant flux (or power) with respect to time. In nuclear physics, Radiant Energy" is energy, excluding rest energy, of the particles that are emitted, transferred, or received.'),
('http://qudt.org/vocab/quantitykind/RadiantEnergyDensity', 'Radiant Energy Density', '"Radiant Energy Density", or radiant power, is the radiant energy per unit volume.'),
('http://qudt.org/vocab/quantitykind/RadiantEnergyExposure', 'Radiant Energy Exposure', NULL),
('http://qudt.org/vocab/quantitykind/RadiantExposure', 'Radiant Exposure', 'Radiant exposure is a measure of the total radiant energy incident on a surface per unit area; equal to the integral over time of the radiant flux density. Also known as exposure.'),
('http://qudt.org/vocab/quantitykind/RadiantFluence', 'Radiant Fluence', 'Radiant fluence rate, or spherical irradiance, is equal to the total radiant flux incident on a small sphere divided by the area of the diametrical cross-section of the sphere.'),
('http://qudt.org/vocab/quantitykind/RadiantFluenceRate', 'Radiant Fluence Rate', 'Radiant fluence rate, or spherical irradiance, is equal to the total radiant flux incident on a small sphere divided by the area of the diametrical cross-section of the sphere.'),
('http://qudt.org/vocab/quantitykind/RadiantFlux', 'Radiant Flux', 'Radiant Flux, or radiant power, is the measure of the total power of electromagnetic radiation (including infrared, ultraviolet, and visible light). The power may be the total emitted from a source, or the total landing on a particular surface.'),
('http://qudt.org/vocab/quantitykind/RadiantIntensity', 'Radiant Intensity', 'Radiant Intensity is a measure of the intensity of electromagnetic radiation. It is defined as power per unit solid angle.'),
('http://qudt.org/vocab/quantitykind/RadiativeHeatTransfer', 'Radiative Heat Transfer', '"Radiative Heat Transfer" is proportional to (T_1^4 - T_2^4) and area of the surface, where T_1 and T_2 are thermodynamic temperatures of two black surfaces, for non totally black surfaces an additional factor less than 1 is needed.'),
('http://qudt.org/vocab/quantitykind/RadioactiveDecay', 'Radioactive Decay', NULL),
('http://qudt.org/vocab/quantitykind/Radioactivity', 'Radioactivity', 'number of spontaneous nuclear transformations in a defined amount of substance during a sufficiently small period of time divided by this period, expressed as a ratio ∂N/∂t, where ∂N is the expected value for the number of spontaneous transformations from this state within the time period ∂t'),
('http://qudt.org/vocab/quantitykind/Radiosity', 'Radiosity', 'Radiosity is the total emitted and reflected radiation leaving a surface.'),
('http://qudt.org/vocab/quantitykind/Radius', 'Radius', 'In classical geometry, the "Radius" of a circle or sphere is any line segment from its center to its perimeter the radius of a circle or sphere is the length of any such segment.'),
('http://qudt.org/vocab/quantitykind/RadiusOfCurvature', 'Radius of Curvature', 'In geometry, the "Radius of Curvature", R, of a curve at a point is a measure of the radius of the circular arc which best approximates the curve at that point.'),
('http://qudt.org/vocab/quantitykind/RadonExposure', 'Radon Exposure', 'Radon Exposure is the integral with respect to time of radon activity concentration accumulated during the exposure time. It is equivalent to the total number of radon decays per volume.'),
('http://qudt.org/vocab/quantitykind/RankineTemperature', 'Rankine Temperature', 'quantity which uses a temperature scale with a zero value at the absolute temperature zero (0 K) like the Kelvin scale, but, in contrast with it, uses the scale intervals of the Fahrenheit scale'),
('http://qudt.org/vocab/quantitykind/RateOfChange', 'Rate of Change', 'Rate of Change is a dimensionless change per unit time, such as a percentage change per second.'),
('http://qudt.org/vocab/quantitykind/RateOfChangeOfFrequency', 'Rate of Change of Frequency', 'The "Rate of Change of Frequency" is the rate of change of frequency with respect to time. It is used in power systems to describe the rate at which the frequency of the system is changing.'),
('http://qudt.org/vocab/quantitykind/RateOfRiseOfOffStateVoltage', 'Rate of Rise of Off-state Voltage', 'du/dt as time dependent change in voltage'),
('http://qudt.org/vocab/quantitykind/RateOfRiseOfVoltage', 'Rate of Rise of Voltage', NULL),
('http://qudt.org/vocab/quantitykind/Ratio', 'Ratio', NULL),
('http://qudt.org/vocab/quantitykind/RatioOfSpecificHeatCapacities', 'Ratio of Specific Heat Capacities', 'The specific heat ratio of a gas is the ratio of the specific heat at constant pressure, c_p, to the specific heat at constant volume, c_V. It is sometimes referred to as the adiabatic index, or the heat capacity ratio, or the isentropic expansion factor, or the adiabatic exponent, or the isentropic exponent.'),
('http://qudt.org/vocab/quantitykind/Reactance', 'Reactance', '"Reactance" is the opposition of a circuit element to a change of electric current or voltage, due to that element''s inductance or capacitance. A built-up electric field resists the change of voltage on the element, while a magnetic field resists the change of current. The notion of reactance is similar to electrical resistance, but they differ in several respects. Capacitance and inductance are inherent properties of an element, just like resistance.'),
('http://qudt.org/vocab/quantitykind/ReactionEnergy', 'Reaction Energy', '"Reaction Energy" in a nuclear reaction, is the sum of the kinetic energies and photon energies of the reaction products minus the sum of the kinetic and photon energies of the reactants.'),
('http://qudt.org/vocab/quantitykind/ReactiveCharge', 'Reactive Charge', 'Reactive charge is the amount of chemical unit charge, positive or negative, that reactive species donate, accept, or exchange in a chemical process. It counts stoichiometric charge units rather than particles and is expressed in equivalents or moles of charge.'),
('http://qudt.org/vocab/quantitykind/ReactiveChargePerMass', 'Reactive Charge per Mass', NULL),
('http://qudt.org/vocab/quantitykind/ReactiveEnergy', 'Reactive Energy', 'Reactive energy is the integral of reactive power over time, representing the energy exchanged between the source and reactive elements (inductors and capacitors) in an AC electrical circuit. It is commonly measured in volt-ampere reactive hours (varh or kvarh).'),
('http://qudt.org/vocab/quantitykind/ReactivePower', 'Reactive Power', '"Reactive Power", for a linear two-terminal element or two-terminal circuit, under sinusoidal conditions, is the quantity equal to the product of the apparent power S and the sine of the displacement angle ψ. The absolute value of the reactive power is equal to the non-active power. The ISO (and SI) unit for reactive power is the voltampere. The special name var and symbol var are given in IEC 60027 1.'),
('http://qudt.org/vocab/quantitykind/Reactivity', 'Reactivity', '"Reactivity" characterizes the deflection of reactor from the critical state.'),
('http://qudt.org/vocab/quantitykind/ReactorTimeConstant', 'Reactor Time Constant', 'The "Reactor Time Constant", also called the reactor period, is the time during which the neutron flux density in a reactor changes by the factor e = 2.718 (e: basis of natural logarithms), when the neutron flux density increases or decreases exponentially.'),
('http://qudt.org/vocab/quantitykind/ReciprocalElectricResistance', 'Reciprocal Electric Resistance', 'quantity whose value is inversely proportional to the resistance value'),
('http://qudt.org/vocab/quantitykind/ReciprocalEnergy', 'Reciprocal Energy', 'multiplicative inverse of energy'),
('http://qudt.org/vocab/quantitykind/ReciprocalPlaneAngle', 'Reciprocal Plane Angle', 'quantity whose value is inversely proportional to the angle value'),
('http://qudt.org/vocab/quantitykind/ReciprocalVoltage', 'Reciprocal Voltage', 'quantity whose value is inversely proportional to the voltage value'),
('http://qudt.org/vocab/quantitykind/RecombinationCoefficient', 'Recombination Coefficient', 'The "Recombination Coefficient" is the rate of recombination of positive ions with electrons or negative ions in a gas, per unit volume, divided by the product of the number of positive ions per unit volume and the number of electrons or negative ions per unit volume.'),
('http://qudt.org/vocab/quantitykind/Reflectance', 'Reflectance', 'Reflectance generally refers to the fraction of incident power that is reflected at an interface, while the term "reflection coefficient" is used for the fraction of electric field reflected. Reflectance is always a real number between zero and 1.0.'),
('http://qudt.org/vocab/quantitykind/ReflectanceFactor', 'Reflectance Factor', 'Reflectance Factor is the measure of the ability of a surface to reflect light or other electromagnetic radiation, equal to the ratio of the reflected flux to the incident flux.'),
('http://qudt.org/vocab/quantitykind/Reflectivity', 'Reflectivity', 'For homogeneous and semi-infinite materials, reflectivity is the same as reflectance. Reflectivity is the square of the magnitude of the Fresnel reflection coefficient, which is the ratio of the reflected to incident electric field; as such the reflection coefficient can be expressed as a complex number as determined by the Fresnel equations for a single layer, whereas the reflectance is always a positive real number. For layered and finite media, according to the CIE, reflectivity is distinguished from reflectance by the fact that reflectivity is a value that applies to thick reflecting objects. When reflection occurs from thin layers of material, internal reflection effects can cause the reflectance to vary with surface thickness. Reflectivity is the limit value of reflectance as the sample becomes thick; it is the intrinsic reflectance of the surface, hence irrespective of other parameters such as the reflectance of the rear surface. Another way to interpret this is that the reflectance is the fraction of electromagnetic power reflected from a specific sample, while reflectivity is a property of the material itself, which would be measured on a perfect machine if the material filled half of all space.'),
('http://qudt.org/vocab/quantitykind/RefractiveIndex', 'Refractive Index', '"refractive index" or index of refraction n of a substance (optical medium) is a dimensionless number that describes how light, or any other radiation, propagates through that medium.'),
('http://qudt.org/vocab/quantitykind/RelativeAtomicMass', 'Relative Atomic Mass', '"Relative Atomic Mass " is a dimensionless physical quantity, the ratio of the average mass of atoms of an element (from a given source) to 1/12 of the mass of an atom of carbon-12 (known as the unified atomic mass unit)'),
('http://qudt.org/vocab/quantitykind/RelativeHumidity', 'Relative Humidity', 'Relative Humidity is the ratio of the partial pressure of water vapour in an air-water mixture to the saturated vapour pressure of water at a prescribed temperature. The relative humidity of air depends not only on temperature but also on the pressure of the system of interest. Relative Humidity is also referred to as Relative Partial Pressure. Relative partial pressure is often referred to as RH and expressed in percent.'),
('http://qudt.org/vocab/quantitykind/RelativeMassConcentrationOfVapour', 'Relative Mass Concentration of Vapour', 'Relative Mass Concentration of Vapour is one of a number of Relative Concentration quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/RelativeMassDefect', 'Relative Mass Defect', 'The "Relative Mass Defect" is the mass defect between the monoisotopic mass of an element and the mass of its A + 1 or its A + 2 isotopic cluster.'),
('http://qudt.org/vocab/quantitykind/RelativeMassDensity', 'Relative Mass Density', 'Relative density, or specific gravity, is the ratio of the density (mass of a unit volume) of a substance to the density of a given reference material.'),
('http://qudt.org/vocab/quantitykind/RelativeMassExcess', 'Relative Mass Excess', 'The "Relative Mass Excess" is the mass excess between the monoisotopic mass of an element and the mass of its A + 1 or its A + 2 isotopic cluster (extrapolated from relative mass defect).'),
('http://qudt.org/vocab/quantitykind/RelativeMassRatioOfVapour', 'Relative Mass Ratio of Vapour', 'Relative Mass Ratio of Vapour is one of a number of Relative Concentration quantities defined by ISO 80000.'),
('http://qudt.org/vocab/quantitykind/RelativeMolecularMass', 'Relative Molecular Mass', '"Relative Molecular Mass " is equivalent to the numerical value of the molecular mass expressed in unified atomic mass units. The molecular mass (m) is the mass of a molecule.'),
('http://qudt.org/vocab/quantitykind/RelativePartialPressure', 'Relative Partial Pressure', NULL),
('http://qudt.org/vocab/quantitykind/RelativePressureCoefficient', 'Relative Pressure Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/RelaxationTime', 'Relaxation Time', '"Relaxation Time" is a time constant for exponential decay towards equilibrium.'),
('http://qudt.org/vocab/quantitykind/Reluctance', 'Reluctance', '"Reluctance" or magnetic resistance, is a concept used in the analysis of magnetic circuits. It is analogous to resistance in an electrical circuit, but rather than dissipating electric energy it stores magnetic energy. In likeness to the way an electric field causes an electric current to follow the path of least resistance, a magnetic field causes magnetic flux to follow the path of least magnetic reluctance. It is a scalar, extensive quantity, akin to electrical resistance.'),
('http://qudt.org/vocab/quantitykind/Repetency', 'Repetency', 'quantity whose value is inversely proportional to the length value'),
('http://qudt.org/vocab/quantitykind/ResidualResistivity', 'Residual Resistivity', '"Residual Resistivity" for metals, is the resistivity extrapolated to zero thermodynamic temperature.'),
('http://qudt.org/vocab/quantitykind/Resistance', 'Resistance', 'The electrical resistance of an object is a measure of its opposition to the passage of a steady electric current.'),
('http://qudt.org/vocab/quantitykind/ResistanceBasedInductance', 'Resistance-based Inductance', 'magnetic flux through the loop, caused by an electric current in the loop, divided by the product of this current and the resistance which prevents the flow of current'),
('http://qudt.org/vocab/quantitykind/ResistanceRatio', 'Resistance Ratio', NULL),
('http://qudt.org/vocab/quantitykind/Resistivity', 'Resistivity', '"Resistivity" is the inverse of the conductivity when this inverse exists.'),
('http://qudt.org/vocab/quantitykind/ResonanceEnergy', 'Resonance Energy', '"Resonance Energy" in a nuclear reaction, is the kinetic energy of an incident particle, in the reference frame of the target, corresponding to a resonance in a nuclear reaction.'),
('http://qudt.org/vocab/quantitykind/ResonanceEscapeProbability', 'Resonance Escape Probability', 'The "Resonance Escape Probability" is the fraction of fission neutrons that manage to slow down from fission to thermal energies without being absorbed. In an infinite medium, the probability that a neutron slowing down will traverse all or some specified portion of the range of resonance energies without being absorbed.'),
('http://qudt.org/vocab/quantitykind/ResonanceEscapeProbabilityForFission', 'Resonance Escape Probability for Fission', 'Fraction of fission neutrons that manage to slow down from fission to thermal energies without being absorbed.'),
('http://qudt.org/vocab/quantitykind/RespiratoryRate', 'Respiratory Rate', 'Respiratory rate (Vf, Rf or RR) is also known by respiration rate, pulmonary ventilation rate, ventilation rate, or breathing frequency is the number of breaths taken within a set amount of time, typically 60 seconds. A normal respiratory rate is termed eupnea, an increased respiratory rate is termed tachypnea and a lower than normal respiratory rate is termed bradypnea.'),
('http://qudt.org/vocab/quantitykind/RestEnergy', 'Rest Energy', '"Rest Energy" is the energy equivalent of the rest mass of a body, equal to the rest mass multiplied by the speed of light squared.'),
('http://qudt.org/vocab/quantitykind/RestMass', 'Rest Mass', 'The Rest Mass, the invariant mass, intrinsic mass, proper mass, or (in the case of bound systems or objects observed in their center of momentum frame) simply mass, is a characteristic of the total energy and momentum of an object or a system of objects that is the same in all frames of reference related by Lorentz transformations. The mass of a particle type X (electron, proton or neutron) when that particle is at rest. For an electron: m_e = 9,109 382 15(45) 10^-31 kg, for a proton: m_p = 1,672 621 637(83) 10^-27 kg, for a neutron: m_n = 1,674 927 211(84) 10^-27 kg. Rest mass is often denoted m_0.'),
('http://qudt.org/vocab/quantitykind/ReverberationTime', 'Reverberation Time', 'Reverberation Time is the time required for reflections of a direct sound to decay by 60 dB below the level of the direct sound.'),
('http://qudt.org/vocab/quantitykind/ReynoldsNumber', 'Reynolds Number', 'The "Reynolds Number" (Re) is a dimensionless number that gives a measure of the ratio of inertial forces to viscous forces and consequently quantifies the relative importance of these two types of forces for given flow conditions.'),
('http://qudt.org/vocab/quantitykind/RichardsonConstant', 'Richardson Constant', '"Richardson Constant" is a constant used in developing thermionic emission current density for a metal.'),
('http://qudt.org/vocab/quantitykind/RotaryShock', 'Rotary Shock', 'product of the moment of force M in a time interval multiplied by the duration of this interval'),
('http://qudt.org/vocab/quantitykind/RotaryTranslatoryMotionConversion', 'Rotary-translatory Motion Conversion', NULL),
('http://qudt.org/vocab/quantitykind/RotationalFrequency', 'Rotational Frequency', 'IfcRotationalFrequencyMeasure is a measure of the number of cycles that an item revolves in unit time. Usually measured in cycles/s.'),
('http://qudt.org/vocab/quantitykind/RotationalMass', 'Rotational Mass', '"Rotational Mass" denotes the inertia of a body with respect to angular acceleration. It is usually measured in kg*m^2.'),
('http://qudt.org/vocab/quantitykind/RotationalStiffness', 'Rotational Stiffness', 'Rotational Stiffness is the extent to which an object resists deformation in response to an applied torque.'),
('http://qudt.org/vocab/quantitykind/RotationalVelocity', 'Rotational Frequency', 'IfcRotationalFrequencyMeasure is a measure of the number of cycles that an item revolves in unit time. Usually measured in cycles/s.'),
('http://qudt.org/vocab/quantitykind/ScalarMagneticPotential', 'Scalar Magnetic Potential', '"Scalar Magnetic Potential" is the scalar potential of an irrotational magnetic field strength. The negative of the gradient of the scalar magnetic potential is the irrotational magnetic field strength. The magnetic scalar potential is not unique since any constant scalar field can be added to it without changing its gradient.'),
('http://qudt.org/vocab/quantitykind/SecondAxialMomentOfArea', 'Second Axial Moment of Area', 'The moment of inertia, also called mass moment of inertia, rotational inertia, polar moment of inertia of mass, or the angular mass is a property of a distribution of mass in space that measures its resistance to rotational acceleration about an axis.'),
('http://qudt.org/vocab/quantitykind/SecondMomentOfArea', 'Second Moment of Area', 'The second moment of area is a property of a physical object that can be used to predict its resistance to bending and deflection. The deflection of an object under load depends not only on the load, but also on the geometry of the object''s cross-section.'),
('http://qudt.org/vocab/quantitykind/SecondOrderReactionRateConstant', 'Reaction Rate Constant', 'A quantity kind that is a proportionality constant that quantifies the relationship between the molar concentrations of the reactants and the rate of a second order chemical reaction.'),
('http://qudt.org/vocab/quantitykind/SecondPolarMomentOfArea', 'Second Polar Moment of Area', 'The moment of inertia, also called mass moment of inertia, rotational inertia, polar moment of inertia of mass, or the angular mass is a property of a distribution of mass in space that measures its resistance to rotational acceleration about an axis.'),
('http://qudt.org/vocab/quantitykind/SecondRadiationConstant', 'Second Radiation Constant', 'constant in Planck''s radiation law on the dependence of the spectral density of various radiation variables on the wavelength of the electromagnetic radiation and the absolute temperature of the black radiator, derived from the product of Planck''s quantum of action times the velocity of light in relation to Boltzmann''s constant'),
('http://qudt.org/vocab/quantitykind/SectionAreaIntegral', 'Section Area Integral', 'The sectional area integral measure is typically used in torsional analysis. It is usually measured in M⁵.'),
('http://qudt.org/vocab/quantitykind/SectionModulus', 'Section Modulus', 'The Section Modulus is a geometric property for a given cross-section used in the design of beams or flexural members.'),
('http://qudt.org/vocab/quantitykind/SeebeckCoefficient', 'Seebeck Coefficient', '"Seebeck Coefficient", or thermopower, or thermoelectric power of a material is a measure of the magnitude of an induced thermoelectric voltage in response to a temperature difference across that material.'),
('http://qudt.org/vocab/quantitykind/SerumLevel', 'Serum Level', 'Concentration of a biologically active substance in blood serum, expressed in International Units per volume (e.g. IU/L). It is dimensioned as mass concentration, following the mass-equivalent treatment of the International Unit (see unit:IU and quantitykind:AmountOfBiologicallyActiveSubstance), not as amount-of-substance concentration.'),
('http://qudt.org/vocab/quantitykind/ServiceFactor', 'Service Factor', 'The value indicates the multiplier of the rated power that equipment can handle for some period of time when operating according to a manufacturer''s specified conditions; typically applicable to motors.'),
('http://qudt.org/vocab/quantitykind/ShannonDiversityIndex', 'Shannon Diversity Index', 'Information entropy applied to a collection of indiviual organisms [of selected species] in a sample area. A measure of biodiversity.'),
('http://qudt.org/vocab/quantitykind/ShearModulus', 'Shear Modulus', 'The Shear Modulus or modulus of rigidity, denoted by G, or sometimes S or μ, is defined as the ratio of shear stress to the shear strain.'),
('http://qudt.org/vocab/quantitykind/ShearStrain', 'Shear Strain', 'Shear Strain is the amount of deformation perpendicular to a given line rather than parallel to it.'),
('http://qudt.org/vocab/quantitykind/ShearStress', 'Shear Stress', 'Shear stress occurs when the force occurs in shear, or perpendicular to the normal.'),
('http://qudt.org/vocab/quantitykind/ShortRangeOrderParameter', 'Short-Range Order Parameter', '"Short-Range Order Parameter" is the fraction of the nearest-neighbor atom pairs in an Ising ferromagnet having magnetic moments in one direction, minus the fraction having magnetic moments in the opposite direction.'),
('http://qudt.org/vocab/quantitykind/SignalDetectionThreshold', 'Signal Detection Threshold', '"Signal Detection Threshold" is a dimensionless measure of the threshold for detecting a signal against a background of noise. It has no single fixed form: depending on the method it may be expressed as a detection proportion or probability (e.g. the fraction of signals correctly detected at threshold), as a sensitivity index such as the signal-detection-theory d'', or as another dimensionless ratio. In every case it is a pure number.'),
('http://qudt.org/vocab/quantitykind/SignalStrength', 'Signal Strength', 'In telecommunications, particularly in radio, signal strength refers to the magnitude of the electric field at a reference point that is a significant distance from the transmitting antenna. It may also be referred to as received signal level or field strength. Typically, it is expressed in voltage per length or signal power received by a reference antenna. High-powered transmissions, such as those used in broadcasting, are expressed in dB-millivolts per metre (dBmV/m).'),
('http://qudt.org/vocab/quantitykind/SlowingDownArea', 'Slowing-Down Area', '"Slowing-Down Area" in an infinite homogenous medium, is one-sixth of the mean square distance between the neutron source and the point where a neutron reaches a given energy.'),
('http://qudt.org/vocab/quantitykind/SlowingDownDensity', 'Slowing-Down Density', '"Slowing-Down Density" is a measure of the rate at which neutrons lose energy in a nuclear reactor through collisions; equal to the number of neutrons that fall below a given energy per unit volume per unit time.'),
('http://qudt.org/vocab/quantitykind/SlowingDownLength', 'Slowing-Down Length', '"Slowing-Down Length" is the average straight-line distance that a fast neutron will travel between its introduction into the slowing-downmedium (moderator) and thermalization.'),
('http://qudt.org/vocab/quantitykind/SoilAdsorptionCoefficient', 'Soil Adsorption Coefficient', 'A specific volume that is the ratio of the amount of substance adsorbed per unit weight of organic carbon in the soil or sediment to the concentration of the chemical in aqueous solution at equilibrium.'),
('http://qudt.org/vocab/quantitykind/SolidAngle', 'Solid Angle', 'The solid angle subtended by a surface S is defined as the surface area of a unit sphere covered by the surface S''s projection onto the sphere. A solid angle is related to the surface of a sphere in the same way an ordinary angle is related to the circumference of a circle. Since the total surface area of the unit sphere is 4*pi, the measure of solid angle will always be between 0 and 4*pi.'),
('http://qudt.org/vocab/quantitykind/SolidStateDiffusionLength', 'Diffusion Length (Solid State Physics)', '"Solid State Diffusion Length" is the average distance traveled by a particle, such as a minority carrier in a semiconductor'),
('http://qudt.org/vocab/quantitykind/SoundEnergyDensity', 'Sound Energy Density', 'Sound energy density is the time-averaged sound energy in a given volume divided by that volume. The sound energy density or sound density (symbol E or w) is an adequate measure to describe the sound field at a given point as a sound energy value.'),
('http://qudt.org/vocab/quantitykind/SoundExposure', 'Sound Exposure', 'Sound Exposure is the energy of the A-weighted sound calculated over the measurement time(s). For a given period of time, an increase of 10 dB(A) in sound pressure level corresponds to a tenfold increase in E.'),
('http://qudt.org/vocab/quantitykind/SoundExposureLevel', 'Sound Exposure Level', 'Sound Exposure Level abbreviated as SEL and LAE, is the total noise energy produced from a single noise event, expressed as a logarithmic ratio from a reference level.'),
('http://qudt.org/vocab/quantitykind/SoundIntensity', 'Sound Intensity', 'Sound intensity or acoustic intensity (I) is defined as the sound power P_a per unit area A. The usual context is the noise measurement of sound intensity in the air at a listener''s location as a sound energy quantity.'),
('http://qudt.org/vocab/quantitykind/SoundParticleAcceleration', 'Sound Particle Acceleration', 'In a compressible sound transmission medium - mainly air - air particles get an accelerated motion: the particle acceleration or sound acceleration with the symbol a in m/s2. In acoustics or physics, acceleration (symbol: a) is defined as the rate of change (or time derivative) of velocity.'),
('http://qudt.org/vocab/quantitykind/SoundParticleDisplacement', 'Sound Particle Displacement', 'Sound Particle Displacement is the nstantaneous displacement of a particle in a medium from what would be its position in the absence of sound waves.'),
('http://qudt.org/vocab/quantitykind/SoundParticleVelocity', 'Sound Particle Velocity', 'Sound Particle velocity is the velocity v of a particle (real or imagined) in a medium as it transmits a wave. In many cases this is a longitudinal wave of pressure as with sound, but it can also be a transverse wave as with the vibration of a taut string. When applied to a sound wave through a medium of a fluid like air, particle velocity would be the physical speed of a parcel of fluid as it moves back and forth in the direction the sound wave is travelling as it passes.'),
('http://qudt.org/vocab/quantitykind/SoundPower', 'Sound Power', 'Sound power or acoustic power P_a is a measure of sonic energy E per time t unit. It is measured in watts and can be computed as sound intensity (I) times area (A).'),
('http://qudt.org/vocab/quantitykind/SoundPowerLevel', 'Sound Power Level', 'Sound Power Level abbreviated as SWL expresses sound power more practically as a relation to the threshold of hearing - 1 picoW - in a logarithmic scale.'),
('http://qudt.org/vocab/quantitykind/SoundPressure', 'Sound Pressure', 'Sound Pressure is the difference between instantaneous total pressure and static pressure.'),
('http://qudt.org/vocab/quantitykind/SoundPressureLevel', 'Sound Pressure Level', 'Sound pressure level (SPL) or sound level is a logarithmic measure of the effective sound pressure of a sound relative to a reference value. It is measured in decibels (dB) above a standard reference level.'),
('http://qudt.org/vocab/quantitykind/SoundReductionIndex', 'Sound Reduction Index', 'The Sound Reduction Index is used to measure the level of sound insulation provided by a structure such as a wall, window, door, or ventilator.'),
('http://qudt.org/vocab/quantitykind/SoundVolumeVelocity', 'Sound Volume Velocity', 'Sound Volume Velocity is the product of particle velocity v and the surface area S through which an acoustic wave of frequency f propagates. Also, the surface integral of the normal component of the sound particle velocity over the cross-section (through which the sound propagates). It is used to calculate acoustic impedance.'),
('http://qudt.org/vocab/quantitykind/SourceVoltage', 'Source Voltage', 'The quantity kind Source Voltage, also referred to as Source Tension is the voltage between the two terminals of a voltage source when there is no electric current through the source. The name electromotive force with the abbreviation EMF and the symbol E is deprecated.'),
('http://qudt.org/vocab/quantitykind/SourceVoltageBetweenSubstances', 'Source Voltage Between Substances', '"Source Voltage Between Substances" is the source voltage between substance a and b.'),
('http://qudt.org/vocab/quantitykind/SpatialSummationFunction', 'Spatial Summation Function', '"Spatial Summation Function" is he ability to produce a composite signal from the signals coming into the eyes from different directions.'),
('http://qudt.org/vocab/quantitykind/SpecificAcousticImpedance', 'Specific Acoustic Impedance', 'Specific Acoustic Impedance at a point in a medium is the complex quotient of the sound pressure p by the particle velocity v in the direction of wave propagation: z = p / v. Its SI unit is the pascal second per metre (Pa·s/m), also called the rayl.'),
('http://qudt.org/vocab/quantitykind/SpecificActivity', 'Specific Activity', 'The "Specific Activity" is the number of decays per unit time of a radioactive sample. The SI unit of radioactive activity is the becquerel (Bq), in honor of the scientist Henri Becquerel.'),
('http://qudt.org/vocab/quantitykind/SpecificElectricCharge', 'Specific Electric Charge', 'Electric charge (often capacity in the context of electrochemical cells) relativ to the mass (often only active components). capacity'),
('http://qudt.org/vocab/quantitykind/SpecificElectricCurrent', 'Specific Electrical Current', '"Specific Electric Current" is a measure to specify the applied current relative to a corresponding mass. This measure is often used for standardization within electrochemistry.'),
('http://qudt.org/vocab/quantitykind/SpecificEnergy', 'Specific Energy', 'Specific Energy is defined as the energy per unit mass. Common metric units are J/kg. It is an intensive property. Contrast this with energy, which is an extensive property. There are two main types of specific energy: potential energy and specific kinetic energy. Others are the gray and sievert, which are measures for the absorption of radiation. The concept of specific energy applies to a particular or theoretical way of extracting useful energy from the material considered that is usually implied by context. These intensive properties are each symbolized by using the lower case letter of the symbol for the corresponding extensive property, which is symbolized by a capital letter. For example, the extensive thermodynamic property enthalpy is symbolized by H; specific enthalpy is symbolized by h.'),
('http://qudt.org/vocab/quantitykind/SpecificEnergyImparted', 'Specific Energy Imparted', 'The "Specific Energy Imparted", is the energy imparted to an element of irradiated matter divided by the mass, dm, of that element.'),
('http://qudt.org/vocab/quantitykind/SpecificEnthalpy', 'Specific Enthalpy', 'Specific Enthalpy is enthalpy per mass of substance involved. Specific enthalpy is denoted by a lower case h, with dimension of energy per mass (SI unit: joule/kg). In thermodynamics, enthalpy is the sum of the internal energy U and the product of pressure p and volume V of a system: H = U + pV. The internal energy U and the work term pV have dimension of energy, in SI units this is joule; the extensive (linear in size) quantity H has the same dimension.'),
('http://qudt.org/vocab/quantitykind/SpecificEntropy', 'Specific Entropy', '"Specific Entropy" is entropy per unit of mass.'),
('http://qudt.org/vocab/quantitykind/SpecificGibbsEnergy', 'Specific Gibbs Energy', 'Energy has corresponding intensive (size-independent) properties for pure materials. A corresponding intensive property is "Specific Gibbs Energy, which is Gibbs Energy per mass of substance involved. Specific Gibbs Energy" is denoted by a lower case g, with dimension of energy per mass (SI unit: joule/kg).'),
('http://qudt.org/vocab/quantitykind/SpecificHeatCapacity', 'Specific Heat Capacity', 'Specific Heat Capacity of a solid or liquid is defined as the heat required to raise unit mass of substance by one degree of temperature. This is Heat Capacity divided by Mass. Note that there are corresponding molar quantities.'),
('http://qudt.org/vocab/quantitykind/SpecificHeatCapacityAtConstantPressure', 'Specific Heat Capacity at Constant Pressure', 'Specific heat at a constant pressure.'),
('http://qudt.org/vocab/quantitykind/SpecificHeatCapacityAtConstantVolume', 'Specific Heat Capacity at Constant Volume', 'Specific heat per constant volume.'),
('http://qudt.org/vocab/quantitykind/SpecificHeatCapacityAtSaturation', 'Specific Heat Capacity at Saturation', 'Specific heat per constant volume.'),
('http://qudt.org/vocab/quantitykind/SpecificHeatPressure', 'Specific Heat Pressure', 'Specific heat at a constant pressure.'),
('http://qudt.org/vocab/quantitykind/SpecificHeatVolume', 'Specific Heat Volume', 'Specific heat per constant volume.'),
('http://qudt.org/vocab/quantitykind/SpecificHeatsRatio', 'Specific Heats Ratio', 'The ratio of specific heats, for the exhaust gases adiabatic gas constant, is the relative amount of compression/expansion energy that goes into temperature T versus pressure P can be characterized by the heat capacity ratio: γC_P/C_V, where C_P is the specific heat (also called heat capacity) at constant pressure, while C_V is the specific heat at constant volume.'),
('http://qudt.org/vocab/quantitykind/SpecificHelmholtzEnergy', 'Specific Helmholtz Energy', 'Specific Helmholtz Energy is a "corresponding intensive property", which is Helmholz Energy per mass of substance involved. Energy has corresponding intensive (size-independent) properties for pure materials. Specific Helmholz Energy is denoted by a lower case u, with dimension of energy per mass (SI unit: joule/kg).'),
('http://qudt.org/vocab/quantitykind/SpecificHumidity', 'Specific Humidity', 'Specific humidity (or moisture content) is the ratio of the mass of water vapour to the total mass of the air parcel. It is approximately equal to the mixing ratio, defined as the ratio of the mass of water vapour to the mass of dry air in the same parcel.'),
('http://qudt.org/vocab/quantitykind/SpecificImpulse', 'Specific Impulse', 'The impulse produced by a rocket divided by the mass mp of propellant consumed. Specific impulse I_sp is a widely used measure of performance for chemical, nuclear, and electric rockets. It is usually given in seconds for both U.S. Customary and International System (SI) units. The impulse produced by a rocket is the thrust force F times its duration t in seconds. I_sp is the thrust per unit mass flowrate, but with g_o, is the thrust per weight flowrate. The specific impulse is given by the equation: I_sp = F/mg_o.'),
('http://qudt.org/vocab/quantitykind/SpecificImpulseByMass', 'Specific Impulse by Mass', NULL),
('http://qudt.org/vocab/quantitykind/SpecificImpulseByWeight', 'Specific Impulse by Weight', 'Specific impulse expressed on a weight basis: the impulse produced divided by the weight of propellant consumed, I_sp = F / (m g_0), giving a result in seconds. This is the convention quantitykind:SpecificImpulse already adopts. Contrast the mass basis, F / m, which yields an effective exhaust velocity in metres per second and is carried by quantitykind:SpecificThrust; the two differ by the factor g_0.'),
('http://qudt.org/vocab/quantitykind/SpecificInternalEnergy', 'Specific Internal Energy', 'Energy has corresponding intensive (size-independent) properties for pure materials. A corresponding intensive property is specific internal energy, which is energy per mass of substance involved. Specific internal energy is denoted by a lower case u, with dimension of energy per mass (SI unit: joule/kg).'),
('http://qudt.org/vocab/quantitykind/SpecificModulus', 'Specific Modulus', 'Specific modulus is a materials property consisting of the elastic modulus per mass density of a material. It is also known as the stiffness to weight ratio or specific stiffness . High specific modulus materials find wide application in aerospace applications where minimum structural weight is required. The dimensional analysis yields units of distance squared per time squared.'),
('http://qudt.org/vocab/quantitykind/SpecificOpticalRotationalAbility', 'Specific Optical Rotational Ability', 'material-specific quantity, which results as angle of rotation of a substance for a defined wavelength and a defined temperature from the relation: quotient of measured angle of rotation divided by the mass concentration and the radiographed distance'),
('http://qudt.org/vocab/quantitykind/SpecificOpticalRotatoryPower', 'Specific Optical Rotatory Power', 'The "Specific Optical Rotatory Power" Angle of optical rotation divided by the optical path length through the medium and by the mass concentration of the substance giving the specific optical rotatory power.'),
('http://qudt.org/vocab/quantitykind/SpecificPower', 'Specific Power', 'Specific power, also known as power-to-weight ratio, is the amount of power output per unit mass of the power source. It is generally used to measure the performance of that power source. The higher the ratio, the more power a system produces relative to its weight. It''s commonly used in the automotive and aerospace industries to compare the performance of different engines. It''s generally measured in watts per kilogram (W/kg) or horsepower per pound (hp/lb).'),
('http://qudt.org/vocab/quantitykind/SpecificSurfaceArea', 'Specific Surface Area', 'Specific surface area (SSA) is a property of solids defined as the total surface area (SA) of a material per unit mass, (with units of m²/kg or m²/g). It is a physical value that can be used to determine the type and properties of a material (e.g. soil or snow). It has a particular importance for adsorption, heterogeneous catalysis, and reactions on surfaces.'),
('http://qudt.org/vocab/quantitykind/SpecificThrust', 'Specific Thrust', 'Specific impulse (usually abbreviated Isp) is a way to describe the efficiency of rocket and jet engines. It represents the force with respect to the amount of propellant used per unit time.[1] If the "amount" of propellant is given in terms of mass (such as kilograms), then specific impulse has units of velocity. If it is given in terms of Earth-weight (such as kiloponds), then specific impulse has units of time. The conversion constant between the two versions of specific impulse is g. The higher the specific impulse, the lower the propellant flow rate required for a given thrust, and in the case of a rocket the less propellant is needed for a given delta-v per the Tsiolkovsky rocket equation.'),
('http://qudt.org/vocab/quantitykind/SpecificVolume', 'Specific Volume', '"Specific Volume" (ν) is the volume occupied by a unit of mass of a material. It is equal to the inverse of density.'),
('http://qudt.org/vocab/quantitykind/SpecificWeight', 'Specific Weight', 'The specific weight, also known as the unit weight is a volume-specific quantity defined as the weight per unit volume of a material. Note that weight is defined as a force, distinct from mass.'),
('http://qudt.org/vocab/quantitykind/SpectralAngularCrossSection', 'Spectral Angular Cross-section', '"Spectral Angular Cross-section" is the cross-section for ejecting or scattering a particle into an elementary cone with energy E in an energy interval, divided by the solid angle dΩ of that cone and the range dE of that interval.'),
('http://qudt.org/vocab/quantitykind/SpectralConcentrationOfRadiantEnergyDensity', 'Spectral Concentration of Radiant Energy Density', 'energy distribution of the instantaneous value of radiant energy in relation to the volume of the propagation medium'),
('http://qudt.org/vocab/quantitykind/SpectralConcentrationOfVibrationalModes', 'Spectral Concentration of Vibrational Modes (in Terms of Angular Frequency)', 'number of vibrational modes in an infinitesimal interval of angular frequency, divided by the size of that interval and by volume'),
('http://qudt.org/vocab/quantitykind/SpectralCrossSection', 'Spectral Cross-section', '"Spectral Cross-section" is the cross-section for a process in which the energy of the ejected or scattered particle is in an interval of energy, divided by the range dE of this interval.'),
('http://qudt.org/vocab/quantitykind/SpectralDensityOfVibrationalModes', 'Spectral Density of Vibrational Modes', 'The number of vibrational modes in an infinitesimal interval of angular frequency, divided by the size of that interval and by volume.'),
('http://qudt.org/vocab/quantitykind/SpectralEmittance', 'Measurement Unit of Spectral Emittance', 'Spectral Emittance is a radiometry term for the power per unit area of electromagnetic radiation unit wavelength emerging from a surface.'),
('http://qudt.org/vocab/quantitykind/SpectralIrradiance', 'Measurement Unit of Spectral Irradiance', 'Spectral Irradiance is a radiometry term for the power per unit area of electromagnetic radiation per unit wavelength incident at a surface.'),
('http://qudt.org/vocab/quantitykind/SpectralLuminousEfficiency', 'Spectral Luminous Efficiency', 'The Spectral Luminous Efficiency is a measure of how well a light source produces visible light. It is the ratio of luminous flux to power. A common choice is to choose units such that the maximum possible efficacy, 683 lm/W, corresponds to an efficiency of 100%.'),
('http://qudt.org/vocab/quantitykind/SpectralRadiance', 'Measurement Unit of Spectral Radiance', 'Spectral Radiance is a radiometry term for the power per unit area of electromagnetic radiation per unit wavelength per unit solid angle emerging from a surface.'),
('http://qudt.org/vocab/quantitykind/SpectralRadiantEnergyDensity', 'Spectral Radiant Energy Density', '"Spectral Radiant Energy Density" is the spectral concentration of radiant energy density (in terms of wavelength), or the spectral radiant energy density (in terms of wave length).'),
('http://qudt.org/vocab/quantitykind/SpectralRadiantEnergyDensityInTermsOfWavelength', 'Spectral Radiant Energy Density in Terms of Wavelength', NULL),
('http://qudt.org/vocab/quantitykind/Speed', 'Speed', 'Speed is the magnitude of velocity.'),
('http://qudt.org/vocab/quantitykind/SpeedOfLight', 'Speed of Light', 'The quantity kind Speed of Light is the speed of electomagnetic waves in a given medium.'),
('http://qudt.org/vocab/quantitykind/SpeedOfSound', 'Speed of Sound', 'The speed of sound is the distance travelled during a unit of time by a sound wave propagating through an elastic medium.'),
('http://qudt.org/vocab/quantitykind/SpeedRatio', 'Speed Ratio', 'Speed ratio generally refers to the ratio of the rotational speeds of two interconnected rotating components, but it sometimes relates linear speeds.'),
('http://qudt.org/vocab/quantitykind/SphericalIlluminance', 'Illuminance', 'Spherical illuminance is equal to quotient of the total luminous flux Φ_v incident on a small sphere by the cross section area of that sphere.'),
('http://qudt.org/vocab/quantitykind/Spin', 'Spin', 'In quantum mechanics and particle physics "Spin" is an intrinsic form of angular momentum carried by elementary particles, composite particles (hadrons), and atomic nuclei.'),
('http://qudt.org/vocab/quantitykind/SpinQuantumNumber', 'Spin Quantum Number', 'The "Spin Quantum Number" describes the spin (intrinsic angular momentum) of the electron within that orbital, and gives the projection of the spin angular momentum S along the specified axis'),
('http://qudt.org/vocab/quantitykind/SquareEnergy', 'Square Energy', NULL),
('http://qudt.org/vocab/quantitykind/SquareTime', 'Square Time', NULL),
('http://qudt.org/vocab/quantitykind/StandardAbsoluteActivity', 'Standard Absolute Activity', 'The "Standard Absolute Activity" is proportional to the absoulte activity of the pure substance B at the same temperature and pressure multiplied by the standard pressure.'),
('http://qudt.org/vocab/quantitykind/StandardChemicalPotential', 'Standard Chemical Potential', '"Standard Chemical Potential" is the value of the chemical potential at standard conditions'),
('http://qudt.org/vocab/quantitykind/StandardGravitationalParameter', 'Standard Gravitational Parameter', 'In celestial mechanics the standard gravitational parameter of a celestial body is the product of the gravitational constant G and the mass M of the body. Expressed as μ = G · M. The SI units of the standard gravitational parameter are m^3s^-2.'),
('http://qudt.org/vocab/quantitykind/StateDensity', 'State Density', 'function of energy in a solid, determined by the number of permissible quantum states in the energy range between E and E+dE per volume of material of this solid'),
('http://qudt.org/vocab/quantitykind/StateDensityAsExpressionOfAngularFrequency', 'State Density as Expression of Angular Frequency', 'ratio between number of vibration modes in an infinitesimal interval of the angular frequency and the length of this interval and the volume'),
('http://qudt.org/vocab/quantitykind/StateOfCharge', 'State of Charge', '""State of Charge",quantifies the remaining capacity available in a battery at a given time and in relation to a given state of ageing.'),
('http://qudt.org/vocab/quantitykind/StaticFriction', 'Static Friction', 'Static friction is friction between two or more solid objects that are not moving relative to each other. For example, static friction can prevent an object from sliding down a sloped surface.'),
('http://qudt.org/vocab/quantitykind/StaticFrictionCoefficient', 'Static Friction Coefficient', 'Static friction is friction between two or more solid objects that are not moving relative to each other. For example, static friction can prevent an object from sliding down a sloped surface.'),
('http://qudt.org/vocab/quantitykind/StaticPressure', 'Static Pressure', '"Static Pressure" is the pressure at a nominated point in a fluid. Every point in a steadily flowing fluid, regardless of the fluid speed at that point, has its own static pressure P, dynamic pressure q, and total pressure P_0. The total pressure is the sum of the dynamic and static pressures, that is P_0 = P + q.'),
('http://qudt.org/vocab/quantitykind/StatisticalWeight', 'Statistical Weight', 'A "Statistical Weight" is the relative probability (possibly unnormalized) of a particular feature of a state.'),
('http://qudt.org/vocab/quantitykind/StochasticProcess', 'Stochastic Process', 'In probability theory, a stochastic process, or sometimes random process is a collection of random variables; this is often used to represent the evolution of some random value, or system, over time. This is the probabilistic counterpart to a deterministic process (or deterministic system).'),
('http://qudt.org/vocab/quantitykind/StoichiometricNumber', 'Stoichiometric Number', 'Chemical reactions, as macroscopic unit operations, consist of simply a very large number of elementary reactions, where a single molecule reacts with another molecule. As the reacting molecules (or moieties) consist of a definite set of atoms in an integer ratio, the ratio between reactants in a complete reaction is also in integer ratio. A reaction may consume more than one molecule, and the "Stoichiometric Number" counts this number, defined as positive for products (added) and negative for reactants (removed).'),
('http://qudt.org/vocab/quantitykind/Strain', 'Strain', 'In any branch of science dealing with materials and their behaviour, strain is the geometrical expression of deformation caused by the action of stress on a physical body. Strain is calculated by first assuming a change between two body states: the beginning state and the final state. Then the difference in placement of two points in this body in those two states expresses the numerical value of strain. Strain therefore expresses itself as a change in size and/or shape. [Wikipedia] Strain is commonly used as a synonym for LinearStrain.'),
('http://qudt.org/vocab/quantitykind/StrainEnergyDensity', 'Strain Energy Density', 'Defined as the ''work done'' for a given strain, that is the area under the stress-strain curve after a specified eation. Source(s): http://www.prepol.com/product-range/product-subpages/terminology'),
('http://qudt.org/vocab/quantitykind/StrainEnergyReleaseRate', 'Strain Energy Release Rate', 'In fracture mechanics, the energy release rate, G, is the rate at which energy is transformed as a material undergoes fracture. Mathematically, the energy release rate is expressed as the decrease in total potential energy per increase in fracture surface area, and is thus expressed in terms of energy per unit area.'),
('http://qudt.org/vocab/quantitykind/Stress', 'Stress', 'Stress is a measure of the average amount of force exerted per unit area of a surface within a deformable body on which internal forces act. In other words, it is a measure of the intensity or internal distribution of the total internal forces acting within a deformable body across imaginary surfaces. These internal forces are produced between the particles in the body as a reaction to external forces applied on the body. Stress is defined as Stress = F/A.'),
('http://qudt.org/vocab/quantitykind/StressIntensityFactor', 'Stress Intensity Factor', 'In fracture mechanics, the stress intensity factor (K) is used to predict the stress state ("stress intensity") near the tip of a crack or notch caused by a remote load or residual stresses. It is a theoretical construct usually applied to a homogeneous, linear elastic material and is useful for providing a failure criterion for brittle materials, and is a critical technique in the discipline of damage tolerance. The concept can also be applied to materials that exhibit small-scale yielding at a crack tip.'),
('http://qudt.org/vocab/quantitykind/StressOpticCoefficient', 'Stress-Optic Coefficient', 'When a ray of light passes through a photoelastic material, its electromagnetic wave components are resolved along the two principal stress directions and each component experiences a different refractive index due to the birefringence. The difference in the refractive indices leads to a relative phase retardation between the two components. Assuming a thin specimen made of isotropic materials, where two-dimensional photoelasticity is applicable, the magnitude of the relative retardation is given by the stress-optic law Δ=((2πt)/λ)C(σ₁-σ₂), where Δ is the induced retardation, C is the stress-optic coefficient, t is the specimen thickness, λ is the vacuum wavelength, and σ₁ and σ₂ are the first and second principal stresses, respectively.'),
('http://qudt.org/vocab/quantitykind/StructuralEfficiency', 'Structural Efficiency', 'Structural efficiency is a function of the weight of structure to the afforded vehicle''s strength.'),
('http://qudt.org/vocab/quantitykind/StructureFactor', 'Structure Factor', '"Structure Factor" is a mathematical description of how a material scatters incident radiation.'),
('http://qudt.org/vocab/quantitykind/SunProtectionFactorOfAProduct', 'Sun Protection Factor of a Product', NULL),
('http://qudt.org/vocab/quantitykind/SuperconductionTransitionTemperature', 'Superconduction Transition Temperature', '"Superconduction Transition Temperature" is the critical thermodynamic temperature of a superconductor.'),
('http://qudt.org/vocab/quantitykind/SuperconductorEnergyGap', 'Superconductor Energy Gap', '"Superconductor Energy Gap" is the width of the forbidden energy band in a superconductor.'),
('http://qudt.org/vocab/quantitykind/SurfaceActivityDensity', 'Surface Activity Density', 'The "Surface Activity Density" is undefined.'),
('http://qudt.org/vocab/quantitykind/SurfaceCoefficientOfHeatTransfer', 'Surface Coefficient of Heat Transfer', NULL),
('http://qudt.org/vocab/quantitykind/SurfaceDensity', 'Surface Density', 'The area density (also known as areal density, surface density, or superficial density) of a two-dimensional object is calculated as the mass per unit area.'),
('http://qudt.org/vocab/quantitykind/SurfaceRelatedVolumeFlow', 'Surface-related Volume Flow', 'quotient of the volume of a material, which passes through a specified surface, and the therefor required time divided by this specified area'),
('http://qudt.org/vocab/quantitykind/SurfaceRelatedVolumeFlowRate', 'Surface‑related Volume Flow Rate', NULL),
('http://qudt.org/vocab/quantitykind/SurfaceTension', 'Surface Tension', '"Surface Tension" is a contractive tendency of the surface of a liquid that allows it to resist an external force.'),
('http://qudt.org/vocab/quantitykind/SurgeImpedanceOfTheMedium', 'Surge Impedance of the Medium', 'in a mechanical system the area-related quotient of a force affecting to a point divided by the resulting component of the particle velocity in direction of the force'),
('http://qudt.org/vocab/quantitykind/Susceptance', 'Susceptance', '"Susceptance" is the imaginary part of admittance. The inverse of admittance is impedance and the real part of admittance is conductance.'),
('http://qudt.org/vocab/quantitykind/SymbolTransmissionRate', 'Symbol Transmission Rate', 'rate, at which a symbol, consisting of one or more bits, is transmitted per second'),
('http://qudt.org/vocab/quantitykind/SystolicBloodPressure', 'Systolic Blood Pressure', 'The pressure of blood in the arteries which rises to a maximum as blood is pumped out by the left ventricle (systole) and drops to a minimum in diastole. The systolic/diastolic pressure is normally ~120/80 mmHg in a young adult.'),
('http://qudt.org/vocab/quantitykind/Temperature', 'Temperature', 'Temperature is a physical property of matter that quantitatively expresses the common notions of hot and cold. Objects of low temperature are cold, while various degrees of higher temperatures are referred to as warm or hot. Heat spontaneously flows from bodies of a higher temperature to bodies of lower temperature, at a rate that increases with the temperature difference and the thermal conductivity.'),
('http://qudt.org/vocab/quantitykind/TemperatureAmountOfSubstance', 'Temperature Amount of Substance', NULL),
('http://qudt.org/vocab/quantitykind/TemperatureBasedAmountOfSubstanceConcentration', 'Temperature-based Amount-of-substance Concentration', 'ratio of material concentration divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedDensity', 'Temperature-based Density', 'ratio of density divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedDynamicViscosity', 'Temperature-based Dynamic Viscosity', 'ratio of dynamic viscosity, divided by temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedKinematicViscosity', 'Temperature-based Kinematic Viscosity', 'ratio of dynamic viscosity and the density of a material, divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedLength', 'Temperature-based Length', 'ratio of length divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedMass', 'Temperature-based Mass', 'ratio of mass divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedMassFlowRate', 'Temperature-based Mass Flow Rate', 'ratio of mass flow divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedQuantity', 'Temperature-based Quantity', NULL),
('http://qudt.org/vocab/quantitykind/TemperatureBasedVelocity', 'Temperature-based Velocity', 'ratio of velocity divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureBasedVolumeFlowRate', 'Temperature-based Volume Flow Rate', 'ratio of volume flow divided by the related temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureDifference', 'Temperature Difference', 'Temperature difference (Delta T) is the difference of temperatures between two measuring points'),
('http://qudt.org/vocab/quantitykind/TemperatureGradient', 'Temperature Gradient', 'The temperature gradient measures the difference of a temperature per length, as for instance used in an external wall or its layers. It is usually measured in K/m.'),
('http://qudt.org/vocab/quantitykind/TemperaturePerMagneticFluxDensity', 'Temperature per Magnetic Flux Density', NULL),
('http://qudt.org/vocab/quantitykind/TemperaturePerSquareTime', 'Temperature per Square Time', NULL),
('http://qudt.org/vocab/quantitykind/TemperaturePerTime', 'Temperature per Time', NULL),
('http://qudt.org/vocab/quantitykind/TemperatureRateOfChange', 'Temperature Rate of Change', 'The "Temperature Rate of Change" measures the difference of a temperature per time (positive: rise, negative: fall), as for instance used with heat sensors. It is for example measured in K/s.'),
('http://qudt.org/vocab/quantitykind/TemperatureRatio', 'Temperature Ratio', NULL),
('http://qudt.org/vocab/quantitykind/TemperatureRelatedMolarMass', 'Temperature-related Molar Mass', 'molarity (mass of a substance in relation to the amount of this substance) divided by temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureRelatedVolume', 'Temperature-related Volume', 'volume divided by temperature'),
('http://qudt.org/vocab/quantitykind/TemperatureVariance', 'Temperature Variance', 'Variance for temperature data.'),
('http://qudt.org/vocab/quantitykind/TemporalSummationFunction', 'Temporal Summation Function', '"Temporal Summation Function" is the ability of the human eye to produce a composite signal from the signals coming into an eye during a short time interval.'),
('http://qudt.org/vocab/quantitykind/Tension', 'Tension', NULL),
('http://qudt.org/vocab/quantitykind/ThermalAdmittance', 'Thermal Admittance', 'The heat transfer coefficient is also known as thermal admittance in the sense that the material may be seen as admitting heat to flow.'),
('http://qudt.org/vocab/quantitykind/ThermalCapacitance', 'Thermal Capacitance', 'ratio between the supplied quantity of heat and the temperature range caused by the supplied quantity of heat'),
('http://qudt.org/vocab/quantitykind/ThermalCoefficientOfLinearExpansion', 'Thermal Coefficient of Linear Expansion', 'median relative change in length over a specific length of the test piece, divided by the temperature range caused by it'),
('http://qudt.org/vocab/quantitykind/ThermalConductance', 'Thermal Conductance', 'This quantity is also called "Heat Transfer Coefficient".'),
('http://qudt.org/vocab/quantitykind/ThermalConductivity', 'Thermal Conductivity', 'In physics, thermal conductivity, k (also denoted as λ), is the property of a material''s ability to conduct heat. It appears primarily in Fourier''s Law for heat conduction and is the areic heat flow rate divided by temperature gradient.'),
('http://qudt.org/vocab/quantitykind/ThermalDiffusionFactor', 'Thermal Diffusion Factor', 'Thermal diffusion is a phenomenon in which a temperature gradient in a mixture of fluids gives rise to a flow of one constituent relative to the mixture as a whole. in the context of the equation that describes thermal diffusion, the "Thermal Diffusion Factor" is .'),
('http://qudt.org/vocab/quantitykind/ThermalDiffusionRatio', 'Thermal Diffusion Ratio', 'The "Thermal Diffusion Ratio" is proportional to the product of the component concentrations.'),
('http://qudt.org/vocab/quantitykind/ThermalDiffusionRatioCoefficient', 'Thermal Diffusion Coefficient', NULL),
('http://qudt.org/vocab/quantitykind/ThermalDiffusivity', 'Thermal Diffusivity', 'In heat transfer analysis, thermal diffusivity (usually denoted α but a, κ,k, and D are also used) is the thermal conductivity divided by density and specific heat capacity at constant pressure. The formula is: α = k / ρ c_p, where k is thermal conductivity (W/(μ · K)), ρ is density (kg/m^3), and c_p is specific heat capacity (J/(kg · K)) .The denominator ρ c_p, can be considered the volumetric heat capacity (J/(m^3 · K)).'),
('http://qudt.org/vocab/quantitykind/ThermalEfficiency', 'Thermal Efficiency', 'Thermal efficiency is a dimensionless performance measure of a thermal device such as an internal combustion engine, a boiler, or a furnace. The input to the device is heat, or the heat-content of a fuel that is consumed. The desired output is mechanical work, or heat, or possibly both.'),
('http://qudt.org/vocab/quantitykind/ThermalEnergy', 'Thermal Energy', '"Thermal Energy" is the portion of the thermodynamic or internal energy of a system that is responsible for the temperature of the system. From a macroscopic thermodynamic description, the thermal energy of a system is given by its constant volume specific heat capacity C(T), a temperature coefficient also called thermal capacity, at any given absolute temperature (T): U_thermal = C(T) · T.'),
('http://qudt.org/vocab/quantitykind/ThermalEnergyLength', 'Thermal Energy Length', NULL),
('http://qudt.org/vocab/quantitykind/ThermalExpansionCoefficient', 'Thermal Expansion Coefficient', 'The "Thermal Expansion Coefficient" is a measure of the thermal expansion coefficient of a material, which expresses its elongation (as a ratio) per temperature difference. It is usually measured in 1/K. A positive elongation per (positive) rise of temperature is expressed by a positive value.'),
('http://qudt.org/vocab/quantitykind/ThermalInertia', 'Measurement Unit of Thermal Inertia', 'Thermal inertia is a term used to describe the observed delays in a body''s temperature response during heat transfers'),
('http://qudt.org/vocab/quantitykind/ThermalInsulance', 'Thermal Insulance', 'Thermal Insulance is the reduction of heat transfer (the transfer of thermal energy between objects of differing temperature) between objects in thermal contact or in range of radiative influence. In building technology, this quantity is often called Thermal Resistance, with the symbol R.'),
('http://qudt.org/vocab/quantitykind/ThermalInsulation', 'Thermal Insulation', 'temperature difference between two surfaces divided by areic heat flow rate in the direction of the temperature gradient'),
('http://qudt.org/vocab/quantitykind/ThermalPower', 'Thermal Power', 'Thermal power is the rate at which thermal energy is transferred or converted, expressed as energy per unit time. It characterizes the heating or cooling power output of thermal systems such as heat pumps, boilers, and chillers.'),
('http://qudt.org/vocab/quantitykind/ThermalResistance', 'Thermal Resistance', 'Thermal Resistance is a heat property and a measure of a temperature difference by which an object or material resists a heat flow (heat per time unit or thermal resistance). Thermal resistance is the reciprocal thermal conductance. the thermodynamic temperature difference divided by heat flow rate. Thermal resistance R has the units m^2 · K/W.'),
('http://qudt.org/vocab/quantitykind/ThermalResistivity', 'Thermal Resistivity', 'The reciprocal of thermal conductivity is thermal resistivity, measured in kelvin-metres per watt (K · m/W).'),
('http://qudt.org/vocab/quantitykind/ThermalTransmittance', 'Thermal Transmittance', 'Thermal transmittance is the rate of transfer of heat through matter. The thermal transmittance of a material (such as insulation or concrete) or an assembly (such as a wall or window) is expressed as a U-value. The concept of thermal transmittance is closely related to that of thermal resistance. The thermal resistance of a structure is the reciprocal of its thermal transmittance.'),
('http://qudt.org/vocab/quantitykind/ThermalUtilizationFactor', 'Thermal Utilization Factor', 'The "Thermal Utilization Factor" in an infinite medium, is the ratio of the number of thermal absorbed in a fissionable nuclide or in a nuclear fuel, as specified, to the total number of thermal neutrons absorbed.'),
('http://qudt.org/vocab/quantitykind/ThermalUtilizationFactorForFission', 'Thermal Utilization Factor for Fission', 'Probability that a neutron that gets absorbed does so in the fuel material.'),
('http://qudt.org/vocab/quantitykind/ThermodynamicCriticalMagneticFluxDensity', 'Thermodynamic Critical Magnetic Flux Density', '"Thermodynamic Critical Magnetic Flux Density" is the maximum magnetic field strength below which a material remains superconducting.'),
('http://qudt.org/vocab/quantitykind/ThermodynamicEnergy', 'Thermodynamic Energy', NULL),
('http://qudt.org/vocab/quantitykind/ThermodynamicEntropy', 'Thermodynamic Entropy', 'Thermodynamic Entropy is a measure of the unavailability of a system’s energy to do work. It is a measure of the randomness of molecules in a system and is central to the second law of thermodynamics and the fundamental thermodynamic relation, which deal with physical processes and whether they occur spontaneously. The dimensions of entropy are energy divided by temperature, which is the same as the dimensions of Boltzmann''s constant (kB) and heat capacity. The SI unit of entropy is joule per kelvin. [Wikipedia]'),
('http://qudt.org/vocab/quantitykind/ThermodynamicTemperature', 'Thermodynamic Temperature', 'Thermodynamic temperature is the absolute measure of temperature and is one of the principal parameters of thermodynamics. Temperature is a physical property of matter that quantitatively expresses the common notions of hot and cold. In thermodynamics, in a system of which the entropy is considered as an independent externally controlled variable, absolute, or thermodynamic temperature is defined as the derivative of the internal energy with respect to the entropy. This is a base quantity in the International System of Quantities, ISQ, on which the International System of Units, SI, is based.'),
('http://qudt.org/vocab/quantitykind/Thickness', 'Thickness', '"Thickness" is the the smallest of three dimensions: length, width, thickness.'),
('http://qudt.org/vocab/quantitykind/ThomsonCoefficient', 'Thomson Coefficient', '"Thomson Coefficient" represents Thomson heat power developed, divided by the electric current and the temperature difference.'),
('http://qudt.org/vocab/quantitykind/Thrust', 'Thrust', 'Thrust is a reaction force described quantitatively by Newton''s Second and Third Laws. When a system expels or accelerates mass in one direction the accelerated mass will cause a proportional but opposite force on that system.'),
('http://qudt.org/vocab/quantitykind/ThrustCoefficient', 'Thrust Coefficient', 'The thrust force of a jet-propulsion engine per unit of frontal area per unit of incompressible dynamic pressure'),
('http://qudt.org/vocab/quantitykind/ThrustToMassRatio', 'Thrust to Mass Ratio', NULL),
('http://qudt.org/vocab/quantitykind/ThrustToWeightRatio', 'Thrust to Weight Ratio', 'Thrust-to-weight ratio is a ratio of thrust to weight of a rocket, jet engine, propeller engine, or a vehicle propelled by such an engine. It is a dimensionless quantity and is an indicator of the performance of the engine or vehicle.'),
('http://qudt.org/vocab/quantitykind/Tilt', 'Tilt', 'The angle between an object''s orientation vector relative to a reference frame. In the context of architecture, this would refer to the angle between the ground and the face of a surface.'),
('http://qudt.org/vocab/quantitykind/Time', 'Time', 'Time is a basic component of the measuring system used to sequence events, to compare the durations of events and the intervals between them, and to quantify the motions of objects.'),
('http://qudt.org/vocab/quantitykind/TimeAveragedSoundIntensity', 'Time Averaged Sound Intensity', 'Sound intensity or acoustic intensity (I) is defined as the sound power P_a per unit area A. The usual context is the noise measurement of sound intensity in the air at a listener''s location as a sound energy quantity.'),
('http://qudt.org/vocab/quantitykind/TimePerCount', 'Time per Count', 'Time passed between N occurrences of a recurring phenomenon.'),
('http://qudt.org/vocab/quantitykind/TimeRatio', 'Time Ratio', NULL),
('http://qudt.org/vocab/quantitykind/TimeRelatedLogERatio', 'Time-related Logarithmic Ratio to Base e', 'The natural (base-e) logarithm of the ratio of the value of a given quantity to the value of a reference quantity of the same type, divided by the related time. Its corresponding unit is the neper per second.'),
('http://qudt.org/vocab/quantitykind/TimeTemperature', 'Time Temperature', NULL),
('http://qudt.org/vocab/quantitykind/Torque', 'Torque', 'In physics, a torque (τ) is a vector that measures the tendency of a force to rotate an object about some axis. The magnitude of a torque is defined as force times its lever arm. Just as a force is a push or a pull, a torque can be thought of as a twist. The SI unit for torque is newton meters (N m). In U.S. customary units, it is measured in foot pounds (ft lbf) (also known as "pounds feet"). Mathematically, the torque on a particle (which has the position r in some reference frame) can be defined as the cross product: τ = r x F where, r is the particle''s position vector relative to the fulcrum F is the force acting on the particles, or, more generally, torque can be defined as the rate of change of angular momentum: τ = dL/dt where, L is the angular momentum vector t stands for time.'),
('http://qudt.org/vocab/quantitykind/TorqueConstant', 'Torque Constant', 'product of magnetic induction, number of turns per unit length, and the area enclosed by the coil corresponding to the gradient of the curve representing the ratio between the torque of the motor and the current'),
('http://qudt.org/vocab/quantitykind/TorquePerAngle', 'Torque per Angle', NULL),
('http://qudt.org/vocab/quantitykind/TorquePerLength', 'Torque per Length', NULL),
('http://qudt.org/vocab/quantitykind/TorsionalRigidity', 'Torsional Rigidity', NULL),
('http://qudt.org/vocab/quantitykind/TorsionalSpringConstant', 'Torsional Spring Constant', 'A torsional spring constant is a measure of the stiffness of a torsional spring, which is a type of spring that experiences twisting or torque rather than compression or extension. It is typically measured in newton-meters per radian (N·m/rad) and is used to calculate the amount of torque required to twist a spring a certain amount. It is related to the spring''s geometry, material properties, and manufacturing process.'),
('http://qudt.org/vocab/quantitykind/TotalAngularMomentum', 'Total Angular Momentum', '"Total Angular Momentum" combines both the spin and orbital angular momentum of all particles and fields. In atomic and nuclear physics, orbital angular momentum is usually denoted by l or L instead of Λ. The magnitude of J is quantized so that J^2 = ħ^2 j(j + 1), where j is the total angular momentum quantum number.'),
('http://qudt.org/vocab/quantitykind/TotalAngularMomentumQuantumNumber', 'Total Angular Momentum Quantum Number', 'The "Total Angular Quantum Number" describes the magnitude of total angular momentum J, where j refers to a specific particle and J is used for the whole system.'),
('http://qudt.org/vocab/quantitykind/TotalAtomicStoppingPower', 'Total Atomic Stopping Power', 'The "Total Atomic Stopping Power" for an ionizing particle passing through an element, is the particle''s energy loss per atom within a unit area normal to the particle''s path; equal to the linear energy transfer (energy loss per unit path length) divided by the number of atoms per unit volume.'),
('http://qudt.org/vocab/quantitykind/TotalCrossSection', 'Total Cross-section', '"Total Cross-section" is related to the absorbance of the light intensity through Beer-Lambert''s law. It is the sum of all cross-sections corresponding to the various reactions or processes between an incident particle of specified type and energy and a target particle.'),
('http://qudt.org/vocab/quantitykind/TotalCurrent', 'Total Current', '"Total Current" is the sum of the electric current that is flowing through a surface and the displacement current.'),
('http://qudt.org/vocab/quantitykind/TotalCurrentDensity', 'Total Current Density', '"Total Current Density" is the sum of the electric current density and the displacement current density.'),
('http://qudt.org/vocab/quantitykind/TotalIonization', 'Total Ionization', '"Total Ionization" by a particle, total mean charge, divided by the elementary charge, e, of all positive ions produced by an ionizing charged particle along its entire path and along the paths of any secondary charged particles.'),
('http://qudt.org/vocab/quantitykind/TotalLinearStoppingPower', 'Total Linear Stopping Power', 'The "Total Linear Stopping Power" is defined as the average energy loss of the particle per unit path length.'),
('http://qudt.org/vocab/quantitykind/TotalMassStoppingPower', 'Total Mass Stopping Power', 'If a substance is compared in gaseous and solid form, then the linear stopping powers of the two states are very different just because of the different density. One therefore often divides S(E) by the density of the material to obtain the "Mass Stopping Power". The mass stopping power then depends only very little on the density of the material.'),
('http://qudt.org/vocab/quantitykind/TotalPressure', 'Total Pressure', 'The total pressure is the sum of the dynamic and static pressures, that is P_0 = P + q.'),
('http://qudt.org/vocab/quantitykind/TotalRadiance', 'Total Radiance', 'ratio between the differential change in the energy fluence dΨ and the time interval dt: ψ = dΨ / dt; the total radiance is identical to the product of the particle flux density and the average energy of the particles'),
('http://qudt.org/vocab/quantitykind/TouchThresholds', 'Touch Thresholds', '"Touch Thresholds" is an umbrella term for the thresholds of sensitivity of the skin to touch, vibration and other mechanical stimuli. It has no single dimension: a concrete touch threshold specializes into a force for light-touch detection (e.g. von Frey monofilaments, in millinewtons), a length for vibration-detection amplitude or two-point separation, or a pressure, depending on the stimulus and method.'),
('http://qudt.org/vocab/quantitykind/TrafficIntensity', 'Traffic Intensity', 'number of all simultaneously occupied units in a particular group of units'),
('http://qudt.org/vocab/quantitykind/TransmissionRatioBetweenRotationAndTranslation', 'Transmission Ratio Between Rotation and Translation', 'relationship between rotational and longitudinal movements as a measure of how an angle is converted into a linear path'),
('http://qudt.org/vocab/quantitykind/Transmittance', 'Transmittance', 'Transmittance is the fraction of incident light (electromagnetic radiation) at a specified wavelength that passes through a sample.'),
('http://qudt.org/vocab/quantitykind/TransmittanceDensity', 'Transmittance Density', 'Transmittance is the fraction of incident light (electromagnetic radiation) at a specified wavelength that passes through a sample.'),
('http://qudt.org/vocab/quantitykind/Turbidity', 'Turbidity', 'Turbidity is the cloudiness or haziness of a fluid, or of air, caused by individual particles (suspended solids) that are generally invisible to the naked eye, similar to smoke in air. Turbidity in open water is often caused by phytoplankton and the measurement of turbidity is a key test of water quality. The higher the turbidity, the higher the risk of the drinkers developing gastrointestinal diseases, especially for immune-compromised people, because contaminants like virus or bacteria can become attached to the suspended solid. The suspended solids interfere with water disinfection with chlorine because the particles act as shields for the virus and bacteria. Similarly suspended solids can protect bacteria from UV sterilisation of water. Fluids can contain suspended solid matter consisting of particles of many different sizes. While some suspended material will be large enough and heavy enough to settle rapidly to the bottom container if a liquid sample is left to stand (the settleable solids), very small particles will settle only very slowly or not at all if the sample is regularly agitated or the particles are colloidal. These small solid particles cause the liquid to appear turbid.'),
('http://qudt.org/vocab/quantitykind/Turns', 'Turns', '"Turns" is the number of turns in a winding.'),
('http://qudt.org/vocab/quantitykind/Unbalance', 'Unbalance', 'unsteady rotation of a body resulting from an anxious distribution of mass, expressed as the product of radius and related mass'),
('http://qudt.org/vocab/quantitykind/Unknown', 'Unknown', 'Placeholder value used for reference from units where it is not clear what a given unit is a measure of.'),
('http://qudt.org/vocab/quantitykind/UpperCriticalMagneticFluxDensity', 'Upper Critical Magnetic Flux Density', '"Upper Critical Magnetic Flux Density" for type II superconductors, is the threshold magnetic flux density for disappearance of bulk superconductivity.'),
('http://qudt.org/vocab/quantitykind/VacuumThrust', 'Vacuum Thrust', NULL),
('http://qudt.org/vocab/quantitykind/VapourPermeability', 'Vapour Permeability', 'The moisture transmission rate of a material is referred to as its "permeability".'),
('http://qudt.org/vocab/quantitykind/VapourPermeance', 'Vapour Permeance', 'A material''s "permeance", is dependent on thickness much like the R-value in heat transmission. Dividing the permeability of a material by its thickness gives the material''s permeance. Permeance is the number that should be used to compare various products in regard to moisture transmission resistance.'),
('http://qudt.org/vocab/quantitykind/VapourPressure', 'Vapour Pressure', 'A pressure that is the one exerted by a substance vapour in thermodynamic equilibrium with either its solid or liquid phase at a given temperature in a closed system.'),
('http://qudt.org/vocab/quantitykind/Velocity', 'Velocity', 'In kinematics, velocity is the speed of an object and a specification of its direction of motion. Speed describes only how fast an object is moving, whereas velocity gives both how fast and in what direction the object is moving.'),
('http://qudt.org/vocab/quantitykind/VentilationRatePerFloorArea', 'Ventilation Rate per Floor Area', 'Ventilation Rate is often expressed by the volumetric flowrate of outdoor air introduced to a building. However, ASHRAE now recommends ventilation rates dependent upon floor area.'),
('http://qudt.org/vocab/quantitykind/VerticalVelocity', 'Vertical Velocity', 'The rate at which a body moves upwards at an angle of 90 degrees to the ground. It is the component of a projectile''s velocity which is concerned with lifting the projectile.'),
('http://qudt.org/vocab/quantitykind/VibrationalDensityOfStates', 'Vibrational Density of States', '"Density of States" is the number of vibrational modes in an infinitesimal interval of angular frequency divided by the range of that interval and by volume.'),
('http://qudt.org/vocab/quantitykind/VideoFrameRate', 'Video Frame Rate', 'Frame rate (also known as frame frequency) is the frequency (rate) at which an imaging device produces unique consecutive images called frames. The term applies equally well to computer graphics, video cameras, film cameras, and motion capture systems. Frame rate is most often expressed in frames per second (FPS) and is also expressed in progressive scan monitors as hertz (Hz).'),
('http://qudt.org/vocab/quantitykind/Viscosity', 'Viscosity', 'Viscosity is a measure of the resistance of a fluid which is being deformed by either shear stress or extensional stress. In general terms it is the resistance of a liquid to flow, or its "thickness". Viscosity describes a fluid''s internal resistance to flow and may be thought of as a measure of fluid friction. [Wikipedia]. In general conversation or in non-scientific contexts, if someone refers to the viscosity of a fluid, they''re likely talking about its dynamic (or absolute) viscosity. However, in engineering or scientific contexts, it''s essential to clarify which type of viscosity is being discussed, as the interpretation and use of the data may differ depending on whether one is talking about dynamic or kinematic viscosity.'),
('http://qudt.org/vocab/quantitykind/VisibleRadiantEnergy', 'Visible Radiant Energy', '"Visible Radiant Energy", also known as luminous energy, is the energy of electromagnetic waves. It is energy of the particles that are emitted, transferred, or received as radiation.'),
('http://qudt.org/vocab/quantitykind/VisionThresholds', 'Vision Thresholds', '"Vision Thresholds" is the thresholds of sensitivity of the eye.'),
('http://qudt.org/vocab/quantitykind/Voltage', 'Voltage', 'Voltage, also referred to as Electric Tension, is the difference between electrical potentials of two points. For an electric field within a medium, U_ab = - ∫_r_a^r_b E . dr, where E is electric field strength. For an irrotational electric field, the voltage is independent of the path between the two points a and b.'),
('http://qudt.org/vocab/quantitykind/VoltageImbalance', 'Voltage Imbalance', 'Voltage imbalance is the percentage deviation of individual phase voltages from the average voltage across phases in a polyphase electrical system.'),
('http://qudt.org/vocab/quantitykind/VoltagePhasor', 'Voltage Phasor', '"Voltage Phasor" is a representation of voltage as a sinusoidal integral quantity using a complex quantity whose argument is equal to the initial phase and whose modulus is equal to the root-mean-square value. A phasor is a constant complex number, usually expressed in exponential form, representing the complex amplitude (magnitude and phase) of a sinusoidal function of time. Phasors are used by electrical engineers to simplify computations involving sinusoids, where they can often reduce a differential equation problem to an algebraic one.'),
('http://qudt.org/vocab/quantitykind/VoltageRatio', 'Voltage Ratio', NULL),
('http://qudt.org/vocab/quantitykind/Volume', 'Volume', 'The volume of a solid object is the three-dimensional concept of how much space it occupies, often quantified numerically. One-dimensional figures (such as lines) and two-dimensional shapes (such as squares) are assigned zero volume in the three-dimensional space.'),
('http://qudt.org/vocab/quantitykind/VolumeDensityOfCharge', 'Volume Density of Charge', 'volume density of the electric charge Q present in a volume V'),
('http://qudt.org/vocab/quantitykind/VolumeFlowRate', 'Volume Flow Rate', 'Volumetric Flow Rate, (also known as volume flow rate, rate of fluid flow or volume velocity) is the volume of fluid which passes through a given surface per unit time.'),
('http://qudt.org/vocab/quantitykind/VolumeFlowRatio', 'Volume Flow Ratio', 'Volume flow ratio is commonly used in fluid dynamics and engineering, referring to the ratio of the flow rates of two or more fluid streams within a system. In HVAC systems, the flow ratio could compare the amount of fresh air introduced to the amount of recirculated air.'),
('http://qudt.org/vocab/quantitykind/VolumeFraction', 'Volume Fraction', '"Volume Fraction" is the volume of a constituent divided by the volume of all constituents of the mixture prior to mixing. Volume fraction is also called volume concentration in ideal solutions where the volumes of the constituents are additive (the volume of the solution is equal to the sum of the volumes of its ingredients).'),
('http://qudt.org/vocab/quantitykind/VolumePerArea', 'Volume per Unit Area', NULL),
('http://qudt.org/vocab/quantitykind/VolumePerTime', 'Volume per Time', NULL),
('http://qudt.org/vocab/quantitykind/VolumeStrain', 'Volume Strain', 'Volume, or volumetric, Strain, or dilatation (the relative variation of the volume) is the trace of the tensor ϑ.'),
('http://qudt.org/vocab/quantitykind/VolumeThermalExpansion', 'Volume Thermal Expansion', 'When the temperature of a substance changes, the energy that is stored in the intermolecular bonds between atoms changes. When the stored energy increases, so does the length of the molecular bonds. As a result, solids typically expand in response to heating and contract on cooling; this dimensional response to temperature change is expressed by its coefficient of thermal expansion. Different coefficients of thermal expansion can be defined for a substance depending on whether the expansion is measured by: * linear thermal expansion * area thermal expansion * volumetric thermal expansion These characteristics are closely related. The volumetric thermal expansion coefficient can be defined for both liquids and solids. The linear thermal expansion can only be defined for solids, and is common in engineering applications. Some substances expand when cooled, such as freezing water, so they have negative thermal expansion coefficients. [Wikipedia]'),
('http://qudt.org/vocab/quantitykind/VolumetricBitDensity', 'Volumic Bit Density', NULL),
('http://qudt.org/vocab/quantitykind/VolumetricElectricCharge', 'Volumic Electric Charge', NULL),
('http://qudt.org/vocab/quantitykind/VolumetricEntityDensity', 'Volumetric Entity Density', 'quantity whose value is inversely proportional to the volume value'),
('http://qudt.org/vocab/quantitykind/VolumetricFlux', 'Volumetric Flux', 'In fluid dynamics, the volumetric flux is the rate of volume flow across a unit area (m3·s−1·m−2).[Wikipedia]'),
('http://qudt.org/vocab/quantitykind/VolumetricHeatCapacity', 'Volumetric Heat Capacity', 'Volumetric Heat Capacity (VHC), also termed volume-specific heat capacity, describes the ability of a given volume of a substance to store internal energy while undergoing a given temperature change, but without undergoing a phase transition. It is different from specific heat capacity in that the VHC is a per unit volume measure of the relationship between thermal energy and temperature of a material, while the specific heat is a per unit mass measure (or occasionally per molar quantity of the material).'),
('http://qudt.org/vocab/quantitykind/VolumetricOutputPower', 'Volumic Output Power', NULL),
('http://qudt.org/vocab/quantitykind/VolumicAmountOfSubstance', 'Volumic Amount of Substance', 'quantity proportional to the number of single particles of a defined type present in a given sample, divided by the related volume of this sample'),
('http://qudt.org/vocab/quantitykind/VolumicDataQuantity', 'Volumic Data Quantity', 'amount of data, which is usually dependent on the respective complexity of the information or its coding procedure, divided by the related volume'),
('http://qudt.org/vocab/quantitykind/VolumicElectromagneticEnergy', 'Volumic Electromagnetic Energy', 'Volumic Electromagnetic Energy, also known as the Electromagnetic Energy Density, is the energy associated with an electromagnetic field, per unit volume of the field.'),
('http://qudt.org/vocab/quantitykind/VolumicOutput', 'Volumic Output', 'ratio released power divided by volume'),
('http://qudt.org/vocab/quantitykind/Vorticity', 'Vorticity', 'In the simplest sense, vorticity is the tendency for elements of a fluid to "spin." More formally, vorticity can be related to the amount of "circulation" or "rotation" (or more strictly, the local angular rate of rotation) in a fluid. The average vorticity in a small region of fluid flow is equal to the circulation C around the boundary of the small region, divided by the area A of the small region. Mathematically, vorticity is a vector field and is defined as the curl of the velocity field.'),
('http://qudt.org/vocab/quantitykind/WarmReceptorThreshold', 'Warm Receptor Threshold', '"Warm Receptor Threshold" is the threshold of warm-sensitive free nerve-ending.'),
('http://qudt.org/vocab/quantitykind/WarpingConstant', 'Warping Constant', 'The "Warping Constant" is a measure for the warping constant or warping resistance of a cross section under torsional loading. It is usually measured in m⁶.'),
('http://qudt.org/vocab/quantitykind/WarpingMoment', 'Warping Moment', 'The warping moment measure is a measure for the warping moment, which occurs in warping torsional analysis. It is usually measured in kNm².'),
('http://qudt.org/vocab/quantitykind/WaterHorsepower', 'Water Horsepower', 'No pump can convert all of its mechanical power into water power. Mechanical power is lost in the pumping process due to friction losses and other physical losses. It is because of these losses that the horsepower going into the pump has to be greater than the water horsepower leaving the pump. The efficiency of any given pump is defined as the ratio of the water horsepower out of the pump compared to the mechanical horsepower into the pump.'),
('http://qudt.org/vocab/quantitykind/WaterSolubility', 'Water Solubility', 'An amount of substance per unit volume that is the concentration of a saturated solution expressed as the ratio of the solute concentration over the volume of water. A substance''s solubility fundamentally depends on several physical and chemical properties of the solution as well as the environment it is in.'),
('http://qudt.org/vocab/quantitykind/WaterVapourDiffusionCoefficient', 'Water Vapour Diffusion Coefficient', 'The Water vapour diffusion coefficient describes how easy vapour diffusion happens in a given material.'),
('http://qudt.org/vocab/quantitykind/WaterVapourPermeability', 'Water Vapour Permeability', 'mass of water vapour passing a surface divided by the area of this surface, the pressure difference, and the corresponding time'),
('http://qudt.org/vocab/quantitykind/Wavelength', 'Wavelength', 'For a monochromatic wave, "wavelength" is the distance between two successive points in a direction perpendicular to the wavefront where at a given instant the phase differs by 2π. The wavelength of a sinusoidal wave is the spatial period of the wave—the distance over which the wave''s shape repeats. The SI unit of wavelength is the meter.'),
('http://qudt.org/vocab/quantitykind/Wavenumber', 'Wavenumber', '"Wavenumber" is the spatial frequency of a wave - the number of waves that exist over a specified distance. More formally, it is the reciprocal of the wavelength. It is also the magnitude of the wave vector. Light passing through different media keeps its frequency, but not its wavelength or wavenumber. The unit for wavenumber commonly used in spectroscopy is centimetre to power minus one, PER-CM, rather than metre to power minus one, PER-M.'),
('http://qudt.org/vocab/quantitykind/WebTime', 'Web Time', NULL),
('http://qudt.org/vocab/quantitykind/WebTimeAveragePressure', 'Web Time Average Pressure', NULL),
('http://qudt.org/vocab/quantitykind/WebTimeAverageThrust', 'Web Time Average Thrust', NULL),
('http://qudt.org/vocab/quantitykind/Weight', 'Weight', 'The force with which a body is attracted toward an astronomical body. Or, the product of the mass of a body and the acceleration acting on a body. In a dynamic situation, the weight can be a multiple of that under resting conditions. Weight also varies on other planets in accordance with their gravity.'),
('http://qudt.org/vocab/quantitykind/WetBulbTemperature', 'Wet Bulb Temperature', 'the temperature of a parcel of air cooled to saturation (100% relative humidity) by the evaporation of water into it, with the latent heat supplied by the parcel.'),
('http://qudt.org/vocab/quantitykind/Width', 'Width', '"Width" is the middle of three dimensions: length, width, thickness.'),
('http://qudt.org/vocab/quantitykind/Work', 'Work', 'A force is said to do Work when it acts on a body so that there is a displacement of the point of application, however small, in the direction of the force. The concepts of work and energy are closely tied to the concept of force because an applied force can do work on an object and cause a change in energy. Energy is defined as the ability to do work. Work is done on an object when an applied force moves it through a distance. Kinetic energy is the energy of an object in motion. The net work is equal to the change in kinetic energy.'),
('http://qudt.org/vocab/quantitykind/WorkFunction', 'Work Function', '"Work Function" is the energy difference between an electron at rest at infinity and an electron at a certain energy level. The minimum energy (usually measured in electronvolts) needed to remove an electron from a solid to a point immediately outside the solid surface (or energy needed to move an electron from the Fermi level into vacuum).'),
('http://qudt.org/vocab/quantitykind/ZenithAngle', 'Zenith Angle', 'Zenith angle is the angle measured from the zenith (the point directly overhead) downward to a celestial object or direction of interest. It is the complement of the elevation (altitude) angle.')
