('http://qudt.org/vocab/unit/FT-PER-SEC2', 'Foot per Square Second', 'ft/s²', 'A73'),
('http://qudt.org/vocab/unit/FT3', 'Cubic Foot', 'ft³', 'FTQ'),
('http://qudt.org/vocab/unit/FT3-PER-HR', 'Cubic Foot per Hour', 'ft³/h', '2K'),
('http://qudt.org/vocab/unit/FT3-PER-MIN', 'Cubic Foot per Minute', 'ft³/min', '2L'),
('http://qudt.org/vocab/unit/GM', 'Gram', 'g', 'GRM'),
('http://qudt.org/vocab/unit/GM-PER-M3', 'Gram per Cubic Metre', 'g/m³', 'A93'),
('http://qudt.org/vocab/unit/HR', 'Hour', 'h', 'HUR'),
('http://qudt.org/vocab/unit/HZ', 'Hertz', 'Hz', 'HTZ'),
('http://qudt.org/vocab/unit/IN', 'Inch', 'in', 'INH'),
('http://qudt.org/vocab/unit/IN-PER-MIN', 'Inch per Minute', 'in/min', 'M63'),
('http://qudt.org/vocab/unit/IN-PER-REV', 'Inch per Revolution', 'in/rev', 'H57'),
('http://qudt.org/vocab/unit/IN-PER-SEC', 'Inch per Second', 'in/s', 'IU'),
('http://qudt.org/vocab/unit/IN-PER-SEC2', 'Inch per Square Second', 'in/s²', 'IV'),
('http://qudt.org/vocab/unit/IN2', 'Square Inch', 'in²', 'INK'),
('http://qudt.org/vocab/unit/J', 'Joule', 'J', 'JOU'),
('http://qudt.org/vocab/unit/K', 'Kelvin', 'K', 'KEL'),
('http://qudt.org/vocab/unit/KiloGM', 'Kilogram', 'kg', 'KGM'),
('http://qudt.org/vocab/unit/KiloW', 'Kilowatt', 'kW', 'KWT'),
('http://qudt.org/vocab/unit/KiloW-HR', 'Kilowatt Hour', 'kW·h', 'KWH'),
('http://qudt.org/vocab/unit/L', 'Litre', 'L', 'LTR'),
